// بيانات السور
Object.assign(quranData, {
    33: { // سورة الأحزاب
        name: "الأحزاب",
        basmalaTafsir: ``,
        verses: [
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمًا", tafsir: `` },
            { text: "وَٱتَّبِعْ مَا يُوحَىٰٓ إِلَيْكَ مِن رَّبِّكَ إِنَّ ٱللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا", tafsir: `` },
            { text: "وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا", tafsir: `` },
            { text: "مَّا جَعَلَ ٱللَّهُ لِرَجُلٍ مِّن قَلْبَيْنِ فِى جَوْفِهِۦ وَمَا جَعَلَ أَزْوَٰجَكُمُ ٱلَّٰٓـِٔى تُظَٰهِرُونَ مِنْهُنَّ أُمَّهَٰتِكُمْ وَمَا جَعَلَ أَدْعِيَآءَكُمْ أَبْنَآءَكُمْ ذَٰلِكُمْ قَوْلُكُم بِأَفْوَٰهِكُمْ وَٱللَّهُ يَقُولُ ٱلْحَقَّ وَهُوَ يَهْدِى ٱلسَّبِيلَ", tafsir: `` },
            { text: "ٱدْعُوهُمْ لِـَٔابَآئِهِمْ هُوَ أَقْسَطُ عِندَ ٱللَّهِ فَإِن لَّمْ تَعْلَمُوٓا۟ ءَابَآءَهُمْ فَإِخْوَٰنُكُمْ فِى ٱلدِّينِ وَمَوَٰلِيكُمْ وَلَيْسَ عَلَيْكُمْ جُنَاحٌ فِيمَآ أَخْطَأْتُم بِهِۦ وَلَٰكِن مَّا تَعَمَّدَتْ قُلُوبُكُمْ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا", tafsir: `` },
            { text: "ٱلنَّبِىُّ أَوْلَىٰ بِٱلْمُؤْمِنِينَ مِنْ أَنفُسِهِمْ وَأَزْوَٰجُهُۥٓ أُمَّهَٰتُهُمْ وَأُو۟لُوا۟ ٱلْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ فِى كِتَٰبِ ٱللَّهِ مِنَ ٱلْمُؤْمِنِينَ وَٱلْمُهَٰجِرِينَ إِلَّآ أَن تَفْعَلُوٓا۟ إِلَىٰٓ أَوْلِيَآئِكُم مَّعْرُوفًا كَانَ ذَٰلِكَ فِى ٱلْكِتَٰبِ مَسْطُورًا", tafsir: `` },
            { text: "وَإِذْ أَخَذْنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمْ وَمِنكَ وَمِن نُّوحٍ وَإِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبْنِ مَرْيَمَ وَأَخَذْنَا مِنْهُم مِّيثَٰقًا غَلِيظًا", tafsir: `` },
            { text: "لِّيَسْـَٔلَ ٱلصَّٰدِقِينَ عَن صِدْقِهِمْ وَأَعَدَّ لِلْكَٰفِرِينَ عَذَابًا أَلِيمًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ نِعْمَةَ ٱللَّهِ عَلَيْكُمْ إِذْ جَآءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا وَكَانَ ٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا", tafsir: `` },
            { text: "إِذْ جَآءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ ٱلْأَبْصَٰرُ وَبَلَغَتِ ٱلْقُلُوبُ ٱلْحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠", tafsir: `` },
            { text: "هُنَالِكَ ٱبْتُلِىَ ٱلْمُؤْمِنُونَ وَزُلْزِلُوا۟ زِلْزَالًا شَدِيدًا", tafsir: `` },
            { text: "وَإِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا", tafsir: `` },
            { text: "وَإِذْ قَالَت طَّآئِفَةٌ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ لَا مُقَامَ لَكُمْ فَٱرْجِعُوا۟ وَيَسْتَـْٔذِنُ فَرِيقٌ مِّنْهُمُ ٱلنَّبِىَّ يَقُولُونَ إِنَّ بُيُوتَنَا عَوْرَةٌ وَمَا هِىَ بِعَوْرَةٍ إِن يُرِيدُونَ إِلَّا فِرَارًا", tafsir: `` },
            { text: "وَلَوْ دُخِلَتْ عَلَيْهِم مِّنْ أَقْطَارِهَا ثُمَّ سُئِلُوا۟ ٱلْفِتْنَةَ لَـَٔاتَوْهَا وَمَا تَلَبَّثُوا۟ بِهَآ إِلَّا يَسِيرًا", tafsir: `` },
            { text: "وَلَقَدْ كَانُوا۟ عَٰهَدُوا۟ ٱللَّهَ مِن قَبْلُ لَا يُوَلُّونَ ٱلْأَدْبَٰرَ وَكَانَ عَهْدُ ٱللَّهِ مَسْـُٔولًا", tafsir: `` },
            { text: "قُل لَّن يَنفَعَكُمُ ٱلْفِرَارُ إِن فَرَرْتُم مِّنَ ٱلْمَوْتِ أَوِ ٱلْقَتْلِ وَإِذًا لَّا تُمَتَّعُونَ إِلَّا قَلِيلًا", tafsir: `` },
            { text: "قُلْ مَن ذَا ٱلَّذِى يَعْصِمُكُم مِّنَ ٱللَّهِ إِنْ أَرَادَ بِكُمْ سُوٓءًا أَوْ أَرَادَ بِكُمْ رَحْمَةً وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا", tafsir: `` },
            { text: "قَدْ يَعْلَمُ ٱللَّهُ ٱلْمُعَوِّقِينَ مِنكُمْ وَٱلْقَآئِلِينَ لِإِخْوَٰنِهِمْ هَلُمَّ إِلَيْنَا وَلَا يَأْتُونَ ٱلْبَأْسَ إِلَّا قَلِيلًا", tafsir: `` },
            { text: "أَشِحَّةً عَلَيْكُمْ فَإِذَا جَآءَ ٱلْخَوْفُ رَأَيْتَهُمْ يَنظُرُونَ إِلَيْكَ تَدُورُ أَعْيُنُهُمْ كَٱلَّذِى يُغْشَىٰ عَلَيْهِ مِنَ ٱلْمَوْتِ فَإِذَا ذَهَبَ ٱلْخَوْفُ سَلَقُوكُم بِأَلْسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلْخَيْرِ أُو۟لَٰٓئِكَ لَمْ يُؤْمِنُوا۟ فَأَحْبَطَ ٱللَّهُ أَعْمَٰلَهُمْ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا", tafsir: `` },
            { text: "يَحْسَبُونَ ٱلْأَحْزَابَ لَمْ يَذْهَبُوا۟ وَإِن يَأْتِ ٱلْأَحْزَابُ يَوَدُّوا۟ لَوْ أَنَّهُم بَادُونَ فِى ٱلْأَعْرَابِ يَسْـَٔلُونَ عَنْ أَنۢبَآئِكُمْ وَلَوْ كَانُوا۟ فِيكُم مَّا قَٰتَلُوٓا۟ إِلَّا قَلِيلًا", tafsir: `` },
            { text: "لَّقَدْ كَانَ لَكُمْ فِى رَسُولِ ٱللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُوا۟ ٱللَّهَ وَٱلْيَوْمَ ٱلْـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِيرًا", tafsir: `` },
            { text: "وَلَمَّا رَءَا ٱلْمُؤْمِنُونَ ٱلْأَحْزَابَ قَالُوا۟ هَٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥ وَمَا زَادَهُمْ إِلَّآ إِيمَٰنًا وَتَسْلِيمًا", tafsir: `` },
            { text: "مِّنَ ٱلْمُؤْمِنِينَ رِجَالٌ صَدَقُوا۟ مَا عَٰهَدُوا۟ ٱللَّهَ عَلَيْهِ فَمِنْهُم مَّن قَضَىٰ نَحْبَهُۥ وَمِنْهُم مَّن يَنتَظِرُ وَمَا بَدَّلُوا۟ تَبْدِيلًا", tafsir: `` },
            { text: "لِّيَجْزِىَ ٱللَّهُ ٱلصَّٰدِقِينَ بِصِدْقِهِمْ وَيُعَذِّبَ ٱلْمُنَٰفِقِينَ إِن شَآءَ أَوْ يَتُوبَ عَلَيْهِمْ إِنَّ ٱللَّهَ كَانَ غَفُورًا رَّحِيمًا", tafsir: `` },
            { text: "وَرَدَّ ٱللَّهُ ٱلَّذِينَ كَفَرُوا۟ بِغَيْظِهِمْ لَمْ يَنَالُوا۟ خَيْرًا وَكَفَى ٱللَّهُ ٱلْمُؤْمِنِينَ ٱلْقِتَالَ وَكَانَ ٱللَّهُ قَوِيًّا عَزِيزًا", tafsir: `` },
            { text: "وَأَنزَلَ ٱلَّذِينَ ظَٰهَرُوهُم مِّنْ أَهْلِ ٱلْكِتَٰبِ مِن صَيَاصِيهِمْ وَقَذَفَ فِى قُلُوبِهِمُ ٱلرُّعْبَ فَرِيقًا تَقْتُلُونَ وَتَأْسِرُونَ فَرِيقًا", tafsir: `` },
            { text: "وَأَوْرَثَكُمْ أَرْضَهُمْ وَدِيَٰرَهُمْ وَأَمْوَٰلَهُمْ وَأَرْضًا لَّمْ تَطَـُٔوهَا وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ إِن كُنتُنَّ تُرِدْنَ ٱلْحَيَوٰةَ ٱلدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا", tafsir: `` },
            { text: "وَإِن كُنتُنَّ تُرِدْنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلْـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلْمُحْسِنَٰتِ مِنكُنَّ أَجْرًا عَظِيمًا", tafsir: `` },
            { text: "يَٰنِسَآءَ ٱلنَّبِىِّ مَن يَأْتِ مِنكُنَّ بِفَٰحِشَةٍ مُّبَيِّنَةٍ يُضَٰعَفْ لَهَا ٱلْعَذَابُ ضِعْفَيْنِ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا", tafsir: `` },
            { text: "وَمَن يَقْنُتْ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعْمَلْ صَٰلِحًا نُّؤْتِهَآ أَجْرَهَا مَرَّتَيْنِ وَأَعْتَدْنَا لَهَا رِزْقًا كَرِيمًا", tafsir: `` },
            { text: "يَٰنِسَآءَ ٱلنَّبِىِّ لَسْتُنَّ كَأَحَدٍ مِّنَ ٱلنِّسَآءِ إِنِ ٱتَّقَيْتُنَّ فَلَا تَخْضَعْنَ بِٱلْقَوْلِ فَيَطْمَعَ ٱلَّذِى فِى قَلْبِهِۦ مَرَضٌ وَقُلْنَ قَوْلًا مَّعْرُوفًا", tafsir: `` },
            { text: "وَقَرْنَ فِى بُيُوتِكُنَّ وَلَا تَبَرَّجْنَ تَبَرُّجَ ٱلْجَٰهِلِيَّةِ ٱلْأُولَىٰ وَأَقِمْنَ ٱلصَّلَوٰةَ وَءَاتِينَ ٱلزَّكَوٰةَ وَأَطِعْنَ ٱللَّهَ وَرَسُولَهُۥٓ إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذْهِبَ عَنكُمُ ٱلرِّجْسَ أَهْلَ ٱلْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا", tafsir: `` },
            { text: "وَٱذْكُرْنَ مَا يُتْلَىٰ فِى بُيُوتِكُنَّ مِنْ ءَايَٰتِ ٱللَّهِ وَٱلْحِكْمَةِ إِنَّ ٱللَّهَ كَانَ لَطِيفًا خَبِيرًا", tafsir: `` },
            { text: "إِنَّ ٱلْمُسْلِمِينَ وَٱلْمُسْلِمَٰتِ وَٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَٱلْقَٰنِتِينَ وَٱلْقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلْخَٰشِعِينَ وَٱلْخَٰشِعَٰتِ وَٱلْمُتَصَدِّقِينَ وَٱلْمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلْحَٰفِظِينَ فُرُوجَهُمْ وَٱلْحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرًا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغْفِرَةً وَأَجْرًا عَظِيمًا", tafsir: `` },
            { text: "وَمَا كَانَ لِمُؤْمِنٍ وَلَا مُؤْمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥٓ أَمْرًا أَن يَكُونَ لَهُمُ ٱلْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَن يَعْصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ ضَلَّ ضَلَٰلًا مُّبِينًا", tafsir: `` },
            { text: "وَإِذْ تَقُولُ لِلَّذِىٓ أَنْعَمَ ٱللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَٱتَّقِ ٱللَّهَ وَتُخْفِى فِى نَفْسِكَ مَا ٱللَّهُ مُبْدِيهِ وَتَخْشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخْشَىٰهُ فَلَمَّا قَضَىٰ زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَٰكَهَا لِكَىْ لَا يَكُونَ عَلَى ٱلْمُؤْمِنِينَ حَرَجٌ فِىٓ أَزْوَٰجِ أَدْعِيَآئِهِمْ إِذَا قَضَوْا۟ مِنْهُنَّ وَطَرًا وَكَانَ أَمْرُ ٱللَّهِ مَفْعُولًا", tafsir: `` },
            { text: "مَّا كَانَ عَلَى ٱلنَّبِىِّ مِنْ حَرَجٍ فِيمَا فَرَضَ ٱللَّهُ لَهُۥ سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَكَانَ أَمْرُ ٱللَّهِ قَدَرًا مَّقْدُورًا", tafsir: `` },
            { text: "ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخْشَوْنَهُۥ وَلَا يَخْشَوْنَ أَحَدًا إِلَّا ٱللَّهَ وَكَفَىٰ بِٱللَّهِ حَسِيبًا", tafsir: `` },
            { text: "مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَ وَكَانَ ٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱذْكُرُوا۟ ٱللَّهَ ذِكْرًا كَثِيرًا", tafsir: `` },
            { text: "وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا", tafsir: `` },
            { text: "هُوَ ٱلَّذِى يُصَلِّى عَلَيْكُمْ وَمَلَٰٓئِكَتُهُۥ لِيُخْرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَكَانَ بِٱلْمُؤْمِنِينَ رَحِيمًا", tafsir: `` },
            { text: "تَحِيَّتُهُمْ يَوْمَ يَلْقَوْنَهُۥ سَلَٰمٌ وَأَعَدَّ لَهُمْ أَجْرًا كَرِيمًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَرْسَلْنَٰكَ شَٰهِدًا وَمُبَشِّرًا وَنَذِيرًا", tafsir: `` },
            { text: "وَدَاعِيًا إِلَى ٱللَّهِ بِإِذْنِهِۦ وَسِرَاجًا مُّنِيرًا", tafsir: `` },
            { text: "وَبَشِّرِ ٱلْمُؤْمِنِينَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضْلًا كَبِيرًا", tafsir: `` },
            { text: "وَلَا تُطِعِ ٱلْكَٰفِرِينَ وَٱلْمُنَٰفِقِينَ وَدَعْ أَذَىٰهُمْ وَتَوَكَّلْ عَلَى ٱللَّهِ وَكَفَىٰ بِٱللَّهِ وَكِيلًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا نَكَحْتُمُ ٱلْمُؤْمِنَٰتِ ثُمَّ طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمْ عَلَيْهِنَّ مِنْ عِدَّةٍ تَعْتَدُّونَهَا فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحًا جَمِيلًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ إِنَّآ أَحْلَلْنَا لَكَ أَزْوَٰجَكَ ٱلَّٰتِىٓ ءَاتَيْتَ أُجُورَهُنَّ وَمَا مَلَكَتْ يَمِينُكَ مِمَّآ أَفَآءَ ٱللَّهُ عَلَيْكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَٰلَٰتِكَ ٱلَّٰتِى هَاجَرْنَ مَعَكَ وَٱمْرَأَةً مُّؤْمِنَةً إِن وَهَبَتْ نَفْسَهَا لِلنَّبِىِّ إِنْ أَرَادَ ٱلنَّبِىُّ أَن يَسْتَنكِحَهَا خَالِصَةً لَّكَ مِن دُونِ ٱلْمُؤْمِنِينَ قَدْ عَلِمْنَا مَا فَرَضْنَا عَلَيْهِمْ فِىٓ أَزْوَٰجِهِمْ وَمَا مَلَكَتْ أَيْمَٰنُهُمْ لِكَيْلَا يَكُونَ عَلَيْكَ حَرَجٌ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا", tafsir: `` },
            { text: "تُرْجِى مَن تَشَآءُ مِنْهُنَّ وَتُـْٔوِىٓ إِلَيْكَ مَن تَشَآءُ وَمَنِ ٱبْتَغَيْتَ مِمَّنْ عَزَلْتَ فَلَا جُنَاحَ عَلَيْكَ ذَٰلِكَ أَدْنَىٰٓ أَن تَقَرَّ أَعْيُنُهُنَّ وَلَا يَحْزَنَّ وَيَرْضَيْنَ بِمَآ ءَاتَيْتَهُنَّ كُلُّهُنَّ وَٱللَّهُ يَعْلَمُ مَا فِى قُلُوبِكُمْ وَكَانَ ٱللَّهُ عَلِيمًا حَلِيمًا", tafsir: `` },
            { text: "لَّا يَحِلُّ لَكَ ٱلنِّسَآءُ مِنۢ بَعْدُ وَلَآ أَن تَبَدَّلَ بِهِنَّ مِنْ أَزْوَٰجٍ وَلَوْ أَعْجَبَكَ حُسْنُهُنَّ إِلَّا مَا مَلَكَتْ يَمِينُكَ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ رَّقِيبًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَدْخُلُوا۟ بُيُوتَ ٱلنَّبِىِّ إِلَّآ أَن يُؤْذَنَ لَكُمْ إِلَىٰ طَعَامٍ غَيْرَ نَٰظِرِينَ إِنَىٰهُ وَلَٰكِنْ إِذَا دُعِيتُمْ فَٱدْخُلُوا۟ فَإِذَا طَعِمْتُمْ فَٱنتَشِرُوا۟ وَلَا مُسْتَـْٔنِسِينَ لِحَدِيثٍ إِنَّ ذَٰلِكُمْ كَانَ يُؤْذِى ٱلنَّبِىَّ فَيَسْتَحْىِۦ مِنكُمْ وَٱللَّهُ لَا يَسْتَحْىِۦ مِنَ ٱلْحَقِّ وَإِذَا سَأَلْتُمُوهُنَّ مَتَٰعًا فَسْـَٔلُوهُنَّ مِن وَرَآءِ حِجَابٍ ذَٰلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ وَمَا كَانَ لَكُمْ أَن تُؤْذُوا۟ رَسُولَ ٱللَّهِ وَلَآ أَن تَنكِحُوٓا۟ أَزْوَٰجَهُۥ مِنۢ بَعْدِهِۦٓ أَبَدًا إِنَّ ذَٰلِكُمْ كَانَ عِندَ ٱللَّهِ عَظِيمًا", tafsir: `` },
            { text: "إِن تُبْدُوا۟ شَيْـًٔا أَوْ تُخْفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَىْءٍ عَلِيمًا", tafsir: `` },
            { text: "لَّا جُنَاحَ عَلَيْهِنَّ فِىٓ ءَابَآئِهِنَّ وَلَآ أَبْنَآئِهِنَّ وَلَآ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ إِخْوَٰنِهِنَّ وَلَآ أَبْنَآءِ أَخَوَٰتِهِنَّ وَلَا نِسَآئِهِنَّ وَلَا مَا مَلَكَتْ أَيْمَٰنُهُنَّ وَٱتَّقِينَ ٱللَّهَ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدًا", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ وَمَلَٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ يُؤْذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأَعَدَّ لَهُمْ عَذَابًا مُّهِينًا", tafsir: `` },
            { text: "وَٱلَّذِينَ يُؤْذُونَ ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ بِغَيْرِ مَا ٱكْتَسَبُوا۟ فَقَدِ ٱحْتَمَلُوا۟ بُهْتَٰنًا وَإِثْمًا مُّبِينًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّبِىُّ قُل لِّأَزْوَٰجِكَ وَبَنَاتِكَ وَنِسَآءِ ٱلْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِن جَلَٰبِيبِهِنَّ ذَٰلِكَ أَدْنَىٰٓ أَن يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا", tafsir: `` },
            { text: "لَّئِن لَّمْ يَنتَهِ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ وَٱلْمُرْجِفُونَ فِى ٱلْمَدِينَةِ لَنُغْرِيَنَّكَ بِهِمْ ثُمَّ لَا يُجَاوِرُونَكَ فِيهَآ إِلَّا قَلِيلًا", tafsir: `` },
            { text: "مَّلْعُونِينَ أَيْنَمَا ثُقِفُوٓا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقْتِيلًا", tafsir: `` },
            { text: "سُنَّةَ ٱللَّهِ فِى ٱلَّذِينَ خَلَوْا۟ مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبْدِيلًا", tafsir: `` },
            { text: "يَسْـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِ قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِيبًا", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ لَعَنَ ٱلْكَٰفِرِينَ وَأَعَدَّ لَهُمْ سَعِيرًا", tafsir: `` },
            { text: "خَٰلِدِينَ فِيهَآ أَبَدًا لَّا يَجِدُونَ وَلِيًّا وَلَا نَصِيرًا", tafsir: `` },
            { text: "يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى ٱلنَّارِ يَقُولُونَ يَٰلَيْتَنَآ أَطَعْنَا ٱللَّهَ وَأَطَعْنَا ٱلرَّسُولَا۠", tafsir: `` },
            { text: "وَقَالُوا۟ رَبَّنَآ إِنَّآ أَطَعْنَا سَادَتَنَا وَكُبَرَآءَنَا فَأَضَلُّونَا ٱلسَّبِيلَا۠", tafsir: `` },
            { text: "رَبَّنَآ ءَاتِهِمْ ضِعْفَيْنِ مِنَ ٱلْعَذَابِ وَٱلْعَنْهُمْ لَعْنًا كَبِيرًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِينَ ءَاذَوْا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ وَكَانَ عِندَ ٱللَّهِ وَجِيهًا", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوْلًا سَدِيدًا", tafsir: `` },
            { text: "يُصْلِحْ لَكُمْ أَعْمَٰلَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدْ فَازَ فَوْزًا عَظِيمًا", tafsir: `` },
            { text: "إِنَّا عَرَضْنَا ٱلْأَمَانَةَ عَلَى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلْجِبَالِ فَأَبَيْنَ أَن يَحْمِلْنَهَا وَأَشْفَقْنَ مِنْهَا وَحَمَلَهَا ٱلْإِنسَٰنُ إِنَّهُۥ كَانَ ظَلُومًا جَهُولًا", tafsir: `` },
            { text: "لِّيُعَذِّبَ ٱللَّهُ ٱلْمُنَٰفِقِينَ وَٱلْمُنَٰفِقَٰتِ وَٱلْمُشْرِكِينَ وَٱلْمُشْرِكَٰتِ وَيَتُوبَ ٱللَّهُ عَلَى ٱلْمُؤْمِنِينَ وَٱلْمُؤْمِنَٰتِ وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًۢا", tafsir: `` }
        ]
    },
    34: { // سورة سبأ
        name: "سبأ",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَلَهُ ٱلْحَمْدُ فِى ٱلْـَٔاخِرَةِ وَهُوَ ٱلْحَكِيمُ ٱلْخَبِيرُ", tafsir: `` },
            { text: "يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنزِلُ مِنَ ٱلسَّمَآءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ ٱلرَّحِيمُ ٱلْغَفُورُ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَأْتِينَا ٱلسَّاعَةُ قُلْ بَلَىٰ وَرَبِّى لَتَأْتِيَنَّكُمْ عَٰلِمِ ٱلْغَيْبِ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَلَآ أَصْغَرُ مِن ذَٰلِكَ وَلَآ أَكْبَرُ إِلَّا فِى كِتَٰبٍ مُّبِينٍ", tafsir: `` },
            { text: "لِّيَجْزِىَ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ لَهُم مَّغْفِرَةٌ وَرِزْقٌ كَرِيمٌ", tafsir: `` },
            { text: "وَٱلَّذِينَ سَعَوْ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ مِّن رِّجْزٍ أَلِيمٌ", tafsir: `` },
            { text: "وَيَرَى ٱلَّذِينَ أُوتُوا۟ ٱلْعِلْمَ ٱلَّذِىٓ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ هُوَ ٱلْحَقَّ وَيَهْدِىٓ إِلَىٰ صِرَٰطِ ٱلْعَزِيزِ ٱلْحَمِيدِ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ كَفَرُوا۟ هَلْ نَدُلُّكُمْ عَلَىٰ رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِى خَلْقٍ جَدِيدٍ", tafsir: `` },
            { text: "أَفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةٌۢ بَلِ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ فِى ٱلْعَذَابِ وَٱلضَّلَٰلِ ٱلْبَعِيدِ", tafsir: `` },
            { text: "أَفَلَمْ يَرَوْا۟ إِلَىٰ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ إِن نَّشَأْ نَخْسِفْ بِهِمُ ٱلْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِّنَ ٱلسَّمَآءِ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّكُلِّ عَبْدٍ مُّنِيبٍ", tafsir: `` },
            { text: "وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًا يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ وَأَلَنَّا لَهُ ٱلْحَدِيدَ", tafsir: `` },
            { text: "أَنِ ٱعْمَلْ سَٰبِغَٰتٍ وَقَدِّرْ فِى ٱلسَّرْدِ وَٱعْمَلُوا۟ صَٰلِحًا إِنِّى بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `` },
            { text: "وَلِسُلَيْمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ", tafsir: `` },
            { text: "يَعْمَلُونَ لَهُۥ مَا يَشَآءُ مِن مَّحَٰرِيبَ وَتَمَٰثِيلَ وَجِفَانٍ كَٱلْجَوَابِ وَقُدُورٍ رَّاسِيَٰتٍ ٱعْمَلُوٓا۟ ءَالَ دَاوُۥدَ شُكْرًا وَقَلِيلٌ مِّنْ عِبَادِىَ ٱلشَّكُورُ", tafsir: `` },
            { text: "فَلَمَّا قَضَيْنَا عَلَيْهِ ٱلْمَوْتَ مَا دَلَّهُمْ عَلَىٰ مَوْتِهِۦٓ إِلَّا دَآبَّةُ ٱلْأَرْضِ تَأْكُلُ مِنسَأَتَهُۥ فَلَمَّا خَرَّ تَبَيَّنَتِ ٱلْجِنُّ أَن لَّوْ كَانُوا۟ يَعْلَمُونَ ٱلْغَيْبَ مَا لَبِثُوا۟ فِى ٱلْعَذَابِ ٱلْمُهِينِ", tafsir: `` },
            { text: "لَقَدْ كَانَ لِسَبَإٍ فِى مَسْكَنِهِمْ ءَايَةٌ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ كُلُوا۟ مِن رِّزْقِ رَبِّكُمْ وَٱشْكُرُوا۟ لَهُۥ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ", tafsir: `` },
            { text: "فَأَعْرَضُوا۟ فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ ٱلْعَرِمِ وَبَدَّلْنَٰهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَىْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَىْءٍ مِّن سِدْرٍ قَلِيلٍ", tafsir: `` },
            { text: "ذَٰلِكَ جَزَيْنَٰهُم بِمَا كَفَرُوا۟ وَهَلْ نُجَٰزِىٓ إِلَّا ٱلْكَفُورَ", tafsir: `` },
            { text: "وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ ٱلْقُرَى ٱلَّتِى بَٰرَكْنَا فِيهَا قُرًى ظَٰهِرَةً وَقَدَّرْنَا فِيهَا ٱلسَّيْرَ سِيرُوا۟ فِيهَا لَيَالِىَ وَأَيَّامًا ءَامِنِينَ", tafsir: `` },
            { text: "فَقَالُوا۟ رَبَّنَا بَٰعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوٓا۟ أَنفُسَهُمْ فَجَعَلْنَٰهُمْ أَحَادِيثَ وَمَزَّقْنَٰهُمْ كُلَّ مُمَزَّقٍ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ", tafsir: `` },
            { text: "وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِيقًا مِّنَ ٱلْمُؤْمِنِينَ", tafsir: `` },
            { text: "وَمَا كَانَ لَهُۥ عَلَيْهِم مِّن سُلْطَٰنٍ إِلَّا لِنَعْلَمَ مَن يُؤْمِنُ بِٱلْـَٔاخِرَةِ مِمَّنْ هُوَ مِنْهَا فِى شَكٍّ وَرَبُّكَ عَلَىٰ كُلِّ شَىْءٍ حَفِيظٌ", tafsir: `` },
            { text: "قُلِ ٱدْعُوا۟ ٱلَّذِينَ زَعَمْتُم مِّن دُونِ ٱللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِن شِرْكٍ وَمَا لَهُۥ مِنْهُم مِّن ظَهِيرٍ", tafsir: `` },
            { text: "وَلَا تَنفَعُ ٱلشَّفَٰعَةُ عِندَهُۥٓ إِلَّا لِمَنْ أَذِنَ لَهُۥ حَتَّىٰٓ إِذَا فُزِّعَ عَن قُلُوبِهِمْ قَالُوا۟ مَاذَا قَالَ رَبُّكُمْ قَالُوا۟ ٱلْحَقَّ وَهُوَ ٱلْعَلِىُّ ٱلْكَبِيرُ", tafsir: `` },
            { text: "قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ قُلِ ٱللَّهُ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "قُل لَّا تُسْـَٔلُونَ عَمَّآ أَجْرَمْنَا وَلَا نُسْـَٔلُ عَمَّا تَعْمَلُونَ", tafsir: `` },
            { text: "قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِٱلْحَقِّ وَهُوَ ٱلْفَتَّاحُ ٱلْعَلِيمُ", tafsir: `` },
            { text: "قُلْ أَرُونِىَ ٱلَّذِينَ أَلْحَقْتُم بِهِۦ شُرَكَآءَ كَلَّا بَلْ هُوَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `` },
            { text: "وَمَآ أَرْسَلْنَٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `` },
            { text: "قُل لَّكُم مِّيعَادُ يَوْمٍ لَّا تَسْتَـْٔخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَن نُّؤْمِنَ بِهَٰذَا ٱلْقُرْءَانِ وَلَا بِٱلَّذِى بَيْنَ يَدَيْهِ وَلَوْ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ مَوْقُوفُونَ عِندَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَىٰ بَعْضٍ ٱلْقَوْلَ يَقُولُ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ لَوْلَآ أَنتُمْ لَكُنَّا مُؤْمِنِينَ", tafsir: `` },
            { text: "قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ لِلَّذِينَ ٱسْتُضْعِفُوٓا۟ أَنَحْنُ صَدَدْنَٰكُمْ عَنِ ٱلْهُدَىٰ بَعْدَ إِذْ جَآءَكُم بَلْ كُنتُم مُّجْرِمِينَ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ ٱسْتُضْعِفُوا۟ لِلَّذِينَ ٱسْتَكْبَرُوا۟ بَلْ مَكْرُ ٱلَّيْلِ وَٱلنَّهَارِ إِذْ تَأْمُرُونَنَآ أَن نَّكْفُرَ بِٱللَّهِ وَنَجْعَلَ لَهُۥٓ أَندَادًا وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ وَجَعَلْنَا ٱلْأَغْلَٰلَ فِىٓ أَعْنَاقِ ٱلَّذِينَ كَفَرُوا۟ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ", tafsir: `` },
            { text: "وَقَالُوا۟ نَحْنُ أَكْثَرُ أَمْوَٰلًا وَأَوْلَٰدًا وَمَا نَحْنُ بِمُعَذَّبِينَ", tafsir: `` },
            { text: "قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِٱلَّتِى تُقَرِّبُكُمْ عِندَنَا زُلْفَىٰٓ إِلَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَأُو۟لَٰٓئِكَ لَهُمْ جَزَآءُ ٱلضِّعْفِ بِمَا عَمِلُوا۟ وَهُمْ فِى ٱلْغُرُفَٰتِ ءَامِنُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ يَسْعَوْنَ فِىٓ ءَايَٰتِنَا مُعَٰجِزِينَ أُو۟لَٰٓئِكَ فِى ٱلْعَذَابِ مُحْضَرُونَ", tafsir: `` },
            { text: "قُلْ إِنَّ رَبِّى يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ مِنْ عِبَادِهِۦ وَيَقْدِرُ لَهُۥ وَمَآ أَنفَقْتُم مِّن شَىْءٍ فَهُوَ يُخْلِفُهُۥ وَهُوَ خَيْرُ ٱلرَّٰزِقِينَ", tafsir: `` },
            { text: "وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَٰٓئِكَةِ أَهَٰٓؤُلَآءِ إِيَّاكُمْ كَانُوا۟ يَعْبُدُونَ", tafsir: `` },
            { text: "قَالُوا۟ سُبْحَٰنَكَ أَنتَ وَلِيُّنَا مِن دُونِهِم بَلْ كَانُوا۟ يَعْبُدُونَ ٱلْجِنَّ أَكْثَرُهُم بِهِم مُّؤْمِنُونَ", tafsir: `` },
            { text: "فَٱلْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَّفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِى كُنتُم بِهَا تُكَذِّبُونَ", tafsir: `` },
            { text: "وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَٰتُنَا بَيِّنَٰتٍ قَالُوا۟ مَا هَٰذَآ إِلَّا رَجُلٌ يُرِيدُ أَن يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ ءَابَآؤُكُمْ وَقَالُوا۟ مَا هَٰذَآ إِلَّآ إِفْكٌ مُّفْتَرًى وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لِلْحَقِّ لَمَّا جَآءَهُمْ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ", tafsir: `` },
            { text: "وَمَآ ءَاتَيْنَٰهُم مِّن كُتُبٍ يَدْرُسُونَهَا وَمَآ أَرْسَلْنَآ إِلَيْهِمْ قَبْلَكَ مِن نَّذِيرٍ", tafsir: `` },
            { text: "وَكَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ وَمَا بَلَغُوا۟ مِعْشَارَ مَآ ءَاتَيْنَٰهُمْ فَكَذَّبُوا۟ رُسُلِى فَكَيْفَ كَانَ نَكِيرِ", tafsir: `` },
            { text: "قُلْ إِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍ أَن تَقُومُوا۟ لِلَّهِ مَثْنَىٰ وَفُرَٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ مَا بِصَاحِبِكُم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَّكُم بَيْنَ يَدَىْ عَذَابٍ شَدِيدٍ", tafsir: `` },
            { text: "قُلْ مَا سَأَلْتُكُم مِّنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِىَ إِلَّا عَلَى ٱللَّهِ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ", tafsir: `` },
            { text: "قُلْ إِنَّ رَبِّى يَقْذِفُ بِٱلْحَقِّ عَلَّٰمُ ٱلْغُيُوبِ", tafsir: `` },
            { text: "قُلْ جَآءَ ٱلْحَقُّ وَمَا يُبْدِئُ ٱلْبَٰطِلُ وَمَا يُعِيدُ", tafsir: `` },
            { text: "قُلْ إِن ضَلَلْتُ فَإِنَّمَآ أَضِلُّ عَلَىٰ نَفْسِى وَإِنِ ٱهْتَدَيْتُ فَبِمَا يُوحِىٓ إِلَىَّ رَبِّىٓ إِنَّهُۥ سَمِيعٌ قَرِيبٌ", tafsir: `` },
            { text: "وَلَوْ تَرَىٰٓ إِذْ فَزِعُوا۟ فَلَا فَوْتَ وَأُخِذُوا۟ مِن مَّكَانٍ قَرِيبٍ", tafsir: `` },
            { text: "وَقَالُوٓا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانٍۭ بَعِيدٍ", tafsir: `` },
            { text: "وَقَدْ كَفَرُوا۟ بِهِۦ مِن قَبْلُ وَيَقْذِفُونَ بِٱلْغَيْبِ مِن مَّكَانٍۭ بَعِيدٍ", tafsir: `` },
            { text: "وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِم مِّن قَبْلُ إِنَّهُمْ كَانُوا۟ فِى شَكٍّ مُّرِيبٍۭ", tafsir: `` }
        ]
    },
    35: { // سورة فاطر
        name: "فاطر",
        basmalaTafsir: ``,
        verses: [
            { text: "ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَاعِلِ ٱلْمَلَٰٓئِكَةِ رُسُلًا أُو۟لِىٓ أَجْنِحَةٍ مَّثْنَىٰ وَثُلَٰثَ وَرُبَٰعَ يَزِيدُ فِى ٱلْخَلْقِ مَا يَشَآءُ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `` },
            { text: "مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلَا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلَا مُرْسِلَ لَهُۥ مِنۢ بَعْدِهِۦ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّاسُ ٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ هَلْ مِنْ خَٰلِقٍ غَيْرُ ٱللَّهِ يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ", tafsir: `` },
            { text: "وَإِن يُكَذِّبُوكَ فَقَدْ كُذِّبَتْ رُسُلٌ مِّن قَبْلِكَ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَلَا يَغُرَّنَّكُم بِٱللَّهِ ٱلْغَرُورُ", tafsir: `` },
            { text: "إِنَّ ٱلشَّيْطَٰنَ لَكُمْ عَدُوٌّ فَٱتَّخِذُوهُ عَدُوًّا إِنَّمَا يَدْعُوا۟ حِزْبَهُۥ لِيَكُونُوا۟ مِنْ أَصْحَٰبِ ٱلسَّعِيرِ", tafsir: `` },
            { text: "ٱلَّذِينَ كَفَرُوا۟ لَهُمْ عَذَابٌ شَدِيدٌ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُم مَّغْفِرَةٌ وَأَجْرٌ كَبِيرٌ", tafsir: `` },
            { text: "أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنًا فَإِنَّ ٱللَّهَ يُضِلُّ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ فَلَا تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَٰتٍ إِنَّ ٱللَّهَ عَلِيمٌۢ بِمَا يَصْنَعُونَ", tafsir: `` },
            { text: "وَٱللَّهُ ٱلَّذِىٓ أَرْسَلَ ٱلرِّيَٰحَ فَتُثِيرُ سَحَابًا فَسُقْنَٰهُ إِلَىٰ بَلَدٍ مَّيِّتٍ فَأَحْيَيْنَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا كَذَٰلِكَ ٱلنُّشُورُ", tafsir: `` },
            { text: "مَن كَانَ يُرِيدُ ٱلْعِزَّةَ فَلِلَّهِ ٱلْعِزَّةُ جَمِيعًا إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّٰلِحُ يَرْفَعُهُۥ وَٱلَّذِينَ يَمْكُرُونَ ٱلسَّيِّـَٔاتِ لَهُمْ عَذَابٌ شَدِيدٌ وَمَكْرُ أُو۟لَٰٓئِكَ هُوَ يَبُورُ", tafsir: `` },
            { text: "وَٱللَّهُ خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ جَعَلَكُمْ أَزْوَٰجًا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَمَا يُعَمَّرُ مِن مُّعَمَّرٍ وَلَا يُنقَصُ مِنْ عُمُرِهِۦٓ إِلَّا فِى كِتَٰبٍ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٌ", tafsir: `` },
            { text: "وَمَا يَسْتَوِى ٱلْبَحْرَانِ هَٰذَا عَذْبٌ فُرَاتٌ سَآئِغٌ شَرَابُهُۥ وَهَٰذَا مِلْحٌ أُجَاجٌ وَمِن كُلٍّ تَأْكُلُونَ لَحْمًا طَرِيًّا وَتَسْتَخْرِجُونَ حِلْيَةً تَلْبَسُونَهَا وَتَرَى ٱلْفُلْكَ فِيهِ مَوَاخِرَ لِتَبْتَغُوا۟ مِن فَضْلِهِۦ وَلَعَلَّكُمْ تَشْكُرُونَ", tafsir: `` },
            { text: "يُولِجُ ٱلَّيْلَ فِى ٱلنَّهَارِ وَيُولِجُ ٱلنَّهَارَ فِى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ مَا يَمْلِكُونَ مِن قِطْمِيرٍ", tafsir: `` },
            { text: "إِن تَدْعُوهُمْ لَا يَسْمَعُوا۟ دُعَآءَكُمْ وَلَوْ سَمِعُوا۟ مَا ٱسْتَجَابُوا۟ لَكُمْ وَيَوْمَ ٱلْقِيَٰمَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلَا يُنَبِّئُكَ مِثْلُ خَبِيرٍ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلنَّاسُ أَنتُمُ ٱلْفُقَرَآءُ إِلَى ٱللَّهِ وَٱللَّهُ هُوَ ٱلْغَنِىُّ ٱلْحَمِيدُ", tafsir: `` },
            { text: "إِن يَشَأْ يُذْهِبْكُمْ وَيَأْتِ بِخَلْقٍ جَدِيدٍ", tafsir: `` },
            { text: "وَمَا ذَٰلِكَ عَلَى ٱللَّهِ بِعَزِيزٍ", tafsir: `` },
            { text: "وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ", tafsir: `` },
            { text: "وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ", tafsir: `` },
            { text: "وَلَا ٱلظُّلُمَٰتُ وَلَا ٱلنُّورُ", tafsir: `` },
            { text: "وَلَا ٱلظِّلُّ وَلَا ٱلْحَرُورُ", tafsir: `` },
            { text: "وَمَا يَسْتَوِى ٱلْأَحْيَآءُ وَلَا ٱلْأَمْوَٰتُ إِنَّ ٱللَّهَ يُسْمِعُ مَن يَشَآءُ وَمَآ أَنتَ بِمُسْمِعٍ مَّن فِى ٱلْقُبُورِ", tafsir: `` },
            { text: "إِنْ أَنتَ إِلَّا نَذِيرٌ", tafsir: `` },
            { text: "إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَإِن مِّنْ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٌ", tafsir: `` },
            { text: "وَإِن يُكَذِّبُوكَ فَقَدْ كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ وَبِٱلزُّبُرِ وَبِٱلْكِتَٰبِ ٱلْمُنِيرِ", tafsir: `` },
            { text: "ثُمَّ أَخَذْتُ ٱلَّذِينَ كَفَرُوا۟ فَكَيْفَ كَانَ نَكِيرِ", tafsir: `` },
            { text: "أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجْنَا بِهِۦ ثَمَرَٰتٍ مُّخْتَلِفًا أَلْوَٰنُهَا وَمِنَ ٱلْجِبَالِ جُدَدٌۢ بِيضٌ وَحُمْرٌ مُّخْتَلِفٌ أَلْوَٰنُهَا وَغَرَابِيبُ سُودٌ", tafsir: `` },
            { text: "وَمِنَ ٱلنَّاسِ وَٱلدَّوَآبِّ وَٱلْأَنْعَٰمِ مُخْتَلِفٌ أَلْوَٰنُهُۥ كَذَٰلِكَ إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا۟ إِنَّ ٱللَّهَ عَزِيزٌ غَفُورٌ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ يَتْلُونَ كِتَٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقْنَٰهُمْ سِرًّا وَعَلَانِيَةً يَرْجُونَ تِجَٰرَةً لَّن تَبُورَ", tafsir: `` },
            { text: "لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُم مِّن فَضْلِهِۦٓ إِنَّهُۥ غَفُورٌ شَكُورٌ", tafsir: `` },
            { text: "وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ مِنَ ٱلْكِتَٰبِ هُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِيرٌۢ بَصِيرٌ", tafsir: `` },
            { text: "ثُمَّ أَوْرَثْنَا ٱلْكِتَٰبَ ٱلَّذِينَ ٱصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِّنَفْسِهِۦ وَمِنْهُم مُّقْتَصِدٌ وَمِنْهُمْ سَابِقٌۢ بِٱلْخَيْرَٰتِ بِإِذْنِ ٱللَّهِ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ", tafsir: `` },
            { text: "جَنَّٰتُ عَدْنٍ يَدْخُلُونَهَا يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ", tafsir: `` },
            { text: "وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِىٓ أَذْهَبَ عَنَّا ٱلْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ", tafsir: `` },
            { text: "ٱلَّذِىٓ أَحَلَّنَا دَارَ ٱلْمُقَامَةِ مِن فَضْلِهِۦ لَا يَمَسُّنَا فِيهَا نَصَبٌ وَلَا يَمَسُّنَا فِيهَا لُغُوبٌ", tafsir: `` },
            { text: "وَٱلَّذِينَ كَفَرُوا۟ لَهُمْ نَارُ جَهَنَّمَ لَا يُقْضَىٰ عَلَيْهِمْ فَيَمُوتُوا۟ وَلَا يُخَفَّفُ عَنْهُم مِّنْ عَذَابِهَا كَذَٰلِكَ نَجْزِى كُلَّ كَفُورٍ", tafsir: `` },
            { text: "وَهُمْ يَصْطَرِخُونَ فِيهَا رَبَّنَآ أَخْرِجْنَا نَعْمَلْ صَٰلِحًا غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ أَوَلَمْ نُعَمِّرْكُم مَّا يَتَذَكَّرُ فِيهِ مَن تَذَكَّرَ وَجَآءَكُمُ ٱلنَّذِيرُ فَذُوقُوا۟ فَمَا لِلظَّٰلِمِينَ مِن نَّصِيرٍ", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ عَٰلِمُ غَيْبِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى جَعَلَكُمْ خَلَٰٓئِفَ فِى ٱلْأَرْضِ فَمَن كَفَرَ فَعَلَيْهِ كُفْرُهُۥ وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ عِندَ رَبِّهِمْ إِلَّا مَقْتًا وَلَا يَزِيدُ ٱلْكَٰفِرِينَ كُفْرُهُمْ إِلَّا خَسَارًا", tafsir: `` },
            { text: "قُلْ أَرَءَيْتُمْ شُرَكَآءَكُمُ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ أَرُونِى مَاذَا خَلَقُوا۟ مِنَ ٱلْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِى ٱلسَّمَٰوَٰتِ أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا فَهُمْ عَلَىٰ بَيِّنَتٍ مِّنْهُ بَلْ إِن يَعِدُ ٱلظَّٰلِمُونَ بَعْضُهُم بَعْضًا إِلَّا غُرُورًا", tafsir: `` },
            { text: "إِنَّ ٱللَّهَ يُمْسِكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ أَن تَزُولَا وَلَئِن زَالَتَآ إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّنۢ بَعْدِهِۦٓ إِنَّهُۥ كَانَ حَلِيمًا غَفُورًا", tafsir: `` },
            { text: "وَأَقْسَمُوا۟ بِٱللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِن جَآءَهُمْ نَذِيرٌ لَّيَكُونُنَّ أَهْدَىٰ مِنْ إِحْدَى ٱلْأُمَمِ فَلَمَّا جَآءَهُمْ نَذِيرٌ مَّا زَادَهُمْ إِلَّا نُفُورًا", tafsir: `` },
            { text: "ٱسْتِكْبَارًا فِى ٱلْأَرْضِ وَمَكْرَ ٱلسَّيِّئِ وَلَا يَحِيقُ ٱلْمَكْرُ ٱلسَّيِّئُ إِلَّا بِأَهْلِهِۦ فَهَلْ يَنظُرُونَ إِلَّا سُنَّتَ ٱلْأَوَّلِينَ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبْدِيلًا وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحْوِيلًا", tafsir: `` },
            { text: "أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ وَكَانُوٓا۟ أَشَدَّ مِنْهُمْ قُوَّةً وَمَا كَانَ ٱللَّهُ لِيُعْجِزَهُۥ مِن شَىْءٍ فِى ٱلسَّمَٰوَٰتِ وَلَا فِى ٱلْأَرْضِ إِنَّهُۥ كَانَ عَلِيمًا قَدِيرًا", tafsir: `` },
            { text: "وَلَوْ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهْرِهَا مِن دَآبَّةٍ وَلَٰكِن يُؤَخِّرُهُمْ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَإِذَا جَآءَ أَجَلُهُمْ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِيرًۢا", tafsir: `` }
        ]
    },
    36: { // سورة يس
        name: "يس",
        basmalaTafsir: ``,
        verses: [
            { text: "يسٓ", tafsir: `` },
            { text: "وَٱلْقُرْءَانِ ٱلْحَكِيمِ", tafsir: `` },
            { text: "إِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `` },
            { text: "تَنزِيلَ ٱلْعَزِيزِ ٱلرَّحِيمِ", tafsir: `` },
            { text: "لِتُنذِرَ قَوْمًا مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَٰفِلُونَ", tafsir: `` },
            { text: "لَقَدْ حَقَّ ٱلْقَوْلُ عَلَىٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "إِنَّا جَعَلْنَا فِىٓ أَعْنَٰقِهِمْ أَغْلَٰلًا فَهِىَ إِلَى ٱلْأَذْقَانِ فَهُم مُّقْمَحُونَ", tafsir: `` },
            { text: "وَجَعَلْنَا مِنۢ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَٰهُمْ فَهُمْ لَا يُبْصِرُونَ", tafsir: `` },
            { text: "وَسَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكْرَ وَخَشِىَ ٱلرَّحْمَٰنَ بِٱلْغَيْبِ فَبَشِّرْهُ بِمَغْفِرَةٍ وَأَجْرٍ كَرِيمٍ", tafsir: `` },
            { text: "إِنَّا نَحْنُ نُحْىِ ٱلْمَوْتَىٰ وَنَكْتُبُ مَا قَدَّمُوا۟ وَءَاثَٰرَهُمْ وَكُلَّ شَىْءٍ أَحْصَيْنَٰهُ فِىٓ إِمَامٍ مُّبِينٍ", tafsir: `` },
            { text: "وَٱضْرِبْ لَهُم مَّثَلًا أَصْحَٰبَ ٱلْقَرْيَةِ إِذْ جَآءَهَا ٱلْمُرْسَلُونَ", tafsir: `` },
            { text: "إِذْ أَرْسَلْنَآ إِلَيْهِمُ ٱثْنَيْنِ فَكَذَّبُوهُمَا فَعَزَّزْنَا بِثَالِثٍ فَقَالُوٓا۟ إِنَّآ إِلَيْكُم مُّرْسَلُونَ", tafsir: `` },
            { text: "قَالُوا۟ مَآ أَنتُمْ إِلَّا بَشَرٌ مِّثْلُنَا وَمَآ أَنزَلَ ٱلرَّحْمَٰنُ مِن شَىْءٍ إِنْ أَنتُمْ إِلَّا تَكْذِبُونَ", tafsir: `` },
            { text: "قَالُوا۟ رَبُّنَا يَعْلَمُ إِنَّآ إِلَيْكُمْ لَمُرْسَلُونَ", tafsir: `` },
            { text: "وَمَا عَلَيْنَآ إِلَّا ٱلْبَلَٰغُ ٱلْمُبِينُ", tafsir: `` },
            { text: "قَالُوٓا۟ إِنَّا تَطَيَّرْنَا بِكُمْ لَئِن لَّمْ تَنتَهُوا۟ لَنَرْجُمَنَّكُمْ وَلَيَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "قَالُوا۟ طَٰٓئِرُكُم مَّعَكُمْ أَئِن ذُكِّرْتُم بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ", tafsir: `` },
            { text: "وَجَآءَ مِنْ أَقْصَا ٱلْمَدِينَةِ رَجُلٌ يَسْعَىٰ قَالَ يَٰقَوْمِ ٱتَّبِعُوا۟ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "ٱتَّبِعُوا۟ مَن لَّا يَسْـَٔلُكُمْ أَجْرًا وَهُم مُّهْتَدُونَ", tafsir: `` },
            { text: "وَمَا لِىَ لَآ أَعْبُدُ ٱلَّذِى فَطَرَنِى وَإِلَيْهِ تُرْجَعُونَ", tafsir: `` },
            { text: "ءَأَتَّخِذُ مِن دُونِهِۦٓ ءَالِهَةً إِن يُرِدْنِ ٱلرَّحْمَٰنُ بِضُرٍّ لَّا تُغْنِ عَنِّى شَفَٰعَتُهُمْ شَيْـًٔا وَلَا يُنقِذُونِ", tafsir: `` },
            { text: "إِنِّىٓ إِذًا لَّفِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "إِنِّىٓ ءَامَنتُ بِرَبِّكُمْ فَٱسْمَعُونِ", tafsir: `` },
            { text: "قِيلَ ٱدْخُلِ ٱلْجَنَّةَ قَالَ يَٰلَيْتَ قَوْمِى يَعْلَمُونَ", tafsir: `` },
            { text: "بِمَا غَفَرَ لِى رَبِّى وَجَعَلَنِى مِنَ ٱلْمُكْرَمِينَ", tafsir: `` },
            { text: "وَمَآ أَنزَلْنَا عَلَىٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن جُندٍ مِّنَ ٱلسَّمَآءِ وَمَا كُنَّا مُنزِلِينَ", tafsir: `` },
            { text: "إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ خَٰمِدُونَ", tafsir: `` },
            { text: "يَٰحَسْرَةً عَلَى ٱلْعِبَادِ مَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `` },
            { text: "أَلَمْ يَرَوْا۟ كَمْ أَهْلَكْنَا قَبْلَهُم مِّنَ ٱلْقُرُونِ أَنَّهُمْ إِلَيْهِمْ لَا يَرْجِعُونَ", tafsir: `` },
            { text: "وَإِن كُلٌّ لَّمَّا جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ", tafsir: `` },
            { text: "وَءَايَةٌ لَّهُمُ ٱلْأَرْضُ ٱلْمَيْتَةُ أَحْيَيْنَٰهَا وَأَخْرَجْنَا مِنْهَا حَبًّا فَمِنْهُ يَأْكُلُونَ", tafsir: `` },
            { text: "وَجَعَلْنَا فِيهَا جَنَّٰتٍ مِّن نَّخِيلٍ وَأَعْنَٰبٍ وَفَجَّرْنَا فِيهَا مِنَ ٱلْعُيُونِ", tafsir: `` },
            { text: "لِيَأْكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتْهُ أَيْدِيهِمْ أَفَلَا يَشْكُرُونَ", tafsir: `` },
            { text: "سُبْحَٰنَ ٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ وَمِنْ أَنفُسِهِمْ وَمِمَّا لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَءَايَةٌ لَّهُمُ ٱلَّيْلُ نَسْلَخُ مِنْهُ ٱلنَّهَارَ فَإِذَا هُم مُّظْلِمُونَ", tafsir: `` },
            { text: "وَٱلشَّمْسُ تَجْرِى لِمُسْتَقَرٍّ لَّهَا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ", tafsir: `` },
            { text: "وَٱلْقَمَرَ قَدَّرْنَٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلْعُرْجُونِ ٱلْقَدِيمِ", tafsir: `` },
            { text: "لَا ٱلشَّمْسُ يَنۢبَغِى لَهَآ أَن تُدْرِكَ ٱلْقَمَرَ وَلَا ٱلَّيْلُ سَابِقُ ٱلنَّهَارِ وَكُلٌّ فِى فَلَكٍ يَسْبَحُونَ", tafsir: `` },
            { text: "وَءَايَةٌ لَّهُمْ أَنَّا حَمَلْنَا ذُرِّيَّتَهُمْ فِى ٱلْفُلْكِ ٱلْمَشْحُونِ", tafsir: `` },
            { text: "وَخَلَقْنَا لَهُم مِّن مِّثْلِهِۦ مَا يَرْكَبُونَ", tafsir: `` },
            { text: "وَإِن نَّشَأْ نُغْرِقْهُمْ فَلَا صَرِيخَ لَهُمْ وَلَا هُمْ يُنقَذُونَ", tafsir: `` },
            { text: "إِلَّا رَحْمَةً مِّنَّا وَمَتَٰعًا إِلَىٰ حِينٍ", tafsir: `` },
            { text: "وَإِذَا قِيلَ لَهُمُ ٱتَّقُوا۟ مَا بَيْنَ أَيْدِيكُمْ وَمَا خَلْفَكُمْ لَعَلَّكُمْ تُرْحَمُونَ", tafsir: `` },
            { text: "وَمَا تَأْتِيهِم مِّنْ ءَايَةٍ مِّنْ ءَايَٰتِ رَبِّهِمْ إِلَّا كَانُوا۟ عَنْهَا مُعْرِضِينَ", tafsir: `` },
            { text: "وَإِذَا قِيلَ لَهُمْ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِينَ كَفَرُوا۟ لِلَّذِينَ ءَامَنُوٓا۟ أَنُطْعِمُ مَن لَّوْ يَشَآءُ ٱللَّهُ أَطْعَمَهُۥٓ إِنْ أَنتُمْ إِلَّا فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "وَيَقُولُونَ مَتَىٰ هَٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `` },
            { text: "مَا يَنظُرُونَ إِلَّا صَيْحَةً وَٰحِدَةً تَأْخُذُهُمْ وَهُمْ يَخِصِّمُونَ", tafsir: `` },
            { text: "فَلَا يَسْتَطِيعُونَ تَوْصِيَةً وَلَآ إِلَىٰٓ أَهْلِهِمْ يَرْجِعُونَ", tafsir: `` },
            { text: "وَنُفِخَ فِى ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلْأَجْدَاثِ إِلَىٰ رَبِّهِمْ يَنسِلُونَ", tafsir: `` },
            { text: "قَالُوا۟ يَٰوَيْلَنَا مَنۢ بَعَثَنَا مِن مَّرْقَدِنَا هَٰذَا مَا وَعَدَ ٱلرَّحْمَٰنُ وَصَدَقَ ٱلْمُرْسَلُونَ", tafsir: `` },
            { text: "إِن كَانَتْ إِلَّا صَيْحَةً وَٰحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ", tafsir: `` },
            { text: "فَٱلْيَوْمَ لَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَلَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "إِنَّ أَصْحَٰبَ ٱلْجَنَّةِ ٱلْيَوْمَ فِى شُغُلٍ فَٰكِهُونَ", tafsir: `` },
            { text: "هُمْ وَأَزْوَٰجُهُمْ فِى ظِلَٰلٍ عَلَى ٱلْأَرَآئِكِ مُتَّكِـُٔونَ", tafsir: `` },
            { text: "لَهُمْ فِيهَا فَٰكِهَةٌ وَلَهُم مَّا يَدَّعُونَ", tafsir: `` },
            { text: "سَلَٰمٌ قَوْلًا مِّن رَّبٍّ رَّحِيمٍ", tafsir: `` },
            { text: "وَٱمْتَٰزُوا۟ ٱلْيَوْمَ أَيُّهَا ٱلْمُجْرِمُونَ", tafsir: `` },
            { text: "أَلَمْ أَعْهَدْ إِلَيْكُمْ يَٰبَنِىٓ ءَادَمَ أَن لَّا تَعْبُدُوا۟ ٱلشَّيْطَٰنَ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ", tafsir: `` },
            { text: "وَأَنِ ٱعْبُدُونِى هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ", tafsir: `` },
            { text: "وَلَقَدْ أَضَلَّ مِنكُمْ جِبِلًّا كَثِيرًا أَفَلَمْ تَكُونُوا۟ تَعْقِلُونَ", tafsir: `` },
            { text: "هَٰذِهِۦ جَهَنَّمُ ٱلَّتِى كُنتُمْ تُوعَدُونَ", tafsir: `` },
            { text: "ٱصْلَوْهَا ٱلْيَوْمَ بِمَا كُنتُمْ تَكْفُرُونَ", tafsir: `` },
            { text: "ٱلْيَوْمَ نَخْتِمُ عَلَىٰٓ أَفْوَٰهِهِمْ وَتُكَلِّمُنَآ أَيْدِيهِمْ وَتَشْهَدُ أَرْجُلُهُم بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `` },
            { text: "وَلَوْ نَشَآءُ لَطَمَسْنَا عَلَىٰٓ أَعْيُنِهِمْ فَٱسْتَبَقُوا۟ ٱلصِّرَٰطَ فَأَنَّىٰ يُبْصِرُونَ", tafsir: `` },
            { text: "وَلَوْ نَشَآءُ لَمَسَخْنَٰهُمْ عَلَىٰ مَكَانَتِهِمْ فَمَا ٱسْتَطَٰعُوا۟ مُضِيًّا وَلَا يَرْجِعُونَ", tafsir: `` },
            { text: "وَمَن نُّعَمِّرْهُ نُنَكِّسْهُ فِى ٱلْخَلْقِ أَفَلَا يَعْقِلُونَ", tafsir: `` },
            { text: "وَمَا عَلَّمْنَٰهُ ٱلشِّعْرَ وَمَا يَنۢبَغِى لَهُۥٓ إِنْ هُوَ إِلَّا ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ", tafsir: `` },
            { text: "لِّيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ ٱلْقَوْلُ عَلَى ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "أَوَلَمْ يَرَوْا۟ أَنَّا خَلَقْنَا لَهُم مِّمَّا عَمِلَتْ أَيْدِينَآ أَنْعَٰمًا فَهُمْ لَهَا مَٰلِكُونَ", tafsir: `` },
            { text: "وَذَلَّلْنَٰهَا لَهُمْ فَمِنْهَا رَكُوبُهُمْ وَمِنْهَا يَأْكُلُونَ", tafsir: `` },
            { text: "وَلَهُمْ فِيهَا مَنَٰفِعُ وَمَشَارِبُ أَفَلَا يَشْكُرُونَ", tafsir: `` },
            { text: "وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ", tafsir: `` },
            { text: "لَا يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مُّحْضَرُونَ", tafsir: `` },
            { text: "فَلَا يَحْزُنكَ قَوْلُهُمْ إِنَّا نَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ", tafsir: `` },
            { text: "أَوَلَمْ يَرَ ٱلْإِنسَٰنُ أَنَّا خَلَقْنَٰهُ مِن نُّطْفَةٍ فَإِذَا هُوَ خَصِيمٌ مُّبِينٌ", tafsir: `` },
            { text: "وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ قَالَ مَن يُحْىِ ٱلْعِظَٰمَ وَهِىَ رَمِيمٌ", tafsir: `` },
            { text: "قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ", tafsir: `` },
            { text: "ٱلَّذِى جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلْأَخْضَرِ نَارًا فَإِذَآ أَنتُم مِّنْهُ تُوقِدُونَ", tafsir: `` },
            { text: "أَوَلَيْسَ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخْلُقَ مِثْلَهُم بَلَىٰ وَهُوَ ٱلْخَلَّٰقُ ٱلْعَلِيمُ", tafsir: `` },
            { text: "إِنَّمَآ أَمْرُهُۥٓ إِذَآ أَرَادَ شَيْـًٔا أَن يَقُولَ لَهُۥ كُن فَيَكُونُ", tafsir: `` },
            { text: "فَسُبْحَٰنَ ٱلَّذِى بِيَدِهِۦ مَلَكُوتُ كُلِّ شَىْءٍ وَإِلَيْهِ تُرْجَعُونَ", tafsir: `` }
        ]
    },
    37: { // سورة الصافات
        name: "الصافات",
        basmalaTafsir: ``,
        verses: [
            { text: "وَٱلصَّٰٓفَّٰتِ صَفًّا", tafsir: `` },
            { text: "فَٱلزَّٰجِرَٰتِ زَجْرًا", tafsir: `` },
            { text: "فَٱلتَّٰلِيَٰتِ ذِكْرًا", tafsir: `` },
            { text: "إِنَّ إِلَٰهَكُمْ لَوَٰحِدٌ", tafsir: `` },
            { text: "رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ ٱلْمَشَٰرِقِ", tafsir: `` },
            { text: "إِنَّا زَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِزِينَةٍ ٱلْكَوَاكِبِ", tafsir: `` },
            { text: "وَحِفْظًا مِّن كُلِّ شَيْطَٰنٍ مَّارِدٍ", tafsir: `` },
            { text: "لَّا يَسَّمَّعُونَ إِلَى ٱلْمَلَإِ ٱلْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ", tafsir: `` },
            { text: "دُحُورًا وَلَهُمْ عَذَابٌ وَاصِبٌ", tafsir: `` },
            { text: "إِلَّا مَنْ خَطِفَ ٱلْخَطْفَةَ فَأَتْبَعَهُۥ شِهَابٌ ثَاقِبٌ", tafsir: `` },
            { text: "فَٱسْتَفْتِهِمْ أَهُمْ أَشَدُّ خَلْقًا أَم مَّنْ خَلَقْنَآ إِنَّا خَلَقْنَٰهُم مِّن طِينٍ لَّازِبٍۭ", tafsir: `` },
            { text: "بَلْ عَجِبْتَ وَيَسْخَرُونَ", tafsir: `` },
            { text: "وَإِذَا ذُكِّرُوا۟ لَا يَذْكُرُونَ", tafsir: `` },
            { text: "وَإِذَا رَأَوْا۟ ءَايَةً يَسْتَسْخِرُونَ", tafsir: `` },
            { text: "وَقَالُوٓا۟ إِنْ هَٰذَآ إِلَّا سِحْرٌ مُّبِينٌ", tafsir: `` },
            { text: "أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ", tafsir: `` },
            { text: "أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ", tafsir: `` },
            { text: "قُلْ نَعَمْ وَأَنتُمْ دَٰخِرُونَ", tafsir: `` },
            { text: "فَإِنَّمَا هِىَ زَجْرَةٌ وَٰحِدَةٌ فَإِذَا هُمْ يَنظُرُونَ", tafsir: `` },
            { text: "وَقَالُوا۟ يَٰوَيْلَنَا هَٰذَا يَوْمُ ٱلدِّينِ", tafsir: `` },
            { text: "هَٰذَا يَوْمُ ٱلْفَصْلِ ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ", tafsir: `` },
            { text: "ٱحْشُرُوا۟ ٱلَّذِينَ ظَلَمُوا۟ وَأَزْوَٰجَهُمْ وَمَا كَانُوا۟ يَعْبُدُونَ", tafsir: `` },
            { text: "مِن دُونِ ٱللَّهِ فَٱهْدُوهُمْ إِلَىٰ صِرَٰطِ ٱلْجَحِيمِ", tafsir: `` },
            { text: "وَقِفُوهُمْ إِنَّهُم مَّسْـُٔولُونَ", tafsir: `` },
            { text: "مَا لَكُمْ لَا تَنَاصَرُونَ", tafsir: `` },
            { text: "بَلْ هُمُ ٱلْيَوْمَ مُسْتَسْلِمُونَ", tafsir: `` },
            { text: "وَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ", tafsir: `` },
            { text: "قَالُوٓا۟ إِنَّكُمْ كُنتُمْ تَأْتُونَنَا عَنِ ٱلْيَمِينِ", tafsir: `` },
            { text: "قَالُوا۟ بَل لَّمْ تَكُونُوا۟ مُؤْمِنِينَ", tafsir: `` },
            { text: "وَمَا كَانَ لَنَا عَلَيْكُم مِّن سُلْطَٰنٍۭ بَلْ كُنتُمْ قَوْمًا طَٰغِينَ", tafsir: `` },
            { text: "فَحَقَّ عَلَيْنَا قَوْلُ رَبِّنَآ إِنَّا لَذَآئِقُونَ", tafsir: `` },
            { text: "فَأَغْوَيْنَٰكُمْ إِنَّا كُنَّا غَٰوِينَ", tafsir: `` },
            { text: "فَإِنَّهُمْ يَوْمَئِذٍ فِى ٱلْعَذَابِ مُشْتَرِكُونَ", tafsir: `` },
            { text: "إِنَّا كَذَٰلِكَ نَفْعَلُ بِٱلْمُجْرِمِينَ", tafsir: `` },
            { text: "إِنَّهُمْ كَانُوٓا۟ إِذَا قِيلَ لَهُمْ لَآ إِلَٰهَ إِلَّا ٱللَّهُ يَسْتَكْبِرُونَ", tafsir: `` },
            { text: "وَيَقُولُونَ أَئِنَّا لَتَارِكُوٓا۟ ءَالِهَتِنَا لِشَاعِرٍ مَّجْنُونٍۭ", tafsir: `` },
            { text: "بَلْ جَآءَ بِٱلْحَقِّ وَصَدَّقَ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "إِنَّكُمْ لَذَآئِقُوا۟ ٱلْعَذَابِ ٱلْأَلِيمِ", tafsir: `` },
            { text: "وَمَا تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "أُو۟لَٰٓئِكَ لَهُمْ رِزْقٌ مَّعْلُومٌ", tafsir: `` },
            { text: "فَوَٰكِهُ وَهُم مُّكْرَمُونَ", tafsir: `` },
            { text: "فِى جَنَّٰتِ ٱلنَّعِيمِ", tafsir: `` },
            { text: "عَلَىٰ سُرُرٍ مُّتَقَٰبِلِينَ", tafsir: `` },
            { text: "يُطَافُ عَلَيْهِم بِكَأْسٍ مِّن مَّعِينٍۭ", tafsir: `` },
            { text: "بَيْضَآءَ لَذَّةٍ لِّلشَّٰرِبِينَ", tafsir: `` },
            { text: "لَا فِيهَا غَوْلٌ وَلَا هُمْ عَنْهَا يُنزَفُونَ", tafsir: `` },
            { text: "وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ عِينٌ", tafsir: `` },
            { text: "كَأَنَّهُنَّ بَيْضٌ مَّكْنُونٌ", tafsir: `` },
            { text: "فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍ يَتَسَآءَلُونَ", tafsir: `` },
            { text: "قَالَ قَآئِلٌ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌ", tafsir: `` },
            { text: "يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ", tafsir: `` },
            { text: "أَءِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَٰمًا أَءِنَّا لَمَدِينُونَ", tafsir: `` },
            { text: "قَالَ هَلْ أَنتُم مُّطَّلِعُونَ", tafsir: `` },
            { text: "فَٱطَّلَعَ فَرَءَاهُ فِى سَوَآءِ ٱلْجَحِيمِ", tafsir: `` },
            { text: "قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرْدِينِ", tafsir: `` },
            { text: "وَلَوْلَا نِعْمَةُ رَبِّى لَكُنتُ مِنَ ٱلْمُحْضَرِينَ", tafsir: `` },
            { text: "أَفَمَا نَحْنُ بِمَيِّتِينَ", tafsir: `` },
            { text: "إِلَّا مَوْتَتَنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُعَذَّبِينَ", tafsir: `` },
            { text: "إِنَّ هَٰذَا لَهُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "لِمِثْلِ هَٰذَا فَلْيَعْمَلِ ٱلْعَٰمِلُونَ", tafsir: `` },
            { text: "أَذَٰلِكَ خَيْرٌ نُّزُلًا أَمْ شَجَرَةُ ٱلزَّقُّومِ", tafsir: `` },
            { text: "إِنَّا جَعَلْنَٰهَا فِتْنَةً لِّلظَّٰلِمِينَ", tafsir: `` },
            { text: "إِنَّهَا شَجَرَةٌ تَخْرُجُ فِىٓ أَصْلِ ٱلْجَحِيمِ", tafsir: `` },
            { text: "طَلْعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّيَٰطِينِ", tafsir: `` },
            { text: "فَإِنَّهُمْ لَـَٔاكِلُونَ مِنْهَا فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ", tafsir: `` },
            { text: "ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْبًا مِّنْ حَمِيمٍ", tafsir: `` },
            { text: "ثُمَّ إِنَّ مَرْجِعَهُمْ لَإِلَى ٱلْجَحِيمِ", tafsir: `` },
            { text: "إِنَّهُمْ أَلْفَوْا۟ ءَابَآءَهُمْ ضَآلِّينَ", tafsir: `` },
            { text: "فَهُمْ عَلَىٰٓ ءَاثَٰرِهِمْ يُهْرَعُونَ", tafsir: `` },
            { text: "وَلَقَدْ ضَلَّ قَبْلَهُمْ أَكْثَرُ ٱلْأَوَّلِينَ", tafsir: `` },
            { text: "وَلَقَدْ أَرْسَلْنَا فِيهِم مُّنذِرِينَ", tafsir: `` },
            { text: "فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُنذَرِينَ", tafsir: `` },
            { text: "إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "وَلَقَدْ نَادَىٰنَا نُوحٌ فَلَنِعْمَ ٱلْمُجِيبُونَ", tafsir: `` },
            { text: "وَنَجَّيْنَٰهُ وَأَهْلَهُۥ مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ", tafsir: `` },
            { text: "وَجَعَلْنَا ذُرِّيَّتَهُۥ هُمُ ٱلْبَاقِينَ", tafsir: `` },
            { text: "وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ", tafsir: `` },
            { text: "سَلَٰمٌ عَلَىٰ نُوحٍ فِى ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ", tafsir: `` },
            { text: "ثُمَّ أَغْرَقْنَا ٱلْـَٔاخَرِينَ", tafsir: `` },
            { text: "وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ", tafsir: `` },
            { text: "إِذْ جَآءَ رَبَّهُۥ بِقَلْبٍ سَلِيمٍ", tafsir: `` },
            { text: "إِذْ قَالَ لِأَبِيهِ وَقَوْمِهِۦ مَاذَا تَعْبُدُونَ", tafsir: `` },
            { text: "أَئِفْكًا ءَالِهَةً دُونَ ٱللَّهِ تُرِيدُونَ", tafsir: `` },
            { text: "فَمَا ظَنُّكُم بِرَبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "فَنَظَرَ نَظْرَةً فِى ٱلنُّجُومِ", tafsir: `` },
            { text: "فَقَالَ إِنِّى سَقِيمٌ", tafsir: `` },
            { text: "فَتَوَلَّوْا۟ عَنْهُ مُدْبِرِينَ", tafsir: `` },
            { text: "فَرَاغَ إِلَىٰٓ ءَالِهَتِهِمْ فَقَالَ أَلَا تَأْكُلُونَ", tafsir: `` },
            { text: "مَا لَكُمْ لَا تَنطِقُونَ", tafsir: `` },
            { text: "فَرَاغَ عَلَيْهِمْ ضَرْبًۢا بِٱلْيَمِينِ", tafsir: `` },
            { text: "فَأَقْبَلُوٓا۟ إِلَيْهِ يَزِفُّونَ", tafsir: `` },
            { text: "قَالَ أَتَعْبُدُونَ مَا تَنْحِتُونَ", tafsir: `` },
            { text: "وَٱللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ", tafsir: `` },
            { text: "قَالُوا۟ ٱبْنُوا۟ لَهُۥ بُنْيَٰنًا فَأَلْقُوهُ فِى ٱلْجَحِيمِ", tafsir: `` },
            { text: "فَأَرَادُوا۟ بِهِۦ كَيْدًا فَجَعَلْنَٰهُمُ ٱلْأَسْفَلِينَ", tafsir: `` },
            { text: "وَقَالَ إِنِّى ذَاهِبٌ إِلَىٰ رَبِّى سَيَهْدِينِ", tafsir: `` },
            { text: "رَبِّ هَبْ لِى مِنَ ٱلصَّٰلِحِينَ", tafsir: `` },
            { text: "فَبَشَّرْنَٰهُ بِغُلَٰمٍ حَلِيمٍ", tafsir: `` },
            { text: "فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ", tafsir: `` },
            { text: "فَلَمَّآ أَسْلَمَا وَتَلَّهُۥ لِلْجَبِينِ", tafsir: `` },
            { text: "وَنَٰدَيْنَٰهُ أَن يَٰٓإِبْرَٰهِيمُ", tafsir: `` },
            { text: "قَدْ صَدَّقْتَ ٱلرُّءْيَآ إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "إِنَّ هَٰذَا لَهُوَ ٱلْبَلَٰٓؤُا۟ ٱلْمُبِينُ", tafsir: `` },
            { text: "وَفَدَيْنَٰهُ بِذِبْحٍ عَظِيمٍ", tafsir: `` },
            { text: "وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ", tafsir: `` },
            { text: "سَلَٰمٌ عَلَىٰٓ إِبْرَٰهِيمَ", tafsir: `` },
            { text: "كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ", tafsir: `` },
            { text: "وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّا مِّنَ ٱلصَّٰلِحِينَ", tafsir: `` },
            { text: "وَبَٰرَكْنَا عَلَيْهِ وَعَلَىٰٓ إِسْحَٰقَ وَمِن ذُرِّيَّتِهِمَا مُحْسِنٌ وَظَالِمٌ لِّنَفْسِهِۦ مُبِينٌ", tafsir: `` },
            { text: "وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَٰرُونَ", tafsir: `` },
            { text: "وَنَجَّيْنَٰهُمَا وَقَوْمَهُمَا مِنَ ٱلْكَرْبِ ٱلْعَظِيمِ", tafsir: `` },
            { text: "وَنَصَرْنَٰهُمْ فَكَانُوا۟ هُمُ ٱلْغَٰلِبِينَ", tafsir: `` },
            { text: "وَءَاتَيْنَٰهُمَا ٱلْكِتَٰبَ ٱلْمُسْتَبِينَ", tafsir: `` },
            { text: "وَهَدَيْنَٰهُمَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ", tafsir: `` },
            { text: "وَتَرَكْنَا عَلَيْهِمَا فِى ٱلْـَٔاخِرِينَ", tafsir: `` },
            { text: "سَلَٰمٌ عَلَىٰ مُوسَىٰ وَهَٰرُونَ", tafsir: `` },
            { text: "إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "إِنَّهُمَا مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ", tafsir: `` },
            { text: "وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ", tafsir: `` },
            { text: "أَتَدْعُونَ بَعْلًا وَتَذَرُونَ أَحْسَنَ ٱلْخَٰلِقِينَ", tafsir: `` },
            { text: "ٱللَّهَ رَبَّكُمْ وَرَبَّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ", tafsir: `` },
            { text: "فَكَذَّبُوهُ فَإِنَّهُمْ لَمُحْضَرُونَ", tafsir: `` },
            { text: "إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "وَتَرَكْنَا عَلَيْهِ فِى ٱلْـَٔاخِرِينَ", tafsir: `` },
            { text: "سَلَٰمٌ عَلَىٰٓ إِلْ يَاسِينَ", tafsir: `` },
            { text: "إِنَّا كَذَٰلِكَ نَجْزِى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "إِنَّهُۥ مِنْ عِبَادِنَا ٱلْمُؤْمِنِينَ", tafsir: `` },
            { text: "وَإِنَّ لُوطًا لَّمِنَ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "إِذْ نَجَّيْنَٰهُ وَأَهْلَهُۥٓ أَجْمَعِينَ", tafsir: `` },
            { text: "إِلَّا عَجُوزًا فِى ٱلْغَٰبِرِينَ", tafsir: `` },
            { text: "ثُمَّ دَمَّرْنَا ٱلْـَٔاخَرِينَ", tafsir: `` },
            { text: "وَإِنَّكُمْ لَتَمُرُّونَ عَلَيْهِم مُّصْبِحِينَ", tafsir: `` },
            { text: "وَبِٱلَّيْلِ أَفَلَا تَعْقِلُونَ", tafsir: `` },
            { text: "وَإِنَّ يُونُسَ لَمِنَ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "إِذْ أَبَقَ إِلَى ٱلْفُلْكِ ٱلْمَشْحُونِ", tafsir: `` },
            { text: "فَسَاهَمَ فَكَانَ مِنَ ٱلْمُدْحَضِينَ", tafsir: `` },
            { text: "فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌ", tafsir: `` },
            { text: "فَلَوْلَآ أَنَّهُۥ كَانَ مِنَ ٱلْمُسَبِّحِينَ", tafsir: `` },
            { text: "لَلَبِثَ فِى بَطْنِهِۦٓ إِلَىٰ يَوْمِ يُبْعَثُونَ", tafsir: `` },
            { text: "فَنَبَذْنَٰهُ بِٱلْعَرَآءِ وَهُوَ سَقِيمٌ", tafsir: `` },
            { text: "وَأَنۢبَتْنَا عَلَيْهِ شَجَرَةً مِّن يَقْطِينٍ", tafsir: `` },
            { text: "وَأَرْسَلْنَٰهُ إِلَىٰ مِا۟ئَةِ أَلْفٍ أَوْ يَزِيدُونَ", tafsir: `` },
            { text: "فَـَٔامَنُوا۟ فَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍ", tafsir: `` },
            { text: "فَٱسْتَفْتِهِمْ أَلِرَبِّكَ ٱلْبَنَاتُ وَلَهُمُ ٱلْبَنُونَ", tafsir: `` },
            { text: "أَمْ خَلَقْنَا ٱلْمَلَٰٓئِكَةَ إِنَٰثًا وَهُمْ شَٰهِدُونَ", tafsir: `` },
            { text: "أَلَآ إِنَّهُم مِّنْ إِفْكِهِمْ لَيَقُولُونَ", tafsir: `` },
            { text: "وَلَدَ ٱللَّهُ وَإِنَّهُمْ لَكَٰذِبُونَ", tafsir: `` },
            { text: "أَصْطَفَى ٱلْبَنَاتِ عَلَى ٱلْبَنِينَ", tafsir: `` },
            { text: "مَا لَكُمْ كَيْفَ تَحْكُمُونَ", tafsir: `` },
            { text: "أَفَلَا تَذَكَّرُونَ", tafsir: `` },
            { text: "أَمْ لَكُمْ سُلْطَٰنٌ مُّبِينٌ", tafsir: `` },
            { text: "فَأْتُوا۟ بِكِتَٰبِكُمْ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `` },
            { text: "وَجَعَلُوا۟ بَيْنَهُۥ وَبَيْنَ ٱلْجِنَّةِ نَسَبًا وَلَقَدْ عَلِمَتِ ٱلْجِنَّةُ إِنَّهُمْ لَمُحْضَرُونَ", tafsir: `` },
            { text: "سُبْحَٰنَ ٱللَّهِ عَمَّا يَصِفُونَ", tafsir: `` },
            { text: "إِلَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "فَإِنَّكُمْ وَمَا تَعْبُدُونَ", tafsir: `` },
            { text: "مَآ أَنتُمْ عَلَيْهِ بِفَٰتِنِينَ", tafsir: `` },
            { text: "إِلَّا مَنْ هُوَ صَالِ ٱلْجَحِيمِ", tafsir: `` },
            { text: "وَمَا مِنَّآ إِلَّا لَهُۥ مَقَامٌ مَّعْلُومٌ", tafsir: `` },
            { text: "وَإِنَّا لَنَحْنُ ٱلصَّآفُّونَ", tafsir: `` },
            { text: "وَإِنَّا لَنَحْنُ ٱلْمُسَبِّحُونَ", tafsir: `` },
            { text: "وَإِن كَانُوا۟ لَيَقُولُونَ", tafsir: `` },
            { text: "لَوْ أَنَّ عِندَنَا ذِكْرًا مِّنَ ٱلْأَوَّلِينَ", tafsir: `` },
            { text: "لَكُنَّا عِبَادَ ٱللَّهِ ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "فَكَفَرُوا۟ بِهِۦ فَسَوْفَ يَعْلَمُونَ", tafsir: `` },
            { text: "وَلَقَدْ سَبَقَتْ كَلِمَتُنَا لِعِبَادِنَا ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "إِنَّهُمْ لَهُمُ ٱلْمَنصُورُونَ", tafsir: `` },
            { text: "وَإِنَّ جُندَنَا لَهُمُ ٱلْغَٰلِبُونَ", tafsir: `` },
            { text: "فَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ", tafsir: `` },
            { text: "وَأَبْصِرْهُمْ فَسَوْفَ يُبْصِرُونَ", tafsir: `` },
            { text: "أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ", tafsir: `` },
            { text: "فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَآءَ صَبَاحُ ٱلْمُنذَرِينَ", tafsir: `` },
            { text: "وَتَوَلَّ عَنْهُمْ حَتَّىٰ حِينٍ", tafsir: `` },
            { text: "وَأَبْصِرْ فَسَوْفَ يُبْصِرُونَ", tafsir: `` },
            { text: "سُبْحَٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ", tafsir: `` },
            { text: "وَسَلَٰمٌ عَلَى ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "وَٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `` }
        ]
    },
    38: { // سورة ص
        name: "ص",
        basmalaTafsir: ``,
        verses: [
            { text: "صٓ وَٱلْقُرْءَانِ ذِى ٱلذِّكْرِ", tafsir: `` },
            { text: "بَلِ ٱلَّذِينَ كَفَرُوا۟ فِى عِزَّةٍ وَشِقَاقٍ", tafsir: `` },
            { text: "كَمْ أَهْلَكْنَا مِن قَبْلِهِم مِّن قَرْنٍ فَنَادَوا۟ وَّلَاتَ حِينَ مَنَاصٍ", tafsir: `` },
            { text: "وَعَجِبُوٓا۟ أَن جَآءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ ٱلْكَٰفِرُونَ هَٰذَا سَٰحِرٌ كَذَّابٌ", tafsir: `` },
            { text: "أَجَعَلَ ٱلْـَٔالِهَةَ إِلَٰهًا وَٰحِدًا إِنَّ هَٰذَا لَشَىْءٌ عُجَابٌ", tafsir: `` },
            { text: "وَٱنطَلَقَ ٱلْمَلَأُ مِنْهُمْ أَنِ ٱمْشُوا۟ وَٱصْبِرُوا۟ عَلَىٰٓ ءَالِهَتِكُمْ إِنَّ هَٰذَا لَشَىْءٌ يُرَادُ", tafsir: `` },
            { text: "مَا سَمِعْنَا بِهَٰذَا فِى ٱلْمِلَّةِ ٱلْـَٔاخِرَةِ إِنْ هَٰذَآ إِلَّا ٱخْتِلَٰقٌ", tafsir: `` },
            { text: "أَءُنزِلَ عَلَيْهِ ٱلذِّكْرُ مِنۢ بَيْنِنَا بَلْ هُمْ فِى شَكٍّ مِّن ذِكْرِى بَل لَّمَّا يَذُوقُوا۟ عَذَابِ", tafsir: `` },
            { text: "أَمْ عِندَهُمْ خَزَآئِنُ رَحْمَةِ رَبِّكَ ٱلْعَزِيزِ ٱلْوَهَّابِ", tafsir: `` },
            { text: "أَمْ لَهُم مُّلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا فَلْيَرْتَقُوا۟ فِى ٱلْأَسْبَٰبِ", tafsir: `` },
            { text: "جُندٌ مَّا هُنَالِكَ مَهْزُومٌ مِّنَ ٱلْأَحْزَابِ", tafsir: `` },
            { text: "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَعَادٌ وَفِرْعَوْنُ ذُو ٱلْأَوْتَادِ", tafsir: `` },
            { text: "وَثَمُودُ وَقَوْمُ لُوطٍ وَأَصْحَٰبُ لْـَٔيْكَةِ أُو۟لَٰٓئِكَ ٱلْأَحْزَابُ", tafsir: `` },
            { text: "إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ", tafsir: `` },
            { text: "وَمَا يَنظُرُ هَٰٓؤُلَآءِ إِلَّا صَيْحَةً وَٰحِدَةً مَّا لَهَا مِن فَوَاقٍ", tafsir: `` },
            { text: "وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبْلَ يَوْمِ ٱلْحِسَابِ", tafsir: `` },
            { text: "ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ إِنَّهُۥٓ أَوَّابٌ", tafsir: `` },
            { text: "إِنَّا سَخَّرْنَا ٱلْجِبَالَ مَعَهُۥ يُسَبِّحْنَ بِٱلْعَشِىِّ وَٱلْإِشْرَاقِ", tafsir: `` },
            { text: "وَٱلطَّيْرَ مَحْشُورَةً كُلٌّ لَّهُۥٓ أَوَّابٌ", tafsir: `` },
            { text: "وَشَدَدْنَا مُلْكَهُۥ وَءَاتَيْنَٰهُ ٱلْحِكْمَةَ وَفَصْلَ ٱلْخِطَابِ", tafsir: `` },
            { text: "وَهَلْ أَتَىٰكَ نَبَؤُا۟ ٱلْخَصْمِ إِذْ تَسَوَّرُوا۟ ٱلْمِحْرَابَ", tafsir: `` },
            { text: "إِذْ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنْهُمْ قَالُوا۟ لَا تَخَفْ خَصْمَانِ بَغَىٰ بَعْضُنَا عَلَىٰ بَعْضٍ فَٱحْكُم بَيْنَنَا بِٱلْحَقِّ وَلَا تُشْطِطْ وَٱهْدِنَآ إِلَىٰ سَوَآءِ ٱلصِّرَٰطِ", tafsir: `` },
            { text: "إِنَّ هَٰذَآ أَخِى لَهُۥ تِسْعٌ وَتِسْعُونَ نَعْجَةً وَلِىَ نَعْجَةٌ وَٰحِدَةٌ فَقَالَ أَكْفِلْنِيهَا وَعَزَّنِى فِى ٱلْخِطَابِ", tafsir: `` },
            { text: "قَالَ لَقَدْ ظَلَمَكَ بِسُؤَالِ نَعْجَتِكَ إِلَىٰ نِعَاجِهِۦ وَإِنَّ كَثِيرًا مِّنَ ٱلْخُلَطَآءِ لَيَبْغِى بَعْضُهُمْ عَلَىٰ بَعْضٍ إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَقَلِيلٌ مَّا هُمْ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّٰهُ فَٱسْتَغْفَرَ رَبَّهُۥ وَخَرَّ رَاكِعًا وَأَنَابَ", tafsir: `` },
            { text: "فَغَفَرْنَا لَهُۥ ذَٰلِكَ وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ", tafsir: `` },
            { text: "يَٰدَاوُۥدُ إِنَّا جَعَلْنَٰكَ خَلِيفَةً فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ", tafsir: `` },
            { text: "وَمَا خَلَقْنَا ٱلسَّمَآءَ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا بَٰطِلًا ذَٰلِكَ ظَنُّ ٱلَّذِينَ كَفَرُوا۟ فَوَيْلٌ لِّلَّذِينَ كَفَرُوا۟ مِنَ ٱلنَّارِ", tafsir: `` },
            { text: "أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ", tafsir: `` },
            { text: "كِتَٰبٌ أَنزَلْنَٰهُ إِلَيْكَ مُبَٰرَكٌ لِّيَدَّبَّرُوٓا۟ ءَايَٰتِهِۦ وَلِيَتَذَكَّرَ أُو۟لُوا۟ ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "وَوَهَبْنَا لِدَاوُۥدَ سُلَيْمَٰنَ نِعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ", tafsir: `` },
            { text: "إِذْ عُرِضَ عَلَيْهِ بِٱلْعَشِىِّ ٱلصَّٰفِنَٰتُ ٱلْجِيَادُ", tafsir: `` },
            { text: "فَقَالَ إِنِّىٓ أَحْبَبْتُ حُبَّ ٱلْخَيْرِ عَن ذِكْرِ رَبِّى حَتَّىٰ تَوَارَتْ بِٱلْحِجَابِ", tafsir: `` },
            { text: "رُدُّوهَا عَلَىَّ فَطَفِقَ مَسْحًۢا بِٱلسُّوقِ وَٱلْأَعْنَاقِ", tafsir: `` },
            { text: "وَلَقَدْ فَتَنَّا سُلَيْمَٰنَ وَأَلْقَيْنَا عَلَىٰ كُرْسِيِّهِۦ جَسَدًا ثُمَّ أَنَابَ", tafsir: `` },
            { text: "قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًا لَّا يَنۢبَغِى لِأَحَدٍ مِّنۢ بَعْدِىٓ إِنَّكَ أَنتَ ٱلْوَهَّابُ", tafsir: `` },
            { text: "فَسَخَّرْنَا لَهُ ٱلرِّيحَ تَجْرِى بِأَمْرِهِۦ رُخَآءً حَيْثُ أَصَابَ", tafsir: `` },
            { text: "وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٍ وَغَوَّاصٍ", tafsir: `` },
            { text: "وَءَاخَرِينَ مُقَرَّنِينَ فِى ٱلْأَصْفَادِ", tafsir: `` },
            { text: "هَٰذَا عَطَآؤُنَا فَٱمْنُنْ أَوْ أَمْسِكْ بِغَيْرِ حِسَابٍ", tafsir: `` },
            { text: "وَإِنَّ لَهُۥ عِندَنَا لَزُلْفَىٰ وَحُسْنَ مَـَٔابٍ", tafsir: `` },
            { text: "وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍ وَعَذَابٍ", tafsir: `` },
            { text: "ٱرْكُضْ بِرِجْلِكَ هَٰذَا مُغْتَسَلٌۢ بَارِدٌ وَشَرَابٌ", tafsir: `` },
            { text: "وَوَهَبْنَا لَهُۥٓ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةً مِّنَّا وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "وَخُذْ بِيَدِكَ ضِغْثًا فَٱضْرِب بِّهِۦ وَلَا تَحْنَثْ إِنَّا وَجَدْنَٰهُ صَابِرًا نِّعْمَ ٱلْعَبْدُ إِنَّهُۥٓ أَوَّابٌ", tafsir: `` },
            { text: "وَٱذْكُرْ عِبَٰدَنَآ إِبْرَٰهِيمَ وَإِسْحَٰقَ وَيَعْقُوبَ أُو۟لِى ٱلْأَيْدِى وَٱلْأَبْصَٰرِ", tafsir: `` },
            { text: "إِنَّآ أَخْلَصْنَٰهُم بِخَالِصَةٍ ذِكْرَى ٱلدَّارِ", tafsir: `` },
            { text: "وَإِنَّهُمْ عِندَنَا لَمِنَ ٱلْمُصْطَفَيْنَ ٱلْأَخْيَارِ", tafsir: `` },
            { text: "وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ وَكُلٌّ مِّنَ ٱلْأَخْيَارِ", tafsir: `` },
            { text: "هَٰذَا ذِكْرٌ وَإِنَّ لِلْمُتَّقِينَ لَحُسْنَ مَـَٔابٍ", tafsir: `` },
            { text: "جَنَّٰتِ عَدْنٍ مُّفَتَّحَةً لَّهُمُ ٱلْأَبْوَٰبُ", tafsir: `` },
            { text: "مُتَّكِـِٔينَ فِيهَا يَدْعُونَ فِيهَا بِفَٰكِهَةٍ كَثِيرَةٍ وَشَرَابٍ", tafsir: `` },
            { text: "وَعِندَهُمْ قَٰصِرَٰتُ ٱلطَّرْفِ أَتْرَابٌ", tafsir: `` },
            { text: "هَٰذَا مَا تُوعَدُونَ لِيَوْمِ ٱلْحِسَابِ", tafsir: `` },
            { text: "إِنَّ هَٰذَا لَرِزْقُنَا مَا لَهُۥ مِن نَّفَادٍ", tafsir: `` },
            { text: "هَٰذَا وَإِنَّ لِلطَّٰغِينَ لَشَرَّ مَـَٔابٍ", tafsir: `` },
            { text: "جَهَنَّمَ يَصْلَوْنَهَا فَبِئْسَ ٱلْمِهَادُ", tafsir: `` },
            { text: "هَٰذَا فَلْيَذُوقُوهُ حَمِيمٌ وَغَسَّاقٌ", tafsir: `` },
            { text: "وَءَاخَرُ مِن شَكْلِهِۦٓ أَزْوَٰجٌ", tafsir: `` },
            { text: "هَٰذَا فَوْجٌ مُّقْتَحِمٌ مَّعَكُمْ لَا مَرْحَبًۢا بِهِمْ إِنَّهُمْ صَالُوا۟ ٱلنَّارِ", tafsir: `` },
            { text: "قَالُوا۟ بَلْ أَنتُمْ لَا مَرْحَبًۢا بِكُمْ أَنتُمْ قَدَّمْتُمُوهُ لَنَا فَبِئْسَ ٱلْقَرَارُ", tafsir: `` },
            { text: "قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَٰذَا فَزِدْهُ عَذَابًا ضِعْفًا فِى ٱلنَّارِ", tafsir: `` },
            { text: "وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالًا كُنَّا نَعُدُّهُم مِّنَ ٱلْأَشْرَارِ", tafsir: `` },
            { text: "أَتَّخَذْنَٰهُمْ سِخْرِيًّا أَمْ زَاغَتْ عَنْهُمُ ٱلْأَبْصَٰرُ", tafsir: `` },
            { text: "إِنَّ ذَٰلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ ٱلنَّارِ", tafsir: `` },
            { text: "قُلْ إِنَّمَآ أَنَا۠ مُنذِرٌ وَمَا مِنْ إِلَٰهٍ إِلَّا ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ", tafsir: `` },
            { text: "رَبُّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ٱلْعَزِيزُ ٱلْغَفَّٰرُ", tafsir: `` },
            { text: "قُلْ هُوَ نَبَؤٌا۟ عَظِيمٌ", tafsir: `` },
            { text: "أَنتُمْ عَنْهُ مُعْرِضُونَ", tafsir: `` },
            { text: "مَا كَانَ لِىَ مِنْ عِلْمٍۭ بِٱلْمَلَإِ ٱلْأَعْلَىٰٓ إِذْ يَخْتَصِمُونَ", tafsir: `` },
            { text: "إِن يُوحَىٰٓ إِلَىَّ إِلَّآ أَنَّمَآ أَنَا۠ نَذِيرٌ مُّبِينٌ", tafsir: `` },
            { text: "إِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى خَٰلِقٌۢ بَشَرًا مِّن طِينٍ", tafsir: `` },
            { text: "فَإِذَا سَوَّيْتُهُۥ وَنَفَخْتُ فِيهِ مِن رُّوحِى فَقَعُوا۟ لَهُۥ سَٰجِدِينَ", tafsir: `` },
            { text: "فَسَجَدَ ٱلْمَلَٰٓئِكَةُ كُلُّهُمْ أَجْمَعُونَ", tafsir: `` },
            { text: "إِلَّآ إِبْلِيسَ ٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "قَالَ يَٰٓإِبْلِيسُ مَا مَنَعَكَ أَن تَسْجُدَ لِمَا خَلَقْتُ بِيَدَىَّ أَسْتَكْبَرْتَ أَمْ كُنتَ مِنَ ٱلْعَالِينَ", tafsir: `` },
            { text: "قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ", tafsir: `` },
            { text: "قَالَ فَٱخْرُجْ مِنْهَا فَإِنَّكَ رَجِيمٌ", tafsir: `` },
            { text: "وَإِنَّ عَلَيْكَ لَعْنَتِىٓ إِلَىٰ يَوْمِ ٱلدِّينِ", tafsir: `` },
            { text: "قَالَ رَبِّ فَأَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ", tafsir: `` },
            { text: "قَالَ فَإِنَّكَ مِنَ ٱلْمُنظَرِينَ", tafsir: `` },
            { text: "إِلَىٰ يَوْمِ ٱلْوَقْتِ ٱلْمَعْلُومِ", tafsir: `` },
            { text: "قَالَ فَبِعِزَّتِكَ لَأُغْوِيَنَّهُمْ أَجْمَعِينَ", tafsir: `` },
            { text: "إِلَّا عِبَادَكَ مِنْهُمُ ٱلْمُخْلَصِينَ", tafsir: `` },
            { text: "قَالَ فَٱلْحَقُّ وَٱلْحَقَّ أَقُولُ", tafsir: `` },
            { text: "لَأَمْلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنْهُمْ أَجْمَعِينَ", tafsir: `` },
            { text: "قُلْ مَآ أَسْـَٔلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَآ أَنَا۠ مِنَ ٱلْمُتَكَلِّفِينَ", tafsir: `` },
            { text: "إِنْ هُوَ إِلَّا ذِكْرٌ لِّلْعَٰلَمِينَ", tafsir: `` },
            { text: "وَلَتَعْلَمُنَّ نَبَأَهُۥ بَعْدَ حِينٍۭ", tafsir: `` }
        ]
    },
    39: { // سورة الزمر
        name: "الزمر",
        basmalaTafsir: ``,
        verses: [
            { text: "تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ", tafsir: `` },
            { text: "إِنَّآ أَنزَلْنَآ إِلَيْكَ ٱلْكِتَٰبَ بِٱلْحَقِّ فَٱعْبُدِ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ", tafsir: `` },
            { text: "أَلَا لِلَّهِ ٱلدِّينُ ٱلْخَالِصُ وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلْفَىٰٓ إِنَّ ٱللَّهَ يَحْكُمُ بَيْنَهُمْ فِى مَا هُمْ فِيهِ يَخْتَلِفُونَ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ كَٰذِبٌ كَفَّارٌ", tafsir: `` },
            { text: "لَّوْ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدًا لَّٱصْطَفَىٰ مِمَّا يَخْلُقُ مَا يَشَآءُ سُبْحَٰنَهُۥ هُوَ ٱللَّهُ ٱلْوَٰحِدُ ٱلْقَهَّارُ", tafsir: `` },
            { text: "خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ بِٱلْحَقِّ يُكَوِّرُ ٱلَّيْلَ عَلَى ٱلنَّهَارِ وَيُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّيْلِ وَسَخَّرَ ٱلشَّمْسَ وَٱلْقَمَرَ كُلٌّ يَجْرِى لِأَجَلٍ مُّسَمًّى أَلَا هُوَ ٱلْعَزِيزُ ٱلْغَفَّٰرُ", tafsir: `` },
            { text: "خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ ثُمَّ جَعَلَ مِنْهَا زَوْجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلْأَنْعَٰمِ ثَمَٰنِيَةَ أَزْوَٰجٍ يَخْلُقُكُمْ فِى بُطُونِ أُمَّهَٰتِكُمْ خَلْقًا مِّنۢ بَعْدِ خَلْقٍ فِى ظُلُمَٰتٍ ثَلَٰثٍ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ لَهُ ٱلْمُلْكُ لَآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُصْرَفُونَ", tafsir: `` },
            { text: "إِن تَكْفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِىٌّ عَنكُمْ وَلَا يَرْضَىٰ لِعِبَادِهِ ٱلْكُفْرَ وَإِن تَشْكُرُوا۟ يَرْضَهُ لَكُمْ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `` },
            { text: "وَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَا رَبَّهُۥ مُنِيبًا إِلَيْهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعْمَةً مِّنْهُ نَسِىَ مَا كَانَ يَدْعُوٓا۟ إِلَيْهِ مِن قَبْلُ وَجَعَلَ لِلَّهِ أَندَادًا لِّيُضِلَّ عَن سَبِيلِهِۦ قُلْ تَمَتَّعْ بِكُفْرِكَ قَلِيلًا إِنَّكَ مِنْ أَصْحَٰبِ ٱلنَّارِ", tafsir: `` },
            { text: "أَمَّنْ هُوَ قَٰنِتٌ ءَانَآءَ ٱلَّيْلِ سَاجِدًا وَقَآئِمًا يَحْذَرُ ٱلْـَٔاخِرَةَ وَيَرْجُوا۟ رَحْمَةَ رَبِّهِۦ قُلْ هَلْ يَسْتَوِى ٱلَّذِينَ يَعْلَمُونَ وَٱلَّذِينَ لَا يَعْلَمُونَ إِنَّمَا يَتَذَكَّرُ أُو۟لُوا۟ ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "قُلْ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمْ لِلَّذِينَ أَحْسَنُوا۟ فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةٌ وَأَرْضُ ٱللَّهِ وَٰسِعَةٌ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجْرَهُم بِغَيْرِ حِسَابٍ", tafsir: `` },
            { text: "قُلْ إِنِّىٓ أُمِرْتُ أَنْ أَعْبُدَ ٱللَّهَ مُخْلِصًا لَّهُ ٱلدِّينَ", tafsir: `` },
            { text: "وَأُمِرْتُ لِأَنْ أَكُونَ أَوَّلَ ٱلْمُسْلِمِينَ", tafsir: `` },
            { text: "قُلْ إِنِّىٓ أَخَافُ إِنْ عَصَيْتُ رَبِّى عَذَابَ يَوْمٍ عَظِيمٍ", tafsir: `` },
            { text: "قُلِ ٱللَّهَ أَعْبُدُ مُخْلِصًا لَّهُۥ دِينِى", tafsir: `` },
            { text: "فَٱعْبُدُوا۟ مَا شِئْتُم مِّن دُونِهِۦ قُلْ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَا ذَٰلِكَ هُوَ ٱلْخُسْرَانُ ٱلْمُبِينُ", tafsir: `` },
            { text: "لَهُم مِّن فَوْقِهِمْ ظُلَلٌ مِّنَ ٱلنَّارِ وَمِن تَحْتِهِمْ ظُلَلٌ ذَٰلِكَ يُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥ يَٰعِبَادِ فَٱتَّقُونِ", tafsir: `` },
            { text: "وَٱلَّذِينَ ٱجْتَنَبُوا۟ ٱلطَّٰغُوتَ أَن يَعْبُدُوهَا وَأَنَابُوٓا۟ إِلَى ٱللَّهِ لَهُمُ ٱلْبُشْرَىٰ فَبَشِّرْ عِبَادِ", tafsir: `` },
            { text: "ٱلَّذِينَ يَسْتَمِعُونَ ٱلْقَوْلَ فَيَتَّبِعُونَ أَحْسَنَهُۥٓ أُو۟لَٰٓئِكَ ٱلَّذِينَ هَدَىٰهُمُ ٱللَّهُ وَأُو۟لَٰٓئِكَ هُمْ أُو۟لُوا۟ ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "أَفَمَنْ حَقَّ عَلَيْهِ كَلِمَةُ ٱلْعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِى ٱلنَّارِ", tafsir: `` },
            { text: "لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ غُرَفٌ مِّن فَوْقِهَا غُرَفٌ مَّبْنِيَّةٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ وَعْدَ ٱللَّهِ لَا يُخْلِفُ ٱللَّهُ ٱلْمِيعَادَ", tafsir: `` },
            { text: "أَلَمْ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَسَلَكَهُۥ يَنَٰبِيعَ فِى ٱلْأَرْضِ ثُمَّ يُخْرِجُ بِهِۦ زَرْعًا مُّخْتَلِفًا أَلْوَٰنُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصْفَرًّا ثُمَّ يَجْعَلُهُۥ حُطَٰمًا إِنَّ فِى ذَٰلِكَ لَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "أَفَمَن شَرَحَ ٱللَّهُ صَدْرَهُۥ لِلْإِسْلَٰمِ فَهُوَ عَلَىٰ نُورٍ مِّن رَّبِّهِۦ فَوَيْلٌ لِّلْقَٰسِيَةِ قُلُوبُهُم مِّن ذِكْرِ ٱللَّهِ أُو۟لَٰٓئِكَ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "ٱللَّهُ نَزَّلَ أَحْسَنَ ٱلْحَدِيثِ كِتَٰبًا مُّتَشَٰبِهًا مَّثَانِىَ تَقْشَعِرُّ مِنْهُ جُلُودُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُمْ ثُمَّ تَلِينُ جُلُودُهُمْ وَقُلُوبُهُمْ إِلَىٰ ذِكْرِ ٱللَّهِ ذَٰلِكَ هُدَى ٱللَّهِ يَهْدِى بِهِۦ مَن يَشَآءُ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ", tafsir: `` },
            { text: "أَفَمَن يَتَّقِى بِوَجْهِهِۦ سُوٓءَ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَقِيلَ لِلظَّٰلِمِينَ ذُوقُوا۟ مَا كُنتُمْ تَكْسِبُونَ", tafsir: `` },
            { text: "كَذَّبَ ٱلَّذِينَ مِن قَبْلِهِمْ فَأَتَىٰهُمُ ٱلْعَذَابُ مِنْ حَيْثُ لَا يَشْعُرُونَ", tafsir: `` },
            { text: "فَأَذَاقَهُمُ ٱللَّهُ ٱلْخِزْىَ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَكْبَرُ لَوْ كَانُوا۟ يَعْلَمُونَ", tafsir: `` },
            { text: "وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِى هَٰذَا ٱلْقُرْءَانِ مِن كُلِّ مَثَلٍ لَّعَلَّهُمْ يَتَذَكَّرُونَ", tafsir: `` },
            { text: "قُرْءَانًا عَرَبِيًّا غَيْرَ ذِى عِوَجٍ لَّعَلَّهُمْ يَتَّقُونَ", tafsir: `` },
            { text: "ضَرَبَ ٱللَّهُ مَثَلًا رَّجُلًا فِيهِ شُرَكَآءُ مُتَشَٰكِسُونَ وَرَجُلًا سَلَمًا لِّرَجُلٍ هَلْ يَسْتَوِيَانِ مَثَلًا ٱلْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ", tafsir: `` },
            { text: "ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ", tafsir: `` },
            { text: "فَمَنْ أَظْلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدْقِ إِذْ جَآءَهُۥٓ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْكَٰفِرِينَ", tafsir: `` },
            { text: "وَٱلَّذِى جَآءَ بِٱلصِّدْقِ وَصَدَّقَ بِهِۦٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ", tafsir: `` },
            { text: "لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ جَزَآءُ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "لِيُكَفِّرَ ٱللَّهُ عَنْهُمْ أَسْوَأَ ٱلَّذِى عَمِلُوا۟ وَيَجْزِيَهُمْ أَجْرَهُم بِأَحْسَنِ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "أَلَيْسَ ٱللَّهُ بِكَافٍ عَبْدَهُۥ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ", tafsir: `` },
            { text: "وَمَن يَهْدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّ أَلَيْسَ ٱللَّهُ بِعَزِيزٍ ذِى ٱنتِقَامٍ", tafsir: `` },
            { text: "وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ ٱللَّهُ قُلْ أَفَرَءَيْتُم مَّا تَدْعُونَ مِن دُونِ ٱللَّهِ إِنْ أَرَادَنِىَ ٱللَّهُ بِضُرٍّ هَلْ هُنَّ كَٰشِفَٰتُ ضُرِّهِۦٓ أَوْ أَرَادَنِى بِرَحْمَةٍ هَلْ هُنَّ مُمْسِكَٰتُ رَحْمَتِهِۦ قُلْ حَسْبِىَ ٱللَّهُ عَلَيْهِ يَتَوَكَّلُ ٱلْمُتَوَكِّلُونَ", tafsir: `` },
            { text: "قُلْ يَٰقَوْمِ ٱعْمَلُوا۟ عَلَىٰ مَكَانَتِكُمْ إِنِّى عَٰمِلٌ فَسَوْفَ تَعْلَمُونَ", tafsir: `` },
            { text: "مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ", tafsir: `` },
            { text: "إِنَّآ أَنزَلْنَا عَلَيْكَ ٱلْكِتَٰبَ لِلنَّاسِ بِٱلْحَقِّ فَمَنِ ٱهْتَدَىٰ فَلِنَفْسِهِۦ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ", tafsir: `` },
            { text: "ٱللَّهُ يَتَوَفَّى ٱلْأَنفُسَ حِينَ مَوْتِهَا وَٱلَّتِى لَمْ تَمُتْ فِى مَنَامِهَا فَيُمْسِكُ ٱلَّتِى قَضَىٰ عَلَيْهَا ٱلْمَوْتَ وَيُرْسِلُ ٱلْأُخْرَىٰٓ إِلَىٰٓ أَجَلٍ مُّسَمًّى إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يَتَفَكَّرُونَ", tafsir: `` },
            { text: "أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَآءَ قُلْ أَوَلَوْ كَانُوا۟ لَا يَمْلِكُونَ شَيْـًٔا وَلَا يَعْقِلُونَ", tafsir: `` },
            { text: "قُل لِّلَّهِ ٱلشَّفَٰعَةُ جَمِيعًا لَّهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ ثُمَّ إِلَيْهِ تُرْجَعُونَ", tafsir: `` },
            { text: "وَإِذَا ذُكِرَ ٱللَّهُ وَحْدَهُ ٱشْمَأَزَّتْ قُلُوبُ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ وَإِذَا ذُكِرَ ٱلَّذِينَ مِن دُونِهِۦٓ إِذَا هُمْ يَسْتَبْشِرُونَ", tafsir: `` },
            { text: "قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ عَٰلِمَ ٱلْغَيْبِ وَٱلشَّهَٰدَةِ أَنتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِى مَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ", tafsir: `` },
            { text: "وَلَوْ أَنَّ لِلَّذِينَ ظَلَمُوا۟ مَا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لَٱفْتَدَوْا۟ بِهِۦ مِن سُوٓءِ ٱلْعَذَابِ يَوْمَ ٱلْقِيَٰمَةِ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمْ يَكُونُوا۟ يَحْتَسِبُونَ", tafsir: `` },
            { text: "وَبَدَا لَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `` },
            { text: "فَإِذَا مَسَّ ٱلْإِنسَٰنَ ضُرٌّ دَعَانَا ثُمَّ إِذَا خَوَّلْنَٰهُ نِعْمَةً مِّنَّا قَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلْمٍۭ بَلْ هِىَ فِتْنَةٌ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "قَدْ قَالَهَا ٱلَّذِينَ مِن قَبْلِهِمْ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ", tafsir: `` },
            { text: "فَأَصَابَهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَٱلَّذِينَ ظَلَمُوا۟ مِنْ هَٰٓؤُلَآءِ سَيُصِيبُهُمْ سَيِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعْجِزِينَ", tafsir: `` },
            { text: "أَوَلَمْ يَعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّقَوْمٍ يُؤْمِنُونَ", tafsir: `` },
            { text: "قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ", tafsir: `` },
            { text: "وَأَنِيبُوٓا۟ إِلَىٰ رَبِّكُمْ وَأَسْلِمُوا۟ لَهُۥ مِن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ ثُمَّ لَا تُنصَرُونَ", tafsir: `` },
            { text: "وَٱتَّبِعُوٓا۟ أَحْسَنَ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُم مِّن قَبْلِ أَن يَأْتِيَكُمُ ٱلْعَذَابُ بَغْتَةً وَأَنتُمْ لَا تَشْعُرُونَ", tafsir: `` },
            { text: "أَن تَقُولَ نَفْسٌ يَٰحَسْرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِى جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّٰخِرِينَ", tafsir: `` },
            { text: "أَوْ تَقُولَ لَوْ أَنَّ ٱللَّهَ هَدَىٰنِى لَكُنتُ مِنَ ٱلْمُتَّقِينَ", tafsir: `` },
            { text: "أَوْ تَقُولَ حِينَ تَرَى ٱلْعَذَابَ لَوْ أَنَّ لِى كَرَّةً فَأَكُونَ مِنَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "بَلَىٰ قَدْ جَآءَتْكَ ءَايَٰتِى فَكَذَّبْتَ بِهَا وَٱسْتَكْبَرْتَ وَكُنتَ مِنَ ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "وَيَوْمَ ٱلْقِيَٰمَةِ تَرَى ٱلَّذِينَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسْوَدَّةٌ أَلَيْسَ فِى جَهَنَّمَ مَثْوًى لِّلْمُتَكَبِّرِينَ", tafsir: `` },
            { text: "وَيُنَجِّى ٱللَّهُ ٱلَّذِينَ ٱتَّقَوْا۟ بِمَفَازَتِهِمْ لَا يَمَسُّهُمُ ٱلسُّوٓءُ وَلَا هُمْ يَحْزَنُونَ", tafsir: `` },
            { text: "ٱللَّهُ خَٰلِقُ كُلِّ شَىْءٍ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ وَكِيلٌ", tafsir: `` },
            { text: "لَّهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَٰتِ ٱللَّهِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `` },
            { text: "قُلْ أَفَغَيْرَ ٱللَّهِ تَأْمُرُوٓنِّىٓ أَعْبُدُ أَيُّهَا ٱلْجَٰهِلُونَ", tafsir: `` },
            { text: "وَلَقَدْ أُوحِىَ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ", tafsir: `` },
            { text: "بَلِ ٱللَّهَ فَٱعْبُدْ وَكُن مِّنَ ٱلشَّٰكِرِينَ", tafsir: `` },
            { text: "وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ", tafsir: `` },
            { text: "وَنُفِخَ فِى ٱلصُّورِ فَصَعِقَ مَن فِى ٱلسَّمَٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ثُمَّ نُفِخَ فِيهِ أُخْرَىٰ فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ", tafsir: `` },
            { text: "وَأَشْرَقَتِ ٱلْأَرْضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلْكِتَٰبُ وَجِا۟ىٓءَ بِٱلنَّبِيِّـۧنَ وَٱلشُّهَدَآءِ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَهُمْ لَا يُظْلَمُونَ", tafsir: `` },
            { text: "وَوُفِّيَتْ كُلُّ نَفْسٍ مَّا عَمِلَتْ وَهُوَ أَعْلَمُ بِمَا يَفْعَلُونَ", tafsir: `` },
            { text: "وَسِيقَ ٱلَّذِينَ كَفَرُوٓا۟ إِلَىٰ جَهَنَّمَ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا فُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَآ أَلَمْ يَأْتِكُمْ رُسُلٌ مِّنكُمْ يَتْلُونَ عَلَيْكُمْ ءَايَٰتِ رَبِّكُمْ وَيُنذِرُونَكُمْ لِقَآءَ يَوْمِكُمْ هَٰذَا قَالُوا۟ بَلَىٰ وَلَٰكِنْ حَقَّتْ كَلِمَةُ ٱلْعَذَابِ عَلَى ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "قِيلَ ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ", tafsir: `` },
            { text: "وَسِيقَ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ إِلَى ٱلْجَنَّةِ زُمَرًا حَتَّىٰٓ إِذَا جَآءُوهَا وَفُتِحَتْ أَبْوَٰبُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَٰمٌ عَلَيْكُمْ طِبْتُمْ فَٱدْخُلُوهَا خَٰلِدِينَ", tafsir: `` },
            { text: "وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى صَدَقَنَا وَعْدَهُۥ وَأَوْرَثَنَا ٱلْأَرْضَ نَتَبَوَّأُ مِنَ ٱلْجَنَّةِ حَيْثُ نَشَآءُ فَنِعْمَ أَجْرُ ٱلْعَٰمِلِينَ", tafsir: `` },
            { text: "وَتَرَى ٱلْمَلَٰٓئِكَةَ حَآفِّينَ مِنْ حَوْلِ ٱلْعَرْشِ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَقُضِىَ بَيْنَهُم بِٱلْحَقِّ وَقِيلَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `` }
        ]
    },
    40: { // سورة غافر
        name: "غافر",
        basmalaTafsir: ``,
        verses: [
            { text: "حمٓ", tafsir: `` },
            { text: "تَنزِيلُ ٱلْكِتَٰبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ", tafsir: `` },
            { text: "غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِ لَآ إِلَٰهَ إِلَّا هُوَ إِلَيْهِ ٱلْمَصِيرُ", tafsir: `` },
            { text: "مَا يُجَٰدِلُ فِىٓ ءَايَٰتِ ٱللَّهِ إِلَّا ٱلَّذِينَ كَفَرُوا۟ فَلَا يَغْرُرْكَ تَقَلُّبُهُمْ فِى ٱلْبِلَٰدِ", tafsir: `` },
            { text: "كَذَّبَتْ قَبْلَهُمْ قَوْمُ نُوحٍ وَٱلْأَحْزَابُ مِنۢ بَعْدِهِمْ وَهَمَّتْ كُلُّ أُمَّةٍۭ بِرَسُولِهِمْ لِيَأْخُذُوهُ وَجَٰدَلُوا۟ بِٱلْبَٰطِلِ لِيُدْحِضُوا۟ بِهِ ٱلْحَقَّ فَأَخَذْتُهُمْ فَكَيْفَ كَانَ عِقَابِ", tafsir: `` },
            { text: "وَكَذَٰلِكَ حَقَّتْ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِينَ كَفَرُوٓا۟ أَنَّهُمْ أَصْحَٰبُ ٱلنَّارِ", tafsir: `` },
            { text: "ٱلَّذِينَ يَحْمِلُونَ ٱلْعَرْشَ وَمَنْ حَوْلَهُۥ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِۦ وَيَسْتَغْفِرُونَ لِلَّذِينَ ءَامَنُوا۟ رَبَّنَا وَسِعْتَ كُلَّ شَىْءٍ رَّحْمَةً وَعِلْمًا فَٱغْفِرْ لِلَّذِينَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِيلَكَ وَقِهِمْ عَذَابَ ٱلْجَحِيمِ", tafsir: `` },
            { text: "رَبَّنَا وَأَدْخِلْهُمْ جَنَّٰتِ عَدْنٍ ٱلَّتِى وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ ءَابَآئِهِمْ وَأَزْوَٰجِهِمْ وَذُرِّيَّٰتِهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `` },
            { text: "وَقِهِمُ ٱلسَّيِّـَٔاتِ وَمَن تَقِ ٱلسَّيِّـَٔاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُۥ وَذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ كَفَرُوا۟ يُنَادَوْنَ لَمَقْتُ ٱللَّهِ أَكْبَرُ مِن مَّقْتِكُمْ أَنفُسَكُمْ إِذْ تُدْعَوْنَ إِلَى ٱلْإِيمَٰنِ فَتَكْفُرُونَ", tafsir: `` },
            { text: "قَالُوا۟ رَبَّنَآ أَمَتَّنَا ٱثْنَتَيْنِ وَأَحْيَيْتَنَا ٱثْنَتَيْنِ فَٱعْتَرَفْنَا بِذُنُوبِنَا فَهَلْ إِلَىٰ خُرُوجٍ مِّن سَبِيلٍ", tafsir: `` },
            { text: "ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِىَ ٱللَّهُ وَحْدَهُۥ كَفَرْتُمْ وَإِن يُشْرَكْ بِهِۦ تُؤْمِنُوا۟ فَٱلْحُكْمُ لِلَّهِ ٱلْعَلِىِّ ٱلْكَبِيرِ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى يُرِيكُمْ ءَايَٰتِهِۦ وَيُنَزِّلُ لَكُم مِّنَ ٱلسَّمَآءِ رِزْقًا وَمَا يَتَذَكَّرُ إِلَّا مَن يُنِيبُ", tafsir: `` },
            { text: "فَٱدْعُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ وَلَوْ كَرِهَ ٱلْكَٰفِرُونَ", tafsir: `` },
            { text: "رَفِيعُ ٱلدَّرَجَٰتِ ذُو ٱلْعَرْشِ يُلْقِى ٱلرُّوحَ مِنْ أَمْرِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ لِيُنذِرَ يَوْمَ ٱلتَّلَاقِ", tafsir: `` },
            { text: "يَوْمَ هُم بَٰرِزُونَ لَا يَخْفَىٰ عَلَى ٱللَّهِ مِنْهُمْ شَىْءٌ لِّمَنِ ٱلْمُلْكُ ٱلْيَوْمَ لِلَّهِ ٱلْوَٰحِدِ ٱلْقَهَّارِ", tafsir: `` },
            { text: "ٱلْيَوْمَ تُجْزَىٰ كُلُّ نَفْسٍۭ بِمَا كَسَبَتْ لَا ظُلْمَ ٱلْيَوْمَ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ", tafsir: `` },
            { text: "وَأَنذِرْهُمْ يَوْمَ ٱلْـَٔازِفَةِ إِذِ ٱلْقُلُوبُ لَدَى ٱلْحَنَاجِرِ كَٰظِمِينَ مَا لِلظَّٰلِمِينَ مِنْ حَمِيمٍ وَلَا شَفِيعٍ يُطَاعُ", tafsir: `` },
            { text: "يَعْلَمُ خَآئِنَةَ ٱلْأَعْيُنِ وَمَا تُخْفِى ٱلصُّدُورُ", tafsir: `` },
            { text: "وَٱللَّهُ يَقْضِى بِٱلْحَقِّ وَٱلَّذِينَ يَدْعُونَ مِن دُونِهِۦ لَا يَقْضُونَ بِشَىْءٍ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ", tafsir: `` },
            { text: "أَوَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ كَانُوا۟ مِن قَبْلِهِمْ كَانُوا۟ هُمْ أَشَدَّ مِنْهُمْ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقٍ", tafsir: `` },
            { text: "ذَٰلِكَ بِأَنَّهُمْ كَانَت تَّأْتِيهِمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُ إِنَّهُۥ قَوِىٌّ شَدِيدُ ٱلْعِقَابِ", tafsir: `` },
            { text: "وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَا وَسُلْطَٰنٍ مُّبِينٍ", tafsir: `` },
            { text: "إِلَىٰ فِرْعَوْنَ وَهَٰمَٰنَ وَقَٰرُونَ فَقَالُوا۟ سَٰحِرٌ كَذَّابٌ", tafsir: `` },
            { text: "فَلَمَّا جَآءَهُم بِٱلْحَقِّ مِنْ عِندِنَا قَالُوا۟ ٱقْتُلُوٓا۟ أَبْنَآءَ ٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ وَٱسْتَحْيُوا۟ نِسَآءَهُمْ وَمَا كَيْدُ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ", tafsir: `` },
            { text: "وَقَالَ فِرْعَوْنُ ذَرُونِىٓ أَقْتُلْ مُوسَىٰ وَلْيَدْعُ رَبَّهُۥٓ إِنِّىٓ أَخَافُ أَن يُبَدِّلَ دِينَكُمْ أَوْ أَن يُظْهِرَ فِى ٱلْأَرْضِ ٱلْفَسَادَ", tafsir: `` },
            { text: "وَقَالَ مُوسَىٰٓ إِنِّى عُذْتُ بِرَبِّى وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ ٱلْحِسَابِ", tafsir: `` },
            { text: "وَقَالَ رَجُلٌ مُّؤْمِنٌ مِّنْ ءَالِ فِرْعَوْنَ يَكْتُمُ إِيمَٰنَهُۥٓ أَتَقْتُلُونَ رَجُلًا أَن يَقُولَ رَبِّىَ ٱللَّهُ وَقَدْ جَآءَكُم بِٱلْبَيِّنَٰتِ مِن رَّبِّكُمْ وَإِن يَكُ كَٰذِبًا فَعَلَيْهِ كَذِبُهُۥ وَإِن يَكُ صَادِقًا يُصِبْكُم بَعْضُ ٱلَّذِى يَعِدُكُمْ إِنَّ ٱللَّهَ لَا يَهْدِى مَنْ هُوَ مُسْرِفٌ كَذَّابٌ", tafsir: `` },
            { text: "يَٰقَوْمِ لَكُمُ ٱلْمُلْكُ ٱلْيَوْمَ ظَٰهِرِينَ فِى ٱلْأَرْضِ فَمَن يَنصُرُنَا مِنۢ بَأْسِ ٱللَّهِ إِن جَآءَنَا قَالَ فِرْعَوْنُ مَآ أُرِيكُمْ إِلَّا مَآ أَرَىٰ وَمَآ أَهْدِيكُمْ إِلَّا سَبِيلَ ٱلرَّشَادِ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُم مِّثْلَ يَوْمِ ٱلْأَحْزَابِ", tafsir: `` },
            { text: "مِثْلَ دَأْبِ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَٱلَّذِينَ مِنۢ بَعْدِهِمْ وَمَا ٱللَّهُ يُرِيدُ ظُلْمًا لِّلْعِبَادِ", tafsir: `` },
            { text: "وَيَٰقَوْمِ إِنِّىٓ أَخَافُ عَلَيْكُمْ يَوْمَ ٱلتَّنَادِ", tafsir: `` },
            { text: "يَوْمَ تُوَلُّونَ مُدْبِرِينَ مَا لَكُم مِّنَ ٱللَّهِ مِنْ عَاصِمٍ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِنْ هَادٍ", tafsir: `` },
            { text: "وَلَقَدْ جَآءَكُمْ يُوسُفُ مِن قَبْلُ بِٱلْبَيِّنَٰتِ فَمَا زِلْتُمْ فِى شَكٍّ مِّمَّا جَآءَكُم بِهِۦ حَتَّىٰٓ إِذَا هَلَكَ قُلْتُمْ لَن يَبْعَثَ ٱللَّهُ مِنۢ بَعْدِهِۦ رَسُولًا كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنْ هُوَ مُسْرِفٌ مُّرْتَابٌ", tafsir: `` },
            { text: "ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ كَبُرَ مَقْتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِينَ ءَامَنُوا۟ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلْبِ مُتَكَبِّرٍ جَبَّارٍ", tafsir: `` },
            { text: "وَقَالَ فِرْعَوْنُ يَٰهَٰمَٰنُ ٱبْنِ لِى صَرْحًا لَّعَلِّىٓ أَبْلُغُ ٱلْأَسْبَٰبَ", tafsir: `` },
            { text: "أَسْبَٰبَ ٱلسَّمَٰوَٰتِ فَأَطَّلِعَ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّى لَأَظُنُّهُۥ كَٰذِبًا وَكَذَٰلِكَ زُيِّنَ لِفِرْعَوْنَ سُوٓءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِيلِ وَمَا كَيْدُ فِرْعَوْنَ إِلَّا فِى تَبَابٍ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِىٓ ءَامَنَ يَٰقَوْمِ ٱتَّبِعُونِ أَهْدِكُمْ سَبِيلَ ٱلرَّشَادِ", tafsir: `` },
            { text: "يَٰقَوْمِ إِنَّمَا هَٰذِهِ ٱلْحَيَوٰةُ ٱلدُّنْيَا مَتَٰعٌ وَإِنَّ ٱلْـَٔاخِرَةَ هِىَ دَارُ ٱلْقَرَارِ", tafsir: `` },
            { text: "مَنْ عَمِلَ سَيِّئَةً فَلَا يُجْزَىٰٓ إِلَّا مِثْلَهَا وَمَنْ عَمِلَ صَٰلِحًا مِّن ذَكَرٍ أَوْ أُنثَىٰ وَهُوَ مُؤْمِنٌ فَأُو۟لَٰٓئِكَ يَدْخُلُونَ ٱلْجَنَّةَ يُرْزَقُونَ فِيهَا بِغَيْرِ حِسَابٍ", tafsir: `` },
            { text: "وَيَٰقَوْمِ مَا لِىٓ أَدْعُوكُمْ إِلَى ٱلنَّجَوٰةِ وَتَدْعُونَنِىٓ إِلَى ٱلنَّارِ", tafsir: `` },
            { text: "تَدْعُونَنِى لِأَكْفُرَ بِٱللَّهِ وَأُشْرِكَ بِهِۦ مَا لَيْسَ لِى بِهِۦ عِلْمٌ وَأَنَا۠ أَدْعُوكُمْ إِلَى ٱلْعَزِيزِ ٱلْغَفَّٰرِ", tafsir: `` },
            { text: "لَا جَرَمَ أَنَّمَا تَدْعُونَنِىٓ إِلَيْهِ لَيْسَ لَهُۥ دَعْوَةٌ فِى ٱلدُّنْيَا وَلَا فِى ٱلْـَٔاخِرَةِ وَأَنَّ مَرَدَّنَآ إِلَى ٱللَّهِ وَأَنَّ ٱلْمُسْرِفِينَ هُمْ أَصْحَٰبُ ٱلنَّارِ", tafsir: `` },
            { text: "فَسَتَذْكُرُونَ مَآ أَقُولُ لَكُمْ وَأُفَوِّضُ أَمْرِىٓ إِلَى ٱللَّهِ إِنَّ ٱللَّهَ بَصِيرٌۢ بِٱلْعِبَادِ", tafsir: `` },
            { text: "فَوَقَىٰهُ ٱللَّهُ سَيِّـَٔاتِ مَا مَكَرُوا۟ وَحَاقَ بِـَٔالِ فِرْعَوْنَ سُوٓءُ ٱلْعَذَابِ", tafsir: `` },
            { text: "ٱلنَّارُ يُعْرَضُونَ عَلَيْهَا غُدُوًّا وَعَشِيًّا وَيَوْمَ تَقُومُ ٱلسَّاعَةُ أَدْخِلُوٓا۟ ءَالَ فِرْعَوْنَ أَشَدَّ ٱلْعَذَابِ", tafsir: `` },
            { text: "وَإِذْ يَتَحَآجُّونَ فِى ٱلنَّارِ فَيَقُولُ ٱلضُّعَفَٰٓؤُا۟ لِلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُنَّا لَكُمْ تَبَعًا فَهَلْ أَنتُم مُّغْنُونَ عَنَّا نَصِيبًا مِّنَ ٱلنَّارِ", tafsir: `` },
            { text: "قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا كُلٌّ فِيهَآ إِنَّ ٱللَّهَ قَدْ حَكَمَ بَيْنَ ٱلْعِبَادِ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ فِى ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدْعُوا۟ رَبَّكُمْ يُخَفِّفْ عَنَّا يَوْمًا مِّنَ ٱلْعَذَابِ", tafsir: `` },
            { text: "قَالُوٓا۟ أَوَلَمْ تَكُ تَأْتِيكُمْ رُسُلُكُم بِٱلْبَيِّنَٰتِ قَالُوا۟ بَلَىٰ قَالُوا۟ فَٱدْعُوا۟ وَمَا دُعَٰٓؤُا۟ ٱلْكَٰفِرِينَ إِلَّا فِى ضَلَٰلٍ", tafsir: `` },
            { text: "إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ يَقُومُ ٱلْأَشْهَٰدُ", tafsir: `` },
            { text: "يَوْمَ لَا يَنفَعُ ٱلظَّٰلِمِينَ مَعْذِرَتُهُمْ وَلَهُمُ ٱللَّعْنَةُ وَلَهُمْ سُوٓءُ ٱلدَّارِ", tafsir: `` },
            { text: "وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْهُدَىٰ وَأَوْرَثْنَا بَنِىٓ إِسْرَٰٓءِيلَ ٱلْكِتَٰبَ", tafsir: `` },
            { text: "هُدًى وَذِكْرَىٰ لِأُو۟لِى ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ وَٱسْتَغْفِرْ لِذَنۢبِكَ وَسَبِّحْ بِحَمْدِ رَبِّكَ بِٱلْعَشِىِّ وَٱلْإِبْكَٰرِ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ بِغَيْرِ سُلْطَٰنٍ أَتَىٰهُمْ إِن فِى صُدُورِهِمْ إِلَّا كِبْرٌ مَّا هُم بِبَٰلِغِيهِ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ", tafsir: `` },
            { text: "لَخَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ أَكْبَرُ مِنْ خَلْقِ ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "وَمَا يَسْتَوِى ٱلْأَعْمَىٰ وَٱلْبَصِيرُ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَلَا ٱلْمُسِىٓءُ قَلِيلًا مَّا تَتَذَكَّرُونَ", tafsir: `` },
            { text: "إِنَّ ٱلسَّاعَةَ لَـَٔاتِيَةٌ لَّا رَيْبَ فِيهَا وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يُؤْمِنُونَ", tafsir: `` },
            { text: "وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ إِنَّ ٱلَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِى سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ", tafsir: `` },
            { text: "ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلَّيْلَ لِتَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ", tafsir: `` },
            { text: "ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ خَٰلِقُ كُلِّ شَىْءٍ لَّآ إِلَٰهَ إِلَّا هُوَ فَأَنَّىٰ تُؤْفَكُونَ", tafsir: `` },
            { text: "كَذَٰلِكَ يُؤْفَكُ ٱلَّذِينَ كَانُوا۟ بِـَٔايَٰتِ ٱللَّهِ يَجْحَدُونَ", tafsir: `` },
            { text: "ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ قَرَارًا وَٱلسَّمَآءَ بِنَآءً وَصَوَّرَكُمْ فَأَحْسَنَ صُوَرَكُمْ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ ذَٰلِكُمُ ٱللَّهُ رَبُّكُمْ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "هُوَ ٱلْحَىُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "قُلْ إِنِّى نُهِيتُ أَنْ أَعْبُدَ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَآءَنِىَ ٱلْبَيِّنَٰتُ مِن رَّبِّى وَأُمِرْتُ أَنْ أُسْلِمَ لِرَبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى خَلَقَكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ يُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ثُمَّ لِتَكُونُوا۟ شُيُوخًا وَمِنكُم مَّن يُتَوَفَّىٰ مِن قَبْلُ وَلِتَبْلُغُوٓا۟ أَجَلًا مُّسَمًّى وَلَعَلَّكُمْ تَعْقِلُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ فَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ", tafsir: `` },
            { text: "أَلَمْ تَرَ إِلَى ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِ ٱللَّهِ أَنَّىٰ يُصْرَفُونَ", tafsir: `` },
            { text: "ٱلَّذِينَ كَذَّبُوا۟ بِٱلْكِتَٰبِ وَبِمَآ أَرْسَلْنَا بِهِۦ رُسُلَنَا فَسَوْفَ يَعْلَمُونَ", tafsir: `` },
            { text: "إِذِ ٱلْأَغْلَٰلُ فِىٓ أَعْنَٰقِهِمْ وَٱلسَّلَٰسِلُ يُسْحَبُونَ", tafsir: `` },
            { text: "فِى ٱلْحَمِيمِ ثُمَّ فِى ٱلنَّارِ يُسْجَرُونَ", tafsir: `` },
            { text: "ثُمَّ قِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تُشْرِكُونَ", tafsir: `` },
            { text: "مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمْ نَكُن نَّدْعُوا۟ مِن قَبْلُ شَيْـًٔا كَذَٰلِكَ يُضِلُّ ٱللَّهُ ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "ذَٰلِكُم بِمَا كُنتُمْ تَفْرَحُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَبِمَا كُنتُمْ تَمْرَحُونَ", tafsir: `` },
            { text: "ٱدْخُلُوٓا۟ أَبْوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَا فَبِئْسَ مَثْوَى ٱلْمُتَكَبِّرِينَ", tafsir: `` },
            { text: "فَٱصْبِرْ إِنَّ وَعْدَ ٱللَّهِ حَقٌّ فَإِمَّا نُرِيَنَّكَ بَعْضَ ٱلَّذِى نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا يُرْجَعُونَ", tafsir: `` },
            { text: "وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِىَ بِـَٔايَةٍ إِلَّا بِإِذْنِ ٱللَّهِ فَإِذَا جَآءَ أَمْرُ ٱللَّهِ قُضِىَ بِٱلْحَقِّ وَخَسِرَ هُنَالِكَ ٱلْمُبْطِلُونَ", tafsir: `` },
            { text: "ٱللَّهُ ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَنْعَٰمَ لِتَرْكَبُوا۟ مِنْهَا وَمِنْهَا تَأْكُلُونَ", tafsir: `` },
            { text: "وَلَكُمْ فِيهَا مَنَٰفِعُ وَلِتَبْلُغُوا۟ عَلَيْهَا حَاجَةً فِى صُدُورِكُمْ وَعَلَيْهَا وَعَلَى ٱلْفُلْكِ تُحْمَلُونَ", tafsir: `` },
            { text: "وَيُرِيكُمْ ءَايَٰتِهِۦ فَأَىَّ ءَايَٰتِ ٱللَّهِ تُنكِرُونَ", tafsir: `` },
            { text: "أَفَلَمْ يَسِيرُوا۟ فِى ٱلْأَرْضِ فَيَنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبْلِهِمْ كَانُوٓا۟ أَكْثَرَ مِنْهُمْ وَأَشَدَّ قُوَّةً وَءَاثَارًا فِى ٱلْأَرْضِ فَمَآ أَغْنَىٰ عَنْهُم مَّا كَانُوا۟ يَكْسِبُونَ", tafsir: `` },
            { text: "فَلَمَّا جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلْعِلْمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `` },
            { text: "فَلَمَّا رَأَوْا۟ بَأْسَنَا قَالُوٓا۟ ءَامَنَّا بِٱللَّهِ وَحْدَهُۥ وَكَفَرْنَا بِمَا كُنَّا بِهِۦ مُشْرِكِينَ", tafsir: `` },
            { text: "فَلَمْ يَكُ يَنفَعُهُمْ إِيمَٰنُهُمْ لَمَّا رَأَوْا۟ بَأْسَنَا سُنَّتَ ٱللَّهِ ٱلَّتِى قَدْ خَلَتْ فِى عِبَادِهِۦ وَخَسِرَ هُنَالِكَ ٱلْكَٰفِرُونَ", tafsir: `` }
        ]
    },
    41: { // سورة فصلت
        name: "فصلت",
        basmalaTafsir: ``,
        verses: [
            { text: "حمٓ", tafsir: `` },
            { text: "تَنزِيلٌ مِّنَ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ", tafsir: `` },
            { text: "كِتَٰبٌ فُصِّلَتْ ءَايَٰتُهُۥ قُرْءَانًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ", tafsir: `` },
            { text: "بَشِيرًا وَنَذِيرًا فَأَعْرَضَ أَكْثَرُهُمْ فَهُمْ لَا يَسْمَعُونَ", tafsir: `` },
            { text: "وَقَالُوا۟ قُلُوبُنَا فِىٓ أَكِنَّةٍ مِّمَّا تَدْعُونَآ إِلَيْهِ وَفِىٓ ءَاذَانِنَا وَقْرٌ وَمِنۢ بَيْنِنَا وَبَيْنِكَ حِجَابٌ فَٱعْمَلْ إِنَّنَا عَٰمِلُونَ", tafsir: `` },
            { text: "قُلْ إِنَّمَآ أَنَا۠ بَشَرٌ مِّثْلُكُمْ يُوحَىٰٓ إِلَىَّ أَنَّمَآ إِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ فَٱسْتَقِيمُوٓا۟ إِلَيْهِ وَٱسْتَغْفِرُوهُ وَوَيْلٌ لِّلْمُشْرِكِينَ", tafsir: `` },
            { text: "ٱلَّذِينَ لَا يُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ كَٰفِرُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ", tafsir: `` },
            { text: "قُلْ أَئِنَّكُمْ لَتَكْفُرُونَ بِٱلَّذِى خَلَقَ ٱلْأَرْضَ فِى يَوْمَيْنِ وَتَجْعَلُونَ لَهُۥٓ أَندَادًا ذَٰلِكَ رَبُّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "وَجَعَلَ فِيهَا رَوَٰسِىَ مِن فَوْقِهَا وَبَٰرَكَ فِيهَا وَقَدَّرَ فِيهَآ أَقْوَٰتَهَا فِىٓ أَرْبَعَةِ أَيَّامٍ سَوَآءً لِّلسَّآئِلِينَ", tafsir: `` },
            { text: "ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ وَهِىَ دُخَانٌ فَقَالَ لَهَا وَلِلْأَرْضِ ٱئْتِيَا طَوْعًا أَوْ كَرْهًا قَالَتَآ أَتَيْنَا طَآئِعِينَ", tafsir: `` },
            { text: "فَقَضَىٰهُنَّ سَبْعَ سَمَٰوَاتٍ فِى يَوْمَيْنِ وَأَوْحَىٰ فِى كُلِّ سَمَآءٍ أَمْرَهَا وَزَيَّنَّا ٱلسَّمَآءَ ٱلدُّنْيَا بِمَصَٰبِيحَ وَحِفْظًا ذَٰلِكَ تَقْدِيرُ ٱلْعَزِيزِ ٱلْعَلِيمِ", tafsir: `` },
            { text: "فَإِنْ أَعْرَضُوا۟ فَقُلْ أَنذَرْتُكُمْ صَٰعِقَةً مِّثْلَ صَٰعِقَةِ عَادٍ وَثَمُودَ", tafsir: `` },
            { text: "إِذْ جَآءَتْهُمُ ٱلرُّسُلُ مِنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوٓا۟ إِلَّا ٱللَّهَ قَالُوا۟ لَوْ شَآءَ رَبُّنَا لَأَنزَلَ مَلَٰٓئِكَةً فَإِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ", tafsir: `` },
            { text: "فَأَمَّا عَادٌ فَٱسْتَكْبَرُوا۟ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَقَالُوا۟ مَنْ أَشَدُّ مِنَّا قُوَّةً أَوَلَمْ يَرَوْا۟ أَنَّ ٱللَّهَ ٱلَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً وَكَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ", tafsir: `` },
            { text: "فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا صَرْصَرًا فِىٓ أَيَّامٍ نَّحِسَاتٍ لِّنُذِيقَهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَلَعَذَابُ ٱلْـَٔاخِرَةِ أَخْزَىٰ وَهُمْ لَا يُنصَرُونَ", tafsir: `` },
            { text: "وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَٱسْتَحَبُّوا۟ ٱلْعَمَىٰ عَلَى ٱلْهُدَىٰ فَأَخَذَتْهُمْ صَٰعِقَةُ ٱلْعَذَابِ ٱلْهُونِ بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `` },
            { text: "وَنَجَّيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ", tafsir: `` },
            { text: "وَيَوْمَ يُحْشَرُ أَعْدَآءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمْ يُوزَعُونَ", tafsir: `` },
            { text: "حَتَّىٰٓ إِذَا مَا جَآءُوهَا شَهِدَ عَلَيْهِمْ سَمْعُهُمْ وَأَبْصَٰرُهُمْ وَجُلُودُهُم بِمَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "وَقَالُوا۟ لِجُلُودِهِمْ لِمَ شَهِدتُّمْ عَلَيْنَا قَالُوٓا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِىٓ أَنطَقَ كُلَّ شَىْءٍ وَهُوَ خَلَقَكُمْ أَوَّلَ مَرَّةٍ وَإِلَيْهِ تُرْجَعُونَ", tafsir: `` },
            { text: "وَمَا كُنتُمْ تَسْتَتِرُونَ أَن يَشْهَدَ عَلَيْكُمْ سَمْعُكُمْ وَلَآ أَبْصَٰرُكُمْ وَلَا جُلُودُكُمْ وَلَٰكِن ظَنَنتُمْ أَنَّ ٱللَّهَ لَا يَعْلَمُ كَثِيرًا مِّمَّا تَعْمَلُونَ", tafsir: `` },
            { text: "وَذَٰلِكُمْ ظَنُّكُمُ ٱلَّذِى ظَنَنتُم بِرَبِّكُمْ أَرْدَىٰكُمْ فَأَصْبَحْتُم مِّنَ ٱلْخَٰسِرِينَ", tafsir: `` },
            { text: "فَإِن يَصْبِرُوا۟ فَٱلنَّارُ مَثْوًى لَّهُمْ وَإِن يَسْتَعْتِبُوا۟ فَمَا هُم مِّنَ ٱلْمُعْتَبِينَ", tafsir: `` },
            { text: "وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُوا۟ لَهُم مَّا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَحَقَّ عَلَيْهِمُ ٱلْقَوْلُ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِهِم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ إِنَّهُمْ كَانُوا۟ خَٰسِرِينَ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ كَفَرُوا۟ لَا تَسْمَعُوا۟ لِهَٰذَا ٱلْقُرْءَانِ وَٱلْغَوْا۟ فِيهِ لَعَلَّكُمْ تَغْلِبُونَ", tafsir: `` },
            { text: "فَلَنُذِيقَنَّ ٱلَّذِينَ كَفَرُوا۟ عَذَابًا شَدِيدًا وَلَنَجْزِيَنَّهُمْ أَسْوَأَ ٱلَّذِى كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "ذَٰلِكَ جَزَآءُ أَعْدَآءِ ٱللَّهِ ٱلنَّارُ لَهُمْ فِيهَا دَارُ ٱلْخُلْدِ جَزَآءًۢ بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ كَفَرُوا۟ رَبَّنَآ أَرِنَا ٱلَّذَيْنِ أَضَلَّانَا مِنَ ٱلْجِنِّ وَٱلْإِنسِ نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا لِيَكُونَا مِنَ ٱلْأَسْفَلِينَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟ وَأَبْشِرُوا۟ بِٱلْجَنَّةِ ٱلَّتِى كُنتُمْ تُوعَدُونَ", tafsir: `` },
            { text: "نَحْنُ أَوْلِيَآؤُكُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَفِى ٱلْـَٔاخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِىٓ أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ", tafsir: `` },
            { text: "نُزُلًا مِّنْ غَفُورٍ رَّحِيمٍ", tafsir: `` },
            { text: "وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ", tafsir: `` },
            { text: "وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَٰوَةٌ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌ", tafsir: `` },
            { text: "وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُوا۟ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٍ", tafsir: `` },
            { text: "وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `` },
            { text: "وَمِنْ ءَايَٰتِهِ ٱلَّيْلُ وَٱلنَّهَارُ وَٱلشَّمْسُ وَٱلْقَمَرُ لَا تَسْجُدُوا۟ لِلشَّمْسِ وَلَا لِلْقَمَرِ وَٱسْجُدُوا۟ لِلَّهِ ٱلَّذِى خَلَقَهُنَّ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ", tafsir: `` },
            { text: "فَإِنِ ٱسْتَكْبَرُوا۟ فَٱلَّذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ لَهُۥ بِٱلَّيْلِ وَٱلنَّهَارِ وَهُمْ لَا يَسْـَٔمُونَ", tafsir: `` },
            { text: "وَمِنْ ءَايَٰتِهِۦٓ أَنَّكَ تَرَى ٱلْأَرْضَ خَٰشِعَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ إِنَّ ٱلَّذِىٓ أَحْيَاهَا لَمُحْىِ ٱلْمَوْتَىٰٓ إِنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ يُلْحِدُونَ فِىٓ ءَايَٰتِنَا لَا يَخْفَوْنَ عَلَيْنَآ أَفَمَن يُلْقَىٰ فِى ٱلنَّارِ خَيْرٌ أَم مَّن يَأْتِىٓ ءَامِنًا يَوْمَ ٱلْقِيَٰمَةِ ٱعْمَلُوا۟ مَا شِئْتُمْ إِنَّهُۥ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ كَفَرُوا۟ بِٱلذِّكْرِ لَمَّا جَآءَهُمْ وَإِنَّهُۥ لَكِتَٰبٌ عَزِيزٌ", tafsir: `` },
            { text: "لَّا يَأْتِيهِ ٱلْبَٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ", tafsir: `` },
            { text: "مَّا يُقَالُ لَكَ إِلَّا مَا قَدْ قِيلَ لِلرُّسُلِ مِن قَبْلِكَ إِنَّ رَبَّكَ لَذُو مَغْفِرَةٍ وَذُو عِقَابٍ أَلِيمٍ", tafsir: `` },
            { text: "وَلَوْ جَعَلْنَٰهُ قُرْءَانًا أَعْجَمِيًّا لَّقَالُوا۟ لَوْلَا فُصِّلَتْ ءَايَٰتُهُۥٓ ءَا۬عْجَمِىٌّ وَعَرَبِىٌّ قُلْ هُوَ لِلَّذِينَ ءَامَنُوا۟ هُدًى وَشِفَآءٌ وَٱلَّذِينَ لَا يُؤْمِنُونَ فِىٓ ءَاذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى أُو۟لَٰٓئِكَ يُنَادَوْنَ مِن مَّكَانٍۭ بَعِيدٍ", tafsir: `` },
            { text: "وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ فَٱخْتُلِفَ فِيهِ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ لَقُضِىَ بَيْنَهُمْ وَإِنَّهُمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ", tafsir: `` },
            { text: "مَّنْ عَمِلَ صَٰلِحًا فَلِنَفْسِهِۦ وَمَنْ أَسَآءَ فَعَلَيْهَا وَمَا رَبُّكَ بِظَلَّٰمٍ لِّلْعَبِيدِ", tafsir: `` },
            { text: "إِلَيْهِ يُرَدُّ عِلْمُ ٱلسَّاعَةِ وَمَا تَخْرُجُ مِن ثَمَرَٰتٍ مِّنْ أَكْمَامِهَا وَمَا تَحْمِلُ مِنْ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلْمِهِۦ وَيَوْمَ يُنَادِيهِمْ أَيْنَ شُرَكَآءِى قَالُوٓا۟ ءَاذَنَّٰكَ مَا مِنَّا مِن شَهِيدٍ", tafsir: `` },
            { text: "وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَدْعُونَ مِن قَبْلُ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِيصٍ", tafsir: `` },
            { text: "لَّا يَسْـَٔمُ ٱلْإِنسَٰنُ مِن دُعَآءِ ٱلْخَيْرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَيَـُٔوسٌ قَنُوطٌ", tafsir: `` },
            { text: "وَلَئِنْ أَذَقْنَٰهُ رَحْمَةً مِّنَّا مِنۢ بَعْدِ ضَرَّآءَ مَسَّتْهُ لَيَقُولَنَّ هَٰذَا لِى وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةً وَلَئِن رُّجِعْتُ إِلَىٰ رَبِّىٓ إِنَّ لِى عِندَهُۥ لَلْحُسْنَىٰ فَلَنُنَبِّئَنَّ ٱلَّذِينَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِيقَنَّهُم مِّنْ عَذَابٍ غَلِيظٍ", tafsir: `` },
            { text: "وَإِذَآ أَنْعَمْنَا عَلَى ٱلْإِنسَٰنِ أَعْرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَآءٍ عَرِيضٍ", tafsir: `` },
            { text: "قُلْ أَرَءَيْتُمْ إِن كَانَ مِنْ عِندِ ٱللَّهِ ثُمَّ كَفَرْتُم بِهِۦ مَنْ أَضَلُّ مِمَّنْ هُوَ فِى شِقَاقٍۭ بَعِيدٍ", tafsir: `` },
            { text: "سَنُرِيهِمْ ءَايَٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ", tafsir: `` },
            { text: "أَلَآ إِنَّهُمْ فِى مِرْيَةٍ مِّن لِّقَآءِ رَبِّهِمْ أَلَآ إِنَّهُۥ بِكُلِّ شَىْءٍ مُّحِيطٌۢ", tafsir: `` }
        ]
    },
    42: { // سورة الشورى
        name: "الشورى",
        basmalaTafsir: ``,
        verses: [
            { text: "حمٓ", tafsir: `` },
            { text: "عٓسٓقٓ", tafsir: `` },
            { text: "كَذَٰلِكَ يُوحِىٓ إِلَيْكَ وَإِلَى ٱلَّذِينَ مِن قَبْلِكَ ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `أي كهذا الذي ذكرها من « حم عسق » أو كالوحي الذي تقدم من سائر سور القرآن ( يُوحِي إِلَيْكَ ) يا رسول الله ( وَإِلَى ) الأنبياء ( الَّذِينَ مِنْ قَبْلِكَ اللهُ ) فاعل يوحي ( الْعَزِيزُ ) في سلطانه ، فلا غالب عليه ( الْحَكِيمُ ) في تكوينه وتشريعه ، فإنه يخلق الأشياء حسب الحكمة والصلاح ، ويأمر ويشرع ، حسب الحكمة والصلاح ، فإنزال الوحي عليك ، وعلى الأنبياء السابقين ، تابع للحكمة ، لا عبث فيه ، ولا اعتباط ، ولا محاباة.` },
            { text: "لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ", tafsir: `تعالى بالخلق والملك والتدبير ( ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) المراد الظرف والمظروف ، فإن أحدهما يطلق ، ويراد به الآخر ـ في كثير من الأحيان ـ إيجاز في الكلام ( وَهُوَ الْعَلِيُ ) أي الرفيع الذي لا أرفع منه ، والمراد رفعة المنزلة لا رفعة المكان ، فإنه تعالى منزه عن المكان والمكانيات ( الْعَظِيمُ ) الذي هو أعظم من كل شيء ( 1) بحار الأنوار : ج 89 ص 373. تَكادُ السَّماواتُ يَتَفَطَّرْنَ مِنْ فَوْقِهِنَّ وَالْمَلائِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَنْ فِي الْأَرْضِ أَلا إِنَّ اللهَ هُوَ الْغَفُورُ علما وقدرة ، ومن حيث سائر الصفات. [6] ثم بين سبحانه بعض عظمته في الكون التي أوجبت أن تقترب السماوات إلى الإنفطار والانشقاق خوفا وروعة ، وأوجبت تنزيه الملائكة ، وطلب غفرانهم لأهل الأرض العصاة ، كما نرى من اعتذار الوزير من الملك ، عمّن عصاه ، لما يرى شدة بطشه ، ولما يخاف من أن تحل نقمته ـ ( تَكادُ السَّماواتُ يَتَفَطَّرْنَ ) أي يتشققن ( مِنْ فَوْقِهِنَ ) أي جهة أعلاهن ، لأن الأعلى ، أقرب إلى ما ارتكز في الذهن من علوه سبحانه ، وإن كان العلوان مختلفان ، فعلوه سبحانه معنوي وعلوها حسي ، والمعنى أن عظمته سبحانه ، بحيث تؤثر في السماوات ، حتى أنها تقترب من الانشقاق ، وهذا كقوله سبحانه ( وَلَوْ أَنَّ قُرْآناً سُيِّرَتْ بِهِ الْجِبالُ ) (1) وقوله ( ( إِنَّا عَرَضْنَا الْأَمانَةَ عَلَى السَّماواتِ ) (2) ( وَالْمَلائِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ ) أي ينزهونه بذكر محامده ، فإن من قال فلان شجاع ، كان حمدا وتنزيها عن الجبن ، بخلاف ما لو قال إنه ليس بجبان ، فإنه لا يلزم أن يكون شجاعا ( وَيَسْتَغْفِرُونَ لِمَنْ فِي الْأَرْضِ ) بأن يغفر الله لهم ، أما مؤمنهم ، فيغفر له عصيانه ، وأما كافرهم فبأن يهيئ سبحانه مغفرته بالإيمان ، حتى لا يحل بهم العذاب مما يرهب منه ، حتى الملائكة ، وإن كان تعذيبا لغيرهم ، فإن الشخص يرهب العذاب ، حتى إذا نزل بغيره ( أَلا ) فيتنبه البشر ( إِنَّ اللهَ هُوَ الْغَفُورُ ) ( 1) الرعد : 32. ( 2) الأحزاب : 73. الرَّحِيمُ (5) وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِياءَ اللهُ حَفِيظٌ عَلَيْهِمْ وَما أَنْتَ عَلَيْهِمْ بِوَكِيلٍ (6) وَكَذلِكَ أَوْحَيْنا إِلَيْكَ قُرْآناً عَرَبِيًّا لِتُنْذِرَ أُمَّ الْقُرى وَمَنْ حَوْلَها وَتُنْذِرَ يَوْمَ الْجَمْعِ لا رَيْبَ فِيهِ لذنوب عباده ( الرَّحِيمُ ) بهم يتفضل عليهم بالإحسان فوق الغفران.` },
            { text: "تَكَادُ ٱلسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ وَٱلْمَلَٰٓئِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَن فِى ٱلْأَرْضِ أَلَآ إِنَّ ٱللَّهَ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ", tafsir: `` },
            { text: "وَٱلَّذِينَ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ ٱللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَآ أَنتَ عَلَيْهِم بِوَكِيلٍ", tafsir: `أي من دون الله ( أَوْلِياءَ ) أي الأصنام بأن عبدوها ( اللهُ حَفِيظٌ عَلَيْهِمْ ) أي أنه يحفظهم ، فالأصنام موهومات ، لا حقيقة لألوهيتها ، وإنما الله هو الحافظ لهم ، وهكذا كما يقول الرئيس : إن فلانا الذي يحاربني ، يأكل رزقي وعطائي ، ( وَما أَنْتَ ) يا رسول الله ( عَلَيْهِمْ بِوَكِيلٍ ) فإنك غير مسئول عن كفرهم ، وإنما أنت مسئول عن تبليغهم ، وقد فعلت ذلك.` },
            { text: "وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ قُرْءَانًا عَرَبِيًّا لِّتُنذِرَ أُمَّ ٱلْقُرَىٰ وَمَنْ حَوْلَهَا وَتُنذِرَ يَوْمَ ٱلْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِى ٱلْجَنَّةِ وَفَرِيقٌ فِى ٱلسَّعِيرِ", tafsir: `أي كما أوحينا إلى الأنبياء من قبلك ( أَوْحَيْنا إِلَيْكَ ) أو المعنى ، « هكذا أوحينا إليك » وإنما جيء ب « ذلك » لتنزيل رفعة القرآن معنى ، منزلة بعده حسا ـ كما ذكروا في علم البلاغة ـ ( قُرْآناً عَرَبِيًّا ) فإنه بلغة العرب ليفقهوا ما فيه ( لِتُنْذِرَ ) يا رسول الله ( أُمَّ الْقُرى ) وهي مكة ، والمراد أهلها ( وَمَنْ حَوْلَها ) أي حول مكة من سائر القرى في العالم ، فإنها حيث صارت أمّا صارت كل قرية حولها ، فإن البنات حول الأم ، وإنما سميت أم القرى ، لأن الأرض دحيت من تحتها ، كالأولاد الذين يخرجون من الأم بالولادة ، وكأن هذا الإنذار ، بالنسبة إلى الأمور الدنيوية ، فإن من أعرض عن ذكره تكون معيشته ضنكا ( وَتُنْذِرَ يَوْمَ الْجَمْعِ ) هو يوم القيامة ، الذي يجمع فيه الخلائق ، بأن من كفر أو عصى ، عذب بالنار والنكال ( لا رَيْبَ فِيهِ ) وإن ارتاب فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ (7) وَلَوْ شاءَ اللهُ لَجَعَلَهُمْ أُمَّةً واحِدَةً وَلكِنْ يُدْخِلُ مَنْ يَشاءُ فِي رَحْمَتِهِ وَالظَّالِمُونَ ما لَهُمْ مِنْ وَلِيٍّ وَلا نَصِيرٍ (8) أَمِ اتَّخَذُوا مِنْ دُونِهِ أَوْلِياءَ فَاللهُ هُوَ الْوَلِيُّ فيه كثيرون ، إذ المعنى ، إنه ليس محلّا للريب ، كما قال سبحانه ، بالنسبة إلى القرآن ( لا رَيْبَ فِيهِ ) (1) وكما تقول « لا ريب في نور الشمس » وإن أنكره السوفسطائيون ( فَرِيقٌ فِي الْجَنَّةِ ) وهم المؤمنون المطيعون ( وَفَرِيقٌ فِي السَّعِيرِ ) أي النار المستعرة الملتهبة ، وهم الكفار والعصاة ، فتنذرهم ، بأن لا يتمادوا في الكفر والعصيان ، حتى يكونوا من أصحاب السعير.` },
            { text: "وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَهُمْ أُمَّةً وَٰحِدَةً وَلَٰكِن يُدْخِلُ مَن يَشَآءُ فِى رَحْمَتِهِۦ وَٱلظَّٰلِمُونَ مَا لَهُم مِّن وَلِىٍّ وَلَا نَصِيرٍ", tafsir: `أن يجبر الناس على دين واحد ( لَجَعَلَهُمْ أُمَّةً واحِدَةً ) ولكن هذا نقض للغرض ، فإن الغرض من الخلقة التكليف ، حتى يترتب عليه الثواب والعقاب ، ولو كان الناس مجبورين ، لكانوا كالأحجار والنبات في الفعل ( وَلكِنْ ) خيّرهم ، وأعطى الزمام بأيديهم ، ل ( يُدْخِلُ مَنْ يَشاءُ ) ممن آمن وعمل صالحا ( فِي رَحْمَتِهِ ) بالسعادة في الدنيا ، والجنة في الآخرة ( وَالظَّالِمُونَ ) الذين اختاروا الكفر والعصيان ( ما لَهُمْ مِنْ وَلِيٍ ) يواليهم ويلي أمورهم ( وَلا نَصِيرٍ ) ينصرهم.` },
            { text: "أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ فَٱللَّهُ هُوَ ٱلْوَلِىُّ وَهُوَ يُحْىِ ٱلْمَوْتَىٰ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `منقطعة ، بمعنى « بل » أي أن الكفار ضربوا عن عبادة الله وولايته ، و ( اتَّخَذُوا مِنْ دُونِهِ أَوْلِياءَ ) هي الأصنام التي والاها الكفار ( فَاللهُ هُوَ الْوَلِيُ ) وإنما الأصنام أحجار لا تضر ولا تنفع ، فهي ( 1) البقرة : 3. وَهُوَ يُحْيِ الْمَوْتى وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (9) وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللهِ ذلِكُمُ اللهُ رَبِّي عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ (10) فاطِرُ السَّماواتِ وَالْأَرْضِ جَعَلَ لَكُمْ لا توالي أحدا ولا تنفع ولاية الناس لها ( وَهُوَ يُحْيِ الْمَوْتى ) فمبعث الخلق بيده ، لا بيد غيره ، ويلزم من ذلك ، أن يخاف الناس عقابه ، حيث إن بيده الحكم ( وَهُوَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) من الإحياء والإماتة والرزق ، وغيرها ، بخلاف الأصنام ، التي لا تقدر على شيء ، واتخاذ القادر وليا أولى من اتخاذ العاجز. [11] أما هذه الاختلافات التي حدثت بين الناس ، فالحكم الوحيد فيها هو الله تعالى ، إذ هو المطلع على الصدق والكذب والحقيقة والزيف ( وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ ) الضمير عائد إلى « ما » أي كل شيء اختلفتم فيه ( فَحُكْمُهُ إِلَى اللهِ ) وهو الحكم العالم الذي يحق له الحكم ، أما من سواه ، فبين جاهل ، وبين ما لا يحق له الحكم ، وإن كان عالما ، إذ الفصل في القضايا ونفوذها أمر يحتاج إلى السلطة ، ولا سلطة إلى له سبحانه ( ذلِكُمُ ) « ذا » إشارها ، و « كم » خطاب ( اللهُ رَبِّي ) أي أن الذي يحكم بين المختلفين هو ربي ، لا الأصنام العابرة الجاهلة ( عَلَيْهِ تَوَكَّلْتُ ) في مهامي ( وَإِلَيْهِ أُنِيبُ ) أي أرجع في جميع أموري ، أو المعنى ، أتوب إليه. [12] ثم وصف سبحانه بأنه ( فاطِرُ السَّماواتِ وَالْأَرْضِ ) أي خالقهما ومبدعهما ، من فطر بمعنى خلق ، وهو الذي ( جَعَلَ لَكُمْ ) أيها البشر مِنْ أَنْفُسِكُمْ أَزْواجاً وَمِنَ الْأَنْعامِ أَزْواجاً يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ (11) لَهُ مَقالِيدُ السَّماواتِ وَالْأَرْضِ يَبْسُطُ الرِّزْقَ لِمَنْ يَشاءُ ( مِنْ أَنْفُسِكُمْ ) أي من جنس نفوسكم ( أَزْواجاً ) ليسكن الإنسان إليها ، فإن « كل جنس لجنسه يألف » ولا يقال فكيف تكون في الآخرة زوجة الإنسان حورية ؟ إذ هناك يلطف الإنسان ، حتى يكون كالملك فيتجانسان ( وَ ) جعل ( مِنَ الْأَنْعامِ ) الإبل والبقر والغنم ( أَزْواجاً ) ذكرا وأنثى ، لتكميل المنافع والنتاج ، لبقاء النسل ، فمن يا ترى جعل كل ذلك ؟ ( يَذْرَؤُكُمْ ) ذرأ ، بمعنى أوجد ، أي يخلقكم ـ أنتم والأنعام ـ ( فِيهِ ) أي في هذا الجعل ، فإن امتداد نسل الإنسان والحيوان ، إنما هو بجعل الأزواج ، ولذا ينقطع من لا زوج له ( لَيْسَ كَمِثْلِهِ شَيْءٌ ) من الأصنام وغيرها من سائر المعبودات ، والكاف إما زائدة لتأكيد النفي ـ كما هو شأن الزوائد غالبا ـ أي ليس مثله شيء ، قطعا ، أو هذا مبالغة ، فإن الشيء إذا لم يكن لما يشابهه مثل ، لم يكن له مثل بطريق أولى ، مع أنه سبحانه لا يشابه أحدا ، فهو غير منقطع عن خلقه ( وَهُوَ السَّمِيعُ ) للمسموعات ( الْبَصِيرُ ) للمبصرات ، فهو غير منقطع عن خلقه ، فقد أحاطهم علما وإدراكا.` },
            { text: "وَمَا ٱخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُۥٓ إِلَى ٱللَّهِ ذَٰلِكُمُ ٱللَّهُ رَبِّى عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ", tafsir: `` },
            { text: "فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ جَعَلَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًا وَمِنَ ٱلْأَنْعَٰمِ أَزْوَٰجًا يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِۦ شَىْءٌ وَهُوَ ٱلسَّمِيعُ ٱلْبَصِيرُ", tafsir: `` },
            { text: "لَهُۥ مَقَالِيدُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَبْسُطُ ٱلرِّزْقَ لِمَن يَشَآءُ وَيَقْدِرُ إِنَّهُۥ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `سبحانه ( مَقالِيدُ ) جمع مقلاد وهو المفتاح ( السَّماواتِ وَالْأَرْضِ ) فإن مفتاح الصحة والمرض ، والغنى والفقر ، والحياة والموت ، والإيجاد والإعدام ، وغيرها .. . ، بيده ، وهذا من باب التشبيه ، فإن من بيده المفتاح يكون مسيطرا على الخزينة التي منها العطاء والمنح ( يَبْسُطُ الرِّزْقَ ) أي يوسعه ( لِمَنْ يَشاءُ ) من عباده وَيَقْدِرُ إِنَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ (12) شَرَعَ لَكُمْ مِنَ الدِّينِ ما وَصَّى بِهِ نُوحاً وَالَّذِي أَوْحَيْنا إِلَيْكَ وَما وَصَّيْنا بِهِ إِبْراهِيمَ وَمُوسى وَعِيسى ( وَيَقْدِرُ ) أي يضيق الرزق لمن يشاء ، حسب حكمته في التوسعة والتضييق ، وليس معنى هذا ، أن لا مدخلية للطلب ، إذ الطلب من جملة الأشياء التي قررها سبحانه للرزق ، كما أن الزواج من جملة الأسباب التي قررها سبحانه للولد ، وإن كان الولد من خلقه تعالى ( إِنَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ ) ومن علمه جعل بعض الناس أغنياء ، بأن وسع عليهم ، وجعل بعضهم فقراء ، بأن ضيق عليهم. [14] ثم أن هذا الخالق العظيم ، الذي بيده كل شيء ، وهو سميع بصير بكل شيء ، هو الذي شرع الدين لرفاه البشر ، ونظامه أفضل الأديان والأنظمة ، إذ يعرف ما يلائم حياة الإنسان ، وما لا يلائم ، ثم إن نظامه خال من الأغراض ، والأهواء والميول ( شَرَعَ لَكُمْ ) أيها المسلمون ( مِنَ الدِّينِ ) أي الإسلام ، ومعنى الشرع ، جعل النهج والنظام وأصله من الظهور ، ومنه الشريعة لظهور محل أخذ الماء على الشاطئ ، أو من الشروع بمعنى الابتداء ( ما وَصَّى بِهِ نُوحاً ) فالإسلام دين الأنبياء ، من شيخ المرسلين نوح الذي كان بدء العالم الجديد ( وَ ) هو ( الَّذِي أَوْحَيْنا إِلَيْكَ ) يا رسول الله ( وَما وَصَّيْنا بِهِ إِبْراهِيمَ وَمُوسى وَعِيسى ) فهؤلاء الأنبياء ، وغيرهم من سائر الأنبياء ، إنما بشروا بدين واحد ، كما قال الله سبحانه ( إِنَّ الدِّينَ عِنْدَ اللهِ الْإِسْلامُ ) (1) وقد ذكرنا في بعض ( 1) آل عمران : 20. أَنْ أَقِيمُوا الدِّينَ وَلا تَتَفَرَّقُوا فِيهِ كَبُرَ عَلَى الْمُشْرِكِينَ ما تَدْعُوهُمْ إِلَيْهِ اللهُ يَجْتَبِي إِلَيْهِ مَنْ يَشاءُ المؤلفات ، إن الدين ينقسم إلى أصول وفروع وأخلاق ، والكل غير قادر للتبدل ، فالأصول : التوحيد ، والعدل ، والنبوة ، والوصاية ، والمعاد ، وهل هذا قابل للاختلاف ؟ والفروع : خضوع يسمى الصلاة ، وإنفاق يسمى الزكاة ، وإمساك يسمى الصيام ، وذهاب إلى محل يذكر الله يسمى الحج ، وأمر بالمعروف ، ونهي عن المنكر ، وهل هذا قابل للنسخ ؟ ثم بيع وشراء وإجارة وإرث ، وما أشبه ، ورذائل محرمة ، كالخمر والقمار ، وفضائل لازمة ، كالصلة وبر الوالدين ، وهل يمكن تحريف شيء منها ؟ والأخلاق شجاعة وغيرة وبذل ومعونة وعفة ، وما أشبه ، وهل يمكن أن تنقلب الشجاعة رذيلة ، والجبن فضيلة ، وهكذا ؟ نعم اختلاف في الحدود ، والقيود ، والآداب ، لا في الجوهر والأصل ( أَنْ أَقِيمُوا الدِّينَ ) متعلق ، ب « وصّى » أي أوصيناهم بإقامة الدين ، بأن يكون قائما غير دارس ( وَلا تَتَفَرَّقُوا ) أيها الأنبياء عليهم‌السلام أو أيها الناس ـ بأن يكون من باب الالتفات ـ ( فِيهِ ) أي في الدين ثم ذكر الله سبحانه ، إن الكفار يستعظمون دعوتك إلى التوحيد ، لأنهم عباد أصنام قد توارثوها عن الآباء ( كَبُرَ عَلَى الْمُشْرِكِينَ ) بالله ( ما تَدْعُوهُمْ ) من التوحيد والإخلاص ( إِلَيْهِ ) أو المراد كبر عليهم دعوتك إلى نفسك بالرسالة ، إذ قالوا ، كيف صار رسولا من بيننا ( لَوْ لا نُزِّلَ هذَا الْقُرْآنُ عَلى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ ) (1) ؟ وهذا المعنى أقرب إلى الجملة التالية ( اللهُ يَجْتَبِي إِلَيْهِ مَنْ يَشاءُ ) أي أن الله سبحانه يختار من يشاء للرسالة ، ( 1) الزخرف : 32. وَيَهْدِي إِلَيْهِ مَنْ يُنِيبُ (13) وَما تَفَرَّقُوا إِلاَّ مِنْ بَعْدِ ما جاءَهُمُ الْعِلْمُ بَغْياً بَيْنَهُمْ وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ إِلى أَجَلٍ مُسَمًّى لَقُضِيَ بَيْنَهُمْ وَإِنَّ الَّذِينَ أُورِثُوا الْكِتابَ مِنْ بَعْدِهِمْ ولفظ « إليه » إنما هو لأن المختار ينضم وينتهي إلى من اختاره واجتباه ، ولا يختار الله إلا من هو قابل للرسالة ، فليس اعتباطا وجزافا ، أو تابعا للمال والشرف الظاهري ( وَيَهْدِي إِلَيْهِ ) بالألطاف الخفية ( مَنْ يُنِيبُ ) أي من يتوب إليه ، ويرجع عن كفره وعصيانه ، فإنه إذا هدى شخصا وأرشده الطريق ، فأناب وتاب ، لطف به بألطافه الخفية.` },
            { text: "شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ", tafsir: `` },
            { text: "وَمَا تَفَرَّقُوٓا۟ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِن رَّبِّكَ إِلَىٰٓ أَجَلٍ مُّسَمًّى لَّقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلَّذِينَ أُورِثُوا۟ ٱلْكِتَٰبَ مِنۢ بَعْدِهِمْ لَفِى شَكٍّ مِّنْهُ مُرِيبٍ", tafsir: `أي لم يختلف أهل الكتاب فيما بينهم ( إِلَّا مِنْ بَعْدِ ما جاءَهُمُ الْعِلْمُ ) بوحدة الدين ، وحقيقة جميع الأنبياء ، فقد أرشدهم سبحانه ، فلم ينيبوا ولم يرجعوا ، ولذا تركهم سبحانه ولم يلطف بهم الألطاف الخفية ، ولم يزدهم هدى ، وإنما تفرقوا ( بَغْياً ) أي حسدا وظلما ( بَيْنَهُمْ ) بأن بغى بعضهم على بعض حسد بعضهم بعضا ، والمراد ظلم أهل الكتاب بعضهم بعضا ، وكان الإتيان بلفظ « بينهم » لإفادة أنهم لم يظلموا الأجانب عن الإيمان بل حسدوا وظلموا من هم على شاكلتهم في الدين والإذعان ( وَلَوْ لا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ ) بأن يمهلهم ( إِلى أَجَلٍ مُسَمًّى ) قد سمي ذلك الأجل والأمد في اللوح المحفوظ ( لَقُضِيَ بَيْنَهُمْ ) أي قضى الله سبحانه بينهم ، بتقوية الحق ، وإهلاك المبطل ، لكن الله سبحانه ، حيث حكم ببقائهم مدة معينة ـ لمصلحة رآها في ذلك ـ أخّر العذاب عنهم ( وَإِنَّ الَّذِينَ أُورِثُوا الْكِتابَ مِنْ بَعْدِهِمْ ) بأن صاروا من أهل لَفِي شَكٍّ مِنْهُ مُرِيبٍ (14) فَلِذلِكَ فَادْعُ وَاسْتَقِمْ كَما أُمِرْتَ وَلا تَتَّبِعْ أَهْواءَهُمْ وَقُلْ آمَنْتُ بِما أَنْزَلَ اللهُ مِنْ كِتابٍ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ اللهُ رَبُّنا وَرَبُّكُمْ لَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ لا حُجَّةَ بَيْنَنا وَبَيْنَكُمُ الكتاب ، بعد أولئك الأنبياء ، أو بعد آبائهم المختلفين ( لَفِي شَكٍّ مِنْهُ ) أي من هذا القرآن أو من الدين ( مُرِيبٍ ) موجب للتشكيك والريب ، فهؤلاء كآبائهم في الاختلاف والتفرق ، أو المعنى ، أن أخلاف أهل الكتاب ، لفي شك من كتابهم ، إذ التفرق والاختلاف ، يوجب الشك والريب في أن ما بيد الإنسان ، هل هو صحيح أم لا ؟` },
            { text: "فَلِذَٰلِكَ فَٱدْعُ وَٱسْتَقِمْ كَمَآ أُمِرْتَ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ وَقُلْ ءَامَنتُ بِمَآ أَنزَلَ ٱللَّهُ مِن كِتَٰبٍ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ٱللَّهُ رَبُّنَا وَرَبُّكُمْ لَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ ٱللَّهُ يَجْمَعُ بَيْنَنَا وَإِلَيْهِ ٱلْمَصِيرُ", tafsir: `أي لاختلاف هؤلاء في الدين بحيث لم يبق الدين واضحا قائما ( فَادْعُ ) يا رسول الله إلى الله سبحانه ( وَاسْتَقِمْ ) في الدعوة ، ولا تبالي بما تلاقي من أنواع الأذى وصنوف المكروه ( كَما أُمِرْتَ ) أي كما أمرك الله سبحانه بالدعوة والاستقامة ( وَلا تَتَّبِعْ ) يا رسول الله ( أَهْواءَهُمْ ) أي أهواء أهل الكتاب الذين حرفوا الدين ، وزادوا فيه ، وأنقصوا منه ( وَقُلْ ) يا رسول الله معلنا وحدة الأديان والكتب والرسالات ( آمَنْتُ بِما أَنْزَلَ اللهُ مِنْ كِتابٍ ) فكل الكتب للهداية ، والتبشير من جانب الله تعالى ( وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ ) فمن طبيعة دين الله العدل بين جميع الناس ، فلا يحابي أحدا ، ولا ينقص أحدا قدره ( اللهُ رَبُّنا وَرَبُّكُمْ ) أيها الناس ، فلا إله سواه ( لَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ ) فكل امرئ مجزي بأعماله ، إن كان خيرا فخير ، وإن كان شرا فشر ، فكفر الكافر لا يضر إلا نفسه ، كما أن إيمان المؤمن لا ينفع إلا نفسه ، وقد ظهر الحق ف ( لا حُجَّةَ بَيْنَنا وَبَيْنَكُمُ ) فقد تم اللهُ يَجْمَعُ بَيْنَنا وَإِلَيْهِ الْمَصِيرُ (15) وَالَّذِينَ يُحَاجُّونَ فِي اللهِ مِنْ بَعْدِ ما اسْتُجِيبَ لَهُ حُجَّتُهُمْ داحِضَةٌ عِنْدَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذابٌ شَدِيدٌ (16) الاحتجاج ، وظهر الحق ، واضحا جليا ، إذ الاحتجاج إنما يكون قبل ظهور الحق ، أما بعده ، فلا فائدة فيه ( اللهُ يَجْمَعُ بَيْنَنا ) للحساب يوم القيامة ، حتى يظهر هناك ، من المحق ، ومن المبطل ( وَإِلَيْهِ الْمَصِيرُ ) أي إلى ثوابه وعقابه ، فالمؤمنون مصيرهم نعيم الله سبحانه وجنانه والكافرون مصيرهم سخط الله ونيرانه.` },
            { text: "وَٱلَّذِينَ يُحَآجُّونَ فِى ٱللَّهِ مِنۢ بَعْدِ مَا ٱسْتُجِيبَ لَهُۥ حُجَّتُهُمْ دَاحِضَةٌ عِندَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ", tafsir: `في ذاته ، أو صفاته ( مِنْ بَعْدِ ) تلك الحجج الواضحة ، وقد ( ما اسْتُجِيبَ لَهُ ) استجاب للدعوة الزمرة المؤمنة ( حُجَّتُهُمْ داحِضَةٌ ) أي باطلة زائفة ، إذ الاحتجاج بعد تمام الدليل ، والتفات المؤمنين حول الدعوة لا قيمة له ، نعم لو لم تثبت الحجة ، أو لم يكن هناك جماعة مستجيبة ، يأوي إليها الإنسان من شر الخصوم والعداء ، لكان لهم بعض الحق ، في الجدل والخصومة ، أما وقد بان الطريق ، وسلكه الناس ، فلا حجة ، لمن لا يسلك ( عِنْدَ رَبِّهِمْ ) وإن كان بعض الناس يعطيهم الحق في بقائهم على الكفر ، ولكن عند الله سبحانه ، وفي حسابه لا حق لهم ، ولا مفهوم لقوله « من بعد ما استجيب له » بل ذلك بيان لشدة ضلال هؤلاء ، حتى أنه بعد الاستجابة ، يبقون على كفرهم وضلالهم ( وَعَلَيْهِمْ غَضَبٌ ) من الله سبحانه ( وَلَهُمْ عَذابٌ شَدِيدٌ ) يوم القيامة ، أو أعم منه ، ومن الدنيا ، وحيث إن الله سبحانه ، ليس غضبه ، بمعنى ما فينا ـ مما هو ملازم للنفس ـ كان معناه نتيجة الغضب ، وهو الانتقام ، وذلك أعم من اللهُ الَّذِي أَنْزَلَ الْكِتابَ بِالْحَقِّ وَالْمِيزانَ وَما يُدْرِيكَ لَعَلَّ السَّاعَةَ قَرِيبٌ (17) يَسْتَعْجِلُ بِهَا الَّذِينَ لا يُؤْمِنُونَ بِها وَالَّذِينَ آمَنُوا مُشْفِقُونَ مِنْها وَيَعْلَمُونَ أَنَّهَا الْحَقُّ العذاب الشديد ، فلا يقال بأنه موجب للتكرار.` },
            { text: "ٱللَّهُ ٱلَّذِىٓ أَنزَلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَٱلْمِيزَانَ وَمَا يُدْرِيكَ لَعَلَّ ٱلسَّاعَةَ قَرِيبٌ", tafsir: `الذي يحاجون فيه ، هو من أنزل الشريعة وبيده المعاد ، وهل يحاج الإنسان في جاعل النظام ، وإليه مصير الأنام ؟ فإن الله هو ( الَّذِي أَنْزَلَ الْكِتابَ ) أي القرآن ( بِالْحَقِ ) أي إنزالا بالحق ، ولأجل إقامة الحق ، فلا الإنزال بالباطل ، كإنزال الشياطين على الكهنة ، ولا المنزل باطل ، كما لو أمر صاحب الدار بخراب داره ، فإن له الحق في الإنزال ، لأنه صاحب السلطة ، لكن ليس له حق في الأمر المنزّل ، وهو خراب الدار ( وَ ) أنزل ( الْمِيزانَ ) الذي يوزن به بين الحق والباطل في العقائد ، والأعمال والأقوال ( وَما يُدْرِيكَ ) يا رسول الله ، أي من أين تدري ـ وهذا للتهويل ـ أو المراد ، ما يدريك أيها المخاطب ( لَعَلَّ السَّاعَةَ قَرِيبٌ ) أي القيامة ، فلا يغر الإنسان ، ما يراه من الأمن والسلامة ، فلعل محكمته قربت ، فاللازم أن يكون الإنسان على خوف ووجل منها.` },
            { text: "يَسْتَعْجِلُ بِهَا ٱلَّذِينَ لَا يُؤْمِنُونَ بِهَا وَٱلَّذِينَ ءَامَنُوا۟ مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا ٱلْحَقُّ أَلَآ إِنَّ ٱلَّذِينَ يُمَارُونَ فِى ٱلسَّاعَةِ لَفِى ضَلَٰلٍۭ بَعِيدٍ", tafsir: `أي يطلبون عجلة الساعة ، بأن تأتيهم عاجلا ( الَّذِينَ لا يُؤْمِنُونَ بِها ) وإنما استعجالهم على وجه الاستهزاء والسخرية ، كما يسخر غير المؤمن بالساعة إذا ذكّر بها ( وَالَّذِينَ آمَنُوا ) بالله ورسوله والمعاد ( مُشْفِقُونَ ) أي خائفون ( مِنْها ) أي من الساعة ، لما يعلمون من أهوالها ، ولخوفهم ، بأن يكونوا قد قصروا ، فيسألهم عقابها ونكالها ( وَيَعْلَمُونَ أَنَّهَا ) أي الساعة ( الْحَقُ ) الذي لا كذب فيه مقابل أَلا إِنَّ الَّذِينَ يُمارُونَ فِي السَّاعَةِ لَفِي ضَلالٍ بَعِيدٍ (18) اللهُ لَطِيفٌ بِعِبادِهِ يَرْزُقُ مَنْ يَشاءُ وَهُوَ الْقَوِيُّ الْعَزِيزُ (19) مَنْ كانَ يُرِيدُ حَرْثَ الْآخِرَةِ نَزِدْ لَهُ فِي حَرْثِهِ الكفار ، الذين يظنون أنها باطلة ، لا حقيقة لها ( أَلا ) فليتنبه السامع ( إِنَّ الَّذِينَ يُمارُونَ ) أي يجادلون من المراء ، وهو الجدال ( فِي السَّاعَةِ ) ليثبتوا بطلانها ، منكرين لوجودها ( لَفِي ضَلالٍ ) وابتعاد عن الصواب ( بَعِيدٍ ) كالإنسان الذي يضل عن الجادة كثيرا ، ومقابل العصاة ، الذين هم في ضلال ، ولكن ليس بذلك البعد ، فإنهم أقرب إلى الجادة ، من منكر المعاد. [20] إن الله سبحانه خلق الدنيا للامتحان ، ولذا يرزق المؤمن والكافر فيها ، لتهيئة وسيلة السعادة ، أما الآخرة ، فليس رزقها ، إلا لمن آمن وعمل صالحا ، وهذا لتنبيه الكفار ، بأن الآخرة ، التي يوعدونها ليست بمثابة الدنيا يرزق فيها كل صالح وطالح ، وإنما مقياس تلك غير مقياس هذه الدار ( اللهُ لَطِيفٌ بِعِبادِهِ ) يلطف بهم ليسعدهم ، فيهيّئ لهم وسائل السعادة ، سواء كانوا صالحين أم طالحين ( يَرْزُقُ مَنْ يَشاءُ ) كيف يشاء في سعة أو ضيق ( وَهُوَ الْقَوِيُ ) القادر على الإعطاء والمنع والتوسعة والتضييق ( الْعَزِيزُ ) الغالب في سلطانه ، فلا يتمكن أحد من معارضته ، [21] وإذا كان الله رازقا هنا ، فليعلم العباد أن من طلب رزق الدنيا يؤتيه بقدر ، ولا نصيب له في الآخرة ، ومن طلب رزق الآخرة ـ بالإيمان والعمل الصالح ـ يعطى أكثر من كسبه ( مَنْ كانَ يُرِيدُ ) بعمله ( حَرْثَ الْآخِرَةِ ) أي زرعه ، فكأن العمل هنا بذر يعطي هناك ثماره ( نَزِدْ لَهُ فِي حَرْثِهِ ) إذ يعطيه الله سبحانه من عشرة أضعاف إلى ما فوق سبعمائة وَمَنْ كانَ يُرِيدُ حَرْثَ الدُّنْيا نُؤْتِهِ مِنْها وَما لَهُ فِي الْآخِرَةِ مِنْ نَصِيبٍ (20) أَمْ لَهُمْ شُرَكاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ ما لَمْ يَأْذَنْ بِهِ اللهُ وَلَوْ لا كَلِمَةُ الْفَصْلِ لَقُضِيَ بَيْنَهُمْ وَإِنَّ الظَّالِمِينَ لَهُمْ عَذابٌ أَلِيمٌ (21) تَرَى الظَّالِمِينَ ضعف ( وَمَنْ كانَ يُرِيدُ حَرْثَ الدُّنْيا ) بأن عمل وكد واجتهد للدنيا فقط ، بدون لحاظ للآخرة في عمله ( نُؤْتِهِ ) أي ذلك المريد ( مِنْها ) أي من الدنيا ( وَما لَهُ فِي الْآخِرَةِ مِنْ نَصِيبٍ ) لأنه لم يزرع حتى يحصد. [22] لقد تقدم ، أن الدين شرع الله سبحانه الذي بشر به الأنبياء جميعا ، أما طريقة هؤلاء الكفار ، فمن ذا الذي شرعها لهم ، بعد أن لم يأذن بها الله سبحانه ؟ ( أَمْ لَهُمْ شُرَكاءُ شَرَعُوا ) أي هل لهؤلاء الكفار أصنام شرعوا ونهجوا تلك المنهاج ( لَهُمْ مِنَ الدِّينِ ) والطريقة في العقيدة ، والعمل ( ما لَمْ يَأْذَنْ بِهِ اللهُ ) ؟ وهذا سؤال استنكاري ، أي كيف يحق لهم أن ينهجوا نهجا لم يأذن الله سبحانه به ؟ ( وَلَوْ لا كَلِمَةُ الْفَصْلِ ) أي الكلمة التي قالها الله سبحانه ، في شأن تأخير العذاب عن هؤلاء والتي هي فاصلة بين حياتهم ، وبين عذابهم ( لَقُضِيَ بَيْنَهُمْ ) أي حكم عاجلا ، فيما بين هؤلاء الكفار ، وبين المؤمنين ، بإنزال العقوبة على هؤلاء ، لانحرافهم عن الطريق ( وَإِنَّ الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر والعصيان ( لَهُمْ عَذابٌ أَلِيمٌ ) يؤلمهم جزاء على كفرهم وعصيانهم.` },
            { text: "ٱللَّهُ لَطِيفٌۢ بِعِبَادِهِۦ يَرْزُقُ مَن يَشَآءُ وَهُوَ ٱلْقَوِىُّ ٱلْعَزِيزُ", tafsir: `` },
            { text: "مَن كَانَ يُرِيدُ حَرْثَ ٱلْـَٔاخِرَةِ نَزِدْ لَهُۥ فِى حَرْثِهِۦ وَمَن كَانَ يُرِيدُ حَرْثَ ٱلدُّنْيَا نُؤْتِهِۦ مِنْهَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِن نَّصِيبٍ", tafsir: `` },
            { text: "أَمْ لَهُمْ شُرَكَٰٓؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّينِ مَا لَمْ يَأْذَنۢ بِهِ ٱللَّهُ وَلَوْلَا كَلِمَةُ ٱلْفَصْلِ لَقُضِىَ بَيْنَهُمْ وَإِنَّ ٱلظَّٰلِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "تَرَى ٱلظَّٰلِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعٌۢ بِهِمْ وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ فِى رَوْضَاتِ ٱلْجَنَّاتِ لَهُم مَّا يَشَآءُونَ عِندَ رَبِّهِمْ ذَٰلِكَ هُوَ ٱلْفَضْلُ ٱلْكَبِيرُ", tafsir: `يا رسول الله ، وأيها الرائي ( الظَّالِمِينَ ) في يوم القيامة مُشْفِقِينَ مِمَّا كَسَبُوا وَهُوَ واقِعٌ بِهِمْ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ فِي رَوْضاتِ الْجَنَّاتِ لَهُمْ ما يَشاؤُنَ عِنْدَ رَبِّهِمْ ذلِكَ هُوَ الْفَضْلُ الْكَبِيرُ (22) ذلِكَ الَّذِي يُبَشِّرُ اللهُ عِبادَهُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ مُشْفِقِينَ ) أي خائفين ( مِمَّا كَسَبُوا ) إذ يتجلى هناك لهم ، أن أعمالهم أثمرت النيران والنكال ( وَهُوَ ) أي ما كسبوا ـ والمراد جزائه ، إلا أن يقال بتجسيم الأعمال ـ ( واقِعٌ بِهِمْ ) قطعا فلا مفر لهم منه ( وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ ) أي الأعمال الصالحة فصحت عقيدتهم وعملهم ( فِي رَوْضاتِ الْجَنَّاتِ ) الروضة هي الأرض الخضرة ، بحسن النبات ، والجنة الأرض التي يحفها الشجر ، ويجنها عن الشمس والأبصار ( لَهُمْ ما يَشاؤُنَ ) من أنواع الملاذ ( عِنْدَ رَبِّهِمْ ) فلهم شرف القرب المعنوي من الله سبحانه ، كما أن لهم ما يشتهون من الملذات الجسمية ( ذلِكَ ) الثواب الذي ينعم الله سبحانه عليهم به ( هُوَ الْفَضْلُ الْكَبِيرُ ) الذي تفضل الله سبحانه عليهم ، وإلا فالإنسان مهما كان عمله ، لا يستحق على الله سبحانه شيئا.` },
            { text: "ذَٰلِكَ ٱلَّذِى يُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ قُل لَّآ أَسْـَٔلُكُمْ عَلَيْهِ أَجْرًا إِلَّا ٱلْمَوَدَّةَ فِى ٱلْقُرْبَىٰ وَمَن يَقْتَرِفْ حَسَنَةً نَّزِدْ لَهُۥ فِيهَا حُسْنًا إِنَّ ٱللَّهَ غَفُورٌ شَكُورٌ", tafsir: `الثواب والفضل الكبير ، هو ( الَّذِي يُبَشِّرُ اللهُ ) به ( عِبادَهُ ) الصالحين ( الَّذِينَ آمَنُوا ) بالله ورسوله ( وَعَمِلُوا ) الأعمال ( الصَّالِحاتِ ) فليرغب فيه الناس ، والرسول صلى‌الله‌عليه‌وآله‌وسلم ، لا يطلب عوض هذه البشرى ، وهذه الهداية المنتهية إلى تلك النعم ، وذلك الفضل الكبير مالا وأجرا ، وإنما يريد من الناس أن يوالوا أقربائه ، فاطمة والأئمة الأطهار ، وذلك ليس له أيضا ، وإنما لهم ، إذ إن الأئمة عليهم‌السلام قُلْ لا أَسْئَلُكُمْ عَلَيْهِ أَجْراً إِلاَّ الْمَوَدَّةَ فِي الْقُرْبى وَمَنْ يَقْتَرِفْ حَسَنَةً نَزِدْ لَهُ فِ يها حُسْناً إِنَّ اللهَ غَفُورٌ يرشدون الناس إلى الخير والصلاح ، ويهدونهم إلى الحق والصواب والصدق ( قُلْ ) يا رسول الله لهؤلاء الذين بشرتهم ( لا أَسْئَلُكُمْ عَلَيْهِ ) أي على ما جئتكم به من الهداية والبشرى ( أَجْراً ) وثمنا ( إِلَّا الْمَوَدَّةَ ) أي الود والحب ( فِي الْقُرْبى ) أي في أقربائي ، ومن الواضح ، أن المودة الواجبة هي بالنسبة إلى فاطمة والأئمة ، صلوات الله عليهم أجمعين ، أما بالنسبة إلى سائر ذرية الرسول ـ غير من كفر منهم ـ فالمودة مستحبة ، و قد قال الرسول صلى‌الله‌عليه‌وآله‌وسلم « أكرموا ذريتي الصالحين لله والطالحين لي » ، و قال « المرء يحفظ في ولده » (1) وينسب إلى الشافعي ، أنه قال : يا آل بيت رسول الله حبكم فرض من الله في القرآن أنزله كفاكم من عظيم الفخر أنكم من لم يصل عليكم لا صلاة له وقد ورد إن المشركين تسألوا ، هل يريد محمد من رسالته أجرا ، فنزلت هذه الآية ( وَمَنْ يَقْتَرِفْ ) أي يعمل ( حَسَنَةً ) من عقيدة أو عمل أو مودة لآل البيت ( نَزِدْ لَهُ فِيها ) أي في تلك الحسنة ( حُسْناً ) بأن نجعل له ثوابا في الآخرة فالتصدّق ـ مثلا ـ حسن في الدنيا ، فمن تصدق نزيد صدقته حسنة ، بجعل ثواب لها في الآخرة ( إِنَّ اللهَ غَفُورٌ ) ( 1) الاحتجاج : ج 1 ص 102. شَكُورٌ (23) أَمْ يَقُولُونَ افْتَرى عَلَى اللهِ كَذِباً فَإِنْ يَشَإِ اللهُ يَخْتِمْ عَلى قَلْبِكَ وَيَمْحُ اللهُ الْباطِلَ وَيُحِقُّ الْحَقَّ بِكَلِماتِهِ إِنَّهُ عَلِيمٌ بِذاتِ الصُّدُورِ (24) للسيئات ، فلا ييأس المذنب من عفوه وغفرانه ـ وهذا بمناسبة ذكر الكفار والظالمين ـ . ( شَكُورٌ ) يشكر حسنات العباد ، وشكره سبحانه ، بإعطائه الزيادة هنا ، والأجر هناك ـ وهذا بمناسبة ذكر المؤمنين العاملين للصالحات ـ . [25] إن هؤلاء الكفار يصمون عن الحق ، ولا ينظرون في الأدلة ( أَمْ ) أي بل ( يَقُولُونَ افْتَرى ) محمد ( عَلَى اللهِ كَذِباً ) حيث نسب القرآن إليه كذبا ، وهو من كلامه ، ولكن هذا الكلام منهم كذب ، إذ ليس الله سبحانه يدع أحدا يدعي النبوة ، ويأتي بالخارقة ، ثم يذره ( فَإِنْ يَشَإِ اللهُ ) حين يراك كاذبا ـ كما زعموا ـ ( يَخْتِمْ عَلى قَلْبِكَ ) فلا تتمكن من تلاوة القرآن ، كالظرف المختوم الذي لا يخرج منه شيء مما فيه ( وَ ) لا يهمك يا رسول الله هذا الافتراء منهم ، فإنه ( يَمْحُ اللهُ الْباطِلَ ) من أقوالهم ويزيله ، فلا يتعلق به أحد ، ولا يرى كلامهم صوابا ( وَيُحِقُّ الْحَقَ ) أي يظهر كونه حقا ، إذ معنى « أحق » أثبت ( بِكَلِماتِهِ ) أي يظهر حقية الرسول ، بما ينزله من القرآن الذي لا يتمكن أحد من الإتيان بمثله ، فيبطل دعواهم ، إذ لو كان الأمر ، كما قالوا لتمكن فصحاؤهم من الإتيان بمثله ( إِنَّهُ ) تعالى ( عَلِيمٌ ) أي عالم ( بِذاتِ الصُّدُورِ ) أي بالأمور التي تدور في صدورهم حولك لإبطال أمرك ، فلا يترك مؤامراتهم وأفكارهم تنفذ فيك ، وتطبق عليك ، بل يحبطها ويبطلها. وَهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبادِهِ وَيَعْفُوا عَنِ السَّيِّئاتِ وَيَعْلَمُ ما تَفْعَلُونَ (25) وَيَسْتَجِيبُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ وَيَزِيدُهُمْ مِنْ فَضْلِهِ وَالْكافِرُونَ لَهُمْ عَذابٌ شَدِيدٌ (26) وَلَوْ بَسَطَ اللهُ الرِّزْقَ لِعِبادِهِ [26] ولا ييأس هؤلاء الكفار عن رحمة الله وفضله وعفوه ، فإن تابوا مما هم فيه ، تاب عليهم ( وَهُوَ ) الله ( الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبادِهِ ) فمن تاب ورجع إليه قبل توبته ( وَيَعْفُوا عَنِ السَّيِّئاتِ ) أي المعاصي ، وهذا في مقابل أن يقبل التوبة ، ويضم التائب إلى جماعته ، لكنه ينتقم منه لما فعل سابقا ( وَيَعْلَمُ ما تَفْعَلُونَ ) أيها البشر من عصيان وطاعة وإدبار وتوبة فلا يظن أحد أنه مختف عليه سبحانه ، لا يرى سيئته ، فيعاقبه ، أو حسنته فيجازيه بالثواب.` },
            { text: "أَمْ يَقُولُونَ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا فَإِن يَشَإِ ٱللَّهُ يَخْتِمْ عَلَىٰ قَلْبِكَ وَيَمْحُ ٱللَّهُ ٱلْبَٰطِلَ وَيُحِقُّ ٱلْحَقَّ بِكَلِمَٰتِهِۦٓ إِنَّهُۥ عَلِيمٌۢ بِذَاتِ ٱلصُّدُورِ", tafsir: `` },
            { text: "وَهُوَ ٱلَّذِى يَقْبَلُ ٱلتَّوْبَةَ عَنْ عِبَادِهِۦ وَيَعْفُوا۟ عَنِ ٱلسَّيِّـَٔاتِ وَيَعْلَمُ مَا تَفْعَلُونَ", tafsir: `` },
            { text: "وَيَسْتَجِيبُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَيَزِيدُهُم مِّن فَضْلِهِۦ وَٱلْكَٰفِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ", tafsir: `هو الذي ( يَسْتَجِيبُ ) أي يجيب ( الَّذِينَ آمَنُوا ) بالله ورسوله ( وَعَمِلُوا ) الأعمال ( الصَّالِحاتِ ) فهو يعطي طلباتهم إن رأى ذلك صلاحا ، وإلا أخّرها إلى القيامة ، كما ورد بذلك الأحاديث ( وَيَزِيدُهُمْ مِنْ فَضْلِهِ ) فليس إجابة الدعاء فحسب ، بل إثابة على الدعاء ، فمن طلب من الله ولدا أعطاه ، وتفضل عليه بالثواب حيث دعاه ، أو المراد أنه يزيد على الطلب لطفا وكرما ، فمن طلب ولدا أعطاه ولدين ـ مثلا ـ ( وَالْكافِرُونَ لَهُمْ عَذابٌ شَدِيدٌ ) في مقابل المؤمنين لهم الإجابة والفضل. [28] وإذ تقدم أنه سبحانه ، يستجيب للمؤمنين ، ويزيدهم من فضله ، يأتي سؤال أنه ، لماذا نرى حاجة كثير من المؤمنين وفقرهم ، وإنهم يدعون ليل نهار ؟ والجواب ( وَلَوْ بَسَطَ اللهُ الرِّزْقَ لِعِبادِهِ ) بأن وسع عليهم في لَبَغَوْا فِي الْأَرْضِ وَلكِنْ يُنَزِّلُ بِقَدَرٍ ما يَشاءُ إِنَّهُ بِعِبادِهِ خَبِيرٌ بَصِيرٌ (27) وَهُوَ الَّذِي يُنَزِّلُ الْغَيْثَ مِنْ بَعْدِ ما قَنَطُوا وَيَنْشُرُ رَحْمَتَهُ وَهُوَ الْوَلِيُّ الْحَمِيدُ (28) دار الدنيا ، كما يريدون ( لَبَغَوْا فِي الْأَرْضِ ) ف ( إِنَّ الْإِنْسانَ لَيَطْغى * أَنْ رَآهُ اسْتَغْنى ) (1) ، ولذا يضيق عليهم ، حتى يحفظهم من البغي والتعدي وقد حكي : إن معدما سأل موسى أن يطلب من الله ـ في مناجاته ـ أن يتفضل عليه ، فلما سأل موسى ، أجابه الله بذلك ، وأعلمه أن التوسعة على هذا ، لم يكن صلاحا ، وإنما أجاب الدعاء ، وحين رجع موسى من « الطور » رأى المعدم ، وهو يؤخذ للقضاء ، فقالوا : إنه أثرى فشرب الخمر وسكر ، وقتل إنسانا فهو يؤخذ للقصاص ( وَلكِنْ يُنَزِّلُ ) الله الرزق ( بِقَدَرٍ ما يَشاءُ ) مما يراه صلاحا ، وإن قيل ، فلما ذا يفقر بعض الصالحين ، كالأنبياء ، ويثري بعض الفاسدين كالفراعنة ؟ فالجواب ، أن الفقر هناك ، لترفيع الدرجات ، وهنا لإزهاق أرواح هؤلاء بالمال ، حيث تظهر منهم بعض السيئات ، فيستحقون التوسعة للنكال والعذاب ( إِنَّهُ ) تعالى ( بِعِبادِهِ ) جمع عبد ( خَبِيرٌ ) مطلع على أحوالهم ( بَصِيرٌ ) يراهم ، فهم تحت علمه الشامل ، ورؤيته النافذة ، ولذا يدبرهم على نحو الصلاح والحكمة.` },
            { text: "وَلَوْ بَسَطَ ٱللَّهُ ٱلرِّزْقَ لِعِبَادِهِۦ لَبَغَوْا۟ فِى ٱلْأَرْضِ وَلَٰكِن يُنَزِّلُ بِقَدَرٍ مَّا يَشَآءُ إِنَّهُۥ بِعِبَادِهِۦ خَبِيرٌۢ بَصِيرٌ", tafsir: `` },
            { text: "وَهُوَ ٱلَّذِى يُنَزِّلُ ٱلْغَيْثَ مِنۢ بَعْدِ مَا قَنَطُوا۟ وَيَنشُرُ رَحْمَتَهُۥ وَهُوَ ٱلْوَلِىُّ ٱلْحَمِيدُ", tafsir: `أي المطر من السماء ( مِنْ بَعْدِ ما قَنَطُوا ) أي بعد أن يئسوا عن المطر ، وجدبت أراضيهم ، وقحلت ( وَيَنْشُرُ رَحْمَتَهُ ) بإخراج النبات والثمر ، وتنمية الزرع والضرع ، فيرى الإنسان نعمه سبحانه ، منتشرة في سهول الأرض وجبالها ( وَهُوَ الْوَلِيُ ) الذي يلي شؤون عباده ( الْحَمِيدُ ) المحمود في أفعاله ، فما يتفضل به يستحق به ( 1) العلق : 7 و 8. وَمِنْ آياتِهِ خَلْقُ السَّماواتِ وَالْأَرْضِ وَما بَثَّ فِيهِما مِنْ دابَّةٍ وَهُوَ عَلى جَمْعِهِمْ إِذا يَشاءُ قَدِيرٌ (29) وَما أَصابَكُمْ مِنْ مُصِيبَةٍ فَبِما كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ (30) الحمد والشكر.` },
            { text: "وَمِنْ ءَايَٰتِهِۦ خَلْقُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَثَّ فِيهِمَا مِن دَآبَّةٍ وَهُوَ عَلَىٰ جَمْعِهِمْ إِذَا يَشَآءُ قَدِيرٌ", tafsir: `الدالة على وجوده ، وسائر صفاته ( خَلْقُ السَّماواتِ وَالْأَرْضِ ) فمن خلقهما وأوجدهما ، إنه هو الله وحده لا شريك له ( وَما بَثَّ فِيهِما ) أي نشر في السماوات والأرض ( مِنْ دابَّةٍ ) تدب على وجه الأرض ، أو تطير في السماء ( وَهُوَ عَلى جَمْعِهِمْ إِذا يَشاءُ ) الجمع ( قَدِيرٌ ) والمراد بالجمع ، إما الحشر ـ كما قال تعالى : ( وَإِذَا الْوُحُوشُ حُشِرَتْ ) (1) ـ وإما أن يجمعهم في مكان واحد ، وهذا لإلقاء ظلّ قوي من القدرة الوسيعة ، في ذهن المخاطب ، حتى أنه سبحانه ، يتمكن من جميع هذه الكثرة الهائلة المتشتتة من صنوف الحيوان. [31] أرأيتم فضل الله وقدرته ؟ فاعلموا أن انحرافكم عن منهاجه ، يوجب التضييق على أنفسكم ، فما يصيبكم من الأذى ، إنما هو من أعمالكم ، وإلا ففضله سبحانه عام ، كما أنكم لا تقدرون على الفرار من بأسه ، إذا شاء بكم الأذى ، فإنه صاحب القدرة الوسيعة ( وَما أَصابَكُمْ ) أيها الناس ( مِنْ مُصِيبَةٍ ) مالية أو بدنية ، أو غيرهما ( فَبِما كَسَبَتْ أَيْدِيكُمْ ) من الكفر والعصيان ، والنسبة إلى اليد لأنها الآلة العاملة في تحصيل الكثير من الآثام ، كالسرقة والضرب ، والنهب والقتل ، وما أشبه ، ولا يخفى أن هذا العام مخصص بمن لم يكن له كسب سيّء ، فإن ما أصابه ، إنما هو لزيادة الأجر والمنزلة ، كما هو معلوم عقلا ونقلا ( وَيَعْفُوا عَنْ كَثِيرٍ ) فليس يعاقب عليها. ( 1) التكوير : 6. وَما أَنْتُمْ بِمُعْجِزِينَ فِي الْأَرْضِ وَما لَكُمْ مِنْ دُونِ اللهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (31) وَمِنْ آياتِهِ الْجَوارِ فِي الْبَحْرِ كَالْأَعْلامِ (32) إِنْ يَشَأْ يُسْكِنِ الرِّيحَ فَيَظْلَلْنَ رَواكِدَ عَلى ظَهْرِهِ` },
            { text: "وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ", tafsir: `` },
            { text: "وَمَآ أَنتُم بِمُعْجِزِينَ فِى ٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ", tafsir: `أيها البشر ( بِمُعْجِزِينَ فِي الْأَرْضِ ) أي لا تتمكنون من تعجيز الله سبحانه ، بأن تفرون منه ، فلا يقدر على عقوبتكم التي استحققتموها ، ولعل الإتيان ب « في الأرض » للتعميم ، فإن بعض المجرمين أيضا ، لا يتمكنون من تعجيز سلطاتهم في البلاد التي هم مسيطرون عليها ، أما عدم التعجيز في الأرض كلها ، فذلك خاص به سبحانه ( وَما لَكُمْ ) أي ليس لكم أيها البشر ( مِنْ دُونِ اللهِ ) أي سواه ( مِنْ وَلِيٍ ) يلي أموركم ، ويدبر شؤونكم ، ويدفع العذاب عنكم ( وَلا نَصِيرٍ ) ينصركم من بأس الله سبحانه ، وهذا لتنبيه الكفار على أن معاصيهم ، لا بد من الجزاء عليها ، فلا يظنوا أنهم يتمكنون من الفرار ، أو أن أولياءهم ، يتمكنون من دفع العذاب عنهم ، أو أن أنصارهم يقدرون على التغلب على إرادة الله سبحانه.` },
            { text: "وَمِنْ ءَايَٰتِهِ ٱلْجَوَارِ فِى ٱلْبَحْرِ كَٱلْأَعْلَٰمِ", tafsir: `أي آيات الله سبحانه الدالة على وجوده وسائر صفاته ( الْجَوارِ ) جمع جارية ، وهي السفينة ، سميت بها لجريها في الماء ( فِي الْبَحْرِ كَالْأَعْلامِ ) جمع علم ، وهو الجبل الطويل ، فمن جعل الماء بحيث يحملها ، ومن سخر الهواء ، بحيث تجريها إلى حيث تشاء ؟` },
            { text: "إِن يَشَأْ يُسْكِنِ ٱلرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَىٰ ظَهْرِهِۦٓ إِنَّ فِى ذَٰلِكَ لَـَٔايَٰتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ", tafsir: `الله سبحانه ( يُسْكِنِ الرِّيحَ ) بأن لا تتحرك ( فَيَظْلَلْنَ ) أي تلك السفن ، والإتيان بضمير العاقل ، لعله باعتبار من فيها ( رَواكِدَ ) جمع راكدة ، وهي الواقفة في محلها ( عَلى ظَهْرِهِ ) أي ظهر الماء ، إِنَّ فِي ذلِكَ لَآياتٍ لِكُلِّ صَبَّارٍ شَكُورٍ (33) أَوْ يُوبِقْهُنَّ بِما كَسَبُوا وَيَعْفُ عَنْ كَثِيرٍ (34) وَيَعْلَمَ الَّذِينَ يُجادِلُونَ فِي آياتِنا ما لَهُمْ مِنْ مَحِيصٍ (35) فَما أُوتِيتُمْ لا تتحرك من أماكنها ، وهذا بالنسبة إلى السفن الهوائية لا البخارية ( إِنَّ فِي ذلِكَ ) الذي ذكر من تسخير الماء والهواء ، لتسيير السفن ( لَآياتٍ ) دلالات متعددة من البحر والريح والسير ، وغيرها ( لِكُلِّ صَبَّارٍ ) يصبر عند البلاء ( شَكُورٍ ) يشكر عند النعماء ، فإن مثل هذا الإنسان ، الذي نضج عقله ، حتى أنه صار صبارا شكورا ، هو الذي يلتفت إلى هذه النعمة العظيمة ، ويراها الدالة على وجود الله سبحانه ، وسائر صفاته.` },
            { text: "أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا۟ وَيَعْفُ عَن كَثِيرٍ", tafsir: `إن يشأ الله سبحانه ( يُوبِقْهُنَ ) أي يهلك السفن ، بأن يجعل الريح عاصفة حتى تغرقها ( بِما كَسَبُوا ) أي كسب أهلها من الكفر والعصيان ( وَيَعْفُ ) الله سبحانه ( عَنْ كَثِيرٍ ) فإذا أهلكهم ، فببعض ذنوبهم لا بكلها ، وإلا كان الكل مقتضيا ، لإهلاك العاصي قبل ذلك ، وإن رحمهم ، فبعفوه عن جميع الذنوب ، بمعنى عدم معالجته بعقوبتها.` },
            { text: "وَيَعْلَمَ ٱلَّذِينَ يُجَٰدِلُونَ فِىٓ ءَايَٰتِنَا مَا لَهُم مِّن مَّحِيصٍ", tafsir: `هناك ، إذا وقفت الريح أو عصفت ( يَعْلَمَ الَّذِينَ يُجادِلُونَ فِي آياتِنا ) أي يجادلون لإبطال آياتنا ( ما لَهُمْ مِنْ مَحِيصٍ ) أي لا نجاة لهم من تلك التهلكة ، وإنما خصهم ، لأنهم هناك يعترفون ، أما غيرهم ، وهم المؤمنون ، فاعترافهم دائم الأوقات. [37] وإذ بين الله سبحانه بعض نعمه على البشر في البر والبحر ، ألفت الناس إلى أن كل هذه في جنب نعيم الآخرة ، هين يسير ( فَما أُوتِيتُمْ ) مِنْ شَيْءٍ فَمَتاعُ الْحَياةِ الدُّنْيا وَما عِنْدَ اللهِ خَيْرٌ وَأَبْقى لِلَّذِينَ آمَنُوا وَعَلى رَبِّهِمْ يَتَوَكَّلُونَ (36) وَالَّذِينَ يَجْتَنِبُونَ كَبائِرَ الْإِثْمِ وَالْفَواحِشَ وَإِذا ما غَضِبُوا هُمْ يَغْفِرُونَ (37) وَالَّذِينَ اسْتَجابُوا لِرَبِّهِمْ أي أعطيتم أيها البشر ( مِنْ شَيْءٍ ) من هذه النعم فهي متاع ( الْحَياةِ الدُّنْيا ) أي تتمتعون بها في الحياة القريبة الزائلة ( وَما عِنْدَ اللهِ ) والمراد عند رتبته ، بل شرّفها ، وأعلى رتبتها عن رتبة ما في الدنيا ، وإلا فليس لله تعالى مكان ( خَيْرٌ ) من متع هذه الحياة ( وَأَبْقى ) أي أكثر بقاء ، لأنها تبقى دائم الأبد ، وأنها ( لِلَّذِينَ آمَنُوا ) بأن صحت عقيدتهم ( وَعَلى رَبِّهِمْ يَتَوَكَّلُونَ ) في أمورهم ، وذلك دليل الإيمان ، حيث يرون الله سبحانه ، مالك كل شيء ، وبيده أزمة كل شيء.` },
            { text: "فَمَآ أُوتِيتُم مِّن شَىْءٍ فَمَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَا عِندَ ٱللَّهِ خَيْرٌ وَأَبْقَىٰ لِلَّذِينَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمْ يَتَوَكَّلُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ يَجْتَنِبُونَ كَبَٰٓئِرَ ٱلْإِثْمِ وَٱلْفَوَٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمْ يَغْفِرُونَ", tafsir: `عطف على « للذين » والمعنى أن ما عند الله سبحانه ، إنما هو لمن اتصف بهذه الصفات ( يَجْتَنِبُونَ كَبائِرَ الْإِثْمِ ) مثل الزنى والقمار والربا ، وترك الصلاة ، والزكاة ، وما أشبه ، وإنما قال « كبائر الإثم » لأن الصغائر تقع من غير المعصوم ، لا محالة ( وَالْفَواحِشَ ) وهي المعصية الفاحشة التي تتجاوز الحد كثيرا ، وكأن هذا أعظم من الكبائر ، أو المراد التي تسمى في العرف فاحشة ، كالزنى واللواط والسحق وما أشبه ( وَإِذا ما غَضِبُوا ) « ما » زائدة للتأكيد أو مصدرية ، أي حين الغضب ( هُمْ يَغْفِرُونَ ) ذنب الذي أوجب غضبهم ، بأن أزادوا على الحلم ، عن المغضب غفران ذنبه.` },
            { text: "وَٱلَّذِينَ ٱسْتَجَابُوا۟ لِرَبِّهِمْ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ", tafsir: `بأن أجابوه سبحانه في كل ما دعاهم إليه وَأَقامُوا الصَّلاةَ وَأَمْرُهُمْ شُورى بَ يْنَهُمْ من أمور الدين ( وَأَقامُوا الصَّلاةَ ) خصصها بالذكر لأهميتها ، ولصعوبتها على الإنسان ولأنها إذا استقامت ، نهت عن الفحشاء والمنكر بطبعها ( وَأَمْرُهُمْ شُورى بَيْنَهُمْ ) يتشاورون في أمورهم ، هي « فعلى » من المشاورة ، وهي المفاوضة في الكلام ليظهر الحق ، والمراد بالأمور ، هي جميع شؤونهم ، التي لم يجعل لها الله حدا خاصا ، وذلك من المستحب ، في الزواج ، والبيع ، والإجارة ، والتعلم ، والاكتساب ، وغيرها ، وقد تمسك بعض ممن تأثرت أفكارهم بأنظمة الغرب ، بهذه الآية ، لتصحيح الديمقراطية الغربية ، من أحزاب ، وبرلمان ، ومجلس الشيوخ ، وانتخابات ، وما أشبه ، وهذا بالإضافة إلى أنه غلط في نفسه ، وإن وقع فيه كثير من بلاد الغرب ، كما التثليث « في الدين المسيحي » غلط وقعت فيه جماعات كثيرة ، مخالف للإسلام ، ولم يطبقه المسلمون في يوم من الأيام ، وذلك دليل عدم فهمهم من الآية ذلك ولم يفسرها الرسول أو الأئمة عليهم‌السلام بذلك ، فلنأخذ أهل السنة أنهم قالوا ، بأن الرسول مات بلا تعيين ، فأبو بكر خليفة بالقوة ـ كما يظهر ذلك لمن راجع تاريخ السقيفة ـ وعمر بالوصاية من أبي بكر فقط ، وعثمان بجعل من عمر في ستة فقط ـ وإن سماه شورى ، وهل نصب الملوك لشخص في مشاورة سداسية تعتبر انتخابات على ما يريدون هؤلاء ؟ وعلي عليه‌السلام بانتخاب الثوار وجماعة من أهل المدينة ، وإن كثرت الأصوات له بالنسبة إلى سابقيه نوعا ما ، ومجيء علي إلى الحكم ، لأنه عرف نفسه أحق ، لا لأنه انتخب ، ولذا قال في خطبة الشقشقية « وهو يعلم أن محلي منها محل القطب من الرحى » و « أرى تراثي نهبا » ، والحسن عليه‌السلام بالوصاية ، أو انتخاب جماعة من أهل الكوفة ، ومعاوية بالسيف ويزيد بالوصاية ، وهكذا دامت السيف والوصاية إلى آخر خليفة عثماني ، وعمر بن عبد العزيز جاء بالوصاية ، ثم بانتخاب أهل المسجد فقط ـ خوفا من السلطان ، كما هو معلوم في مثل هذه الأحوال ، قديما وحديثا ـ فأين من هذا « الديمقراطية » وإن طورها أحزاب اليوم ألف تطوير ، لإلصاقها بالإسلام ، ويظنون أنه فتح للإسلام ، فبينما هو هدم لأقوى دعائمه ، ثم لنأخذ الشيعة : فنعتقد نحن أن الله كما عين الرسول ، عين الأئمة الاثنى عشر ، ثم عين الأئمة الفقهاء الجامعين للشرائط ، وكل ملك شيعي كان فقيها جامعا للشرائط ، أو كان مأذونا من فقيه جامع للشرائط فهو بحق أصالة أو وكالة ، وكل من فقد هذين الوصفين ، فهو باطل ، ونرى في تاريخ ملوك الشيعة الأقسام الثلاثة ، بدون أن يكون فيهم اسم انتخاب ولو في يوم واحد إلى آخر ملوك القاجار في إيران .. ثم إن الانتخابات بجميع صورها باطلة ليست من الإسلام ، أما انتخابات هذا اليوم فهي أشنع وأبشع ، ولذا أفتى علماء حول مجلس إيران ، بأنه ضلال وانحراف ، وأرادوا تحريره ، فقتل « الشيخ فضل الله النوري » و « السيد عبد الله البهبهاني » و « الشيخ الآخوند المولى محمد كاظم الخراساني » فقد كان قصدهم من « المشروطة » التي أقدموا عليها ، أن يكون للملك جماعة من العلماء العدول ، أقلهم خمسة ، وبعض الناضجين حين ما يريد إنفاذ حكم من أحكام الإسلام ، وتطبيقه على الأمة ، وأرادوا بذلك إحياء سنة الرسول ، وسيرة الخلفاء والملوك الأقدمين حيث كانت مجالسهم لا تخلو من علماء لإرشادهم سبيل الدين ، وناضجين لإرشادهم سبيل الدنيا ـ بالنسبة إلى غير النبي والوصي ـ أما هما فاستشارتهم ، كانت لجلب الخواطر ، وإلا فهم أغنى عن ذلك .. . وأفتى علماء العراق حول وَمِمَّ ا رَزَقْناهُمْ يُنْفِقُونَ (38) وَالَّذِينَ إِذا أَصابَهُمُ الْبَغْيُ هُمْ يَنْتَصِرُونَ (39) وَجَزاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُها مجلس الأمة ، حين أراد « فيصل » فتحه بأمر الإنكليز ، لهدم الإسلام ، بأن « المنتخب والمنتخب كلاهما في النار » وقد لقوا جزاء فتياهم تشريدا وتسميما وإهانة وهتكا ، فمن أراد اليوم إعادة « المجلس » أو « الانتخاب » أو « الديمقراطية » أو « الأحزاب » أو ما شابه ذلك ، بزعم أنه خدمة للإسلام وخلاص للمسلمين ، فليعلم ـ إن كان مخلصا ـ أنه يبني من جديد لهدم الإسلام ، في لباس الإسلام ، وسيرى في الدنيا انقلاب الأمر عليه ، وفي الآخرة الخسارة والنكال ، فإن هذا أساس غربي بحت لا يمت إلى الإسلام بصلة أصلا ، ومن كان شاكا فليدرس الإسلام من جديد ، لا على ضوء الأنظمة الغربية ، وما ارتكز في ذهنه من سموم الأجواء التي نشرها الغرب وعملائه ، بل على ضوء الكتاب والسنة ، وفتوى الفقهاء ، الذين هم أعرف الناس بالإسلام وبنظمه ( وَمِمَّا رَزَقْناهُمْ ) من المال والعلم والجاه ، وغيرها ـ حسب عموم الآية ـ وإن كان المنصرف خصوص المال ( يُنْفِقُونَ ) في سبيل الله.` },
            { text: "وَٱلَّذِينَ إِذَآ أَصَابَهُمُ ٱلْبَغْىُ هُمْ يَنتَصِرُونَ", tafsir: `أي الظلم ، بأن ظلمهم أحد ( هُمْ يَنْتَصِرُونَ ) بأن ينتقموا ممن تعدى عليهم ، لئلا يصيبهم الذل ، ولئلا يجرأ الظالم على التمادي في غيه ، إن رأى الباب أمامه مفتوحا ، وغير خاف أن هذا لا ينافي قوله ( إِذا ما غَضِبُوا هُمْ يَغْفِرُونَ ) فلكل شيء مجاله. [41] ثم بين سبحانه حد الانتصار لئلا يتجاوز المظلوم على مقدار ما ظلم انتقاما وتشفيا ( وَجَزاءُ سَيِّئَةٍ ) يوردها الظالم ( سَيِّئَةٌ مِثْلُها ) يردها المظلوم ، وسميت سيئة ، من باب المزاوجة ، لكون الرد شبيه التعدي فَمَنْ عَفا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللهِ إِنَّهُ لا يُحِبُّ الظَّالِمِينَ (40) وَلَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولئِكَ ما عَلَيْهِمْ مِنْ سَبِيلٍ (41) إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ وَيَبْغُونَ فِي الْأَرْضِ في الشكل ، ومنه قوله تعالى ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) (1) وقوله ( تَعْلَمُ ما فِي نَفْسِي وَلا أَعْلَمُ ) (2) ( فَمَنْ عَفا وَأَصْلَحَ ) بأن عفا عن المعتدي فيما كان ذلك ثوابا ، لا عقابا ، بأن أذل نفسه ، وجرأ المعتدي على التمادي في العدوان ، وأصلح فيما بينه وبين الله ، بأن كان عفوه لله سبحانه ، لا لغاية دنيوية ، أو أصلح بين عدوه ونفسه ( فَأَجْرُهُ عَلَى اللهِ ) فإنه يثيبه جزاء عفوه وإصلاحه ( إِنَّهُ لا يُحِبُّ الظَّالِمِينَ ) فليس ترغيبه في العفو ، لأنه أخذ جانب الظالم ، بل لأجل ، أن بعض الناس يصلحهم العفو أكثر مما تصلحهم العقوبة ، ولأنه موجب لعظيم مثوبة المظلوم.` },
            { text: "وَجَزَٰٓؤُا۟ سَيِّئَةٍ سَيِّئَةٌ مِّثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُۥ عَلَى ٱللَّهِ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "وَلَمَنِ ٱنتَصَرَ بَعْدَ ظُلْمِهِۦ فَأُو۟لَٰٓئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ", tafsir: `لنفسه من ظالمة ، بأن رد اعتدائه بالمثل ( بَعْدَ ظُلْمِهِ ) أي بعد أن ظلمه الظالم ( فَأُولئِكَ ) المنتصرون ، وإنما جيء بالجمع ، باعتبار معنى « من » وقد تقرر في الأدب أنه يجوز في من وما مراعاة اللفظ ، والمعنى ( ما عَلَيْهِمْ مِنْ سَبِيلٍ ) أي من إثم وعقاب في الآخرة ، لأنه أخذ حقه ولم يتعد.` },
            { text: "إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظْلِمُونَ ٱلنَّاسَ وَيَبْغُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ أُو۟لَٰٓئِكَ لَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `في عقاب الدنيا بواسطة السلطان وعقاب الآخرة ( عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ ) ابتداء ( وَيَبْغُونَ فِي الْأَرْضِ ) أي ( 1) البقرة : 195. ( 2) المائدة : 117. بِغَيْرِ الْحَقِّ أُولئِكَ لَهُمْ عَذابٌ أَلِيمٌ (42) وَلَمَنْ صَبَرَ وَغَفَرَ إِنَّ ذلِكَ لَمِنْ عَزْمِ الْأُمُورِ (43) وَمَنْ يُضْلِلِ اللهُ فَما لَهُ مِنْ وَلِيٍّ مِنْ بَعْدِهِ وَتَرَى الظَّالِمِينَ لَمَّا رَأَوُا الْعَذابَ يَقُولُونَ هَلْ إِلى مَرَدٍّ يفسدون في الأرض ، وإنما جيء ، ب « في الأرض » لبيان أن كل بغي ، إنما يظهر أثره في الأرض ، وأن ظنه الظالم صغيرا موضعيا (1) ( بِغَيْرِ الْحَقِ ) فإن كل بغي بغير الحق وإنما جيء بهذا الوصف ، لإظهار البشاعة ، وتعليل « إنما السبيل » ( أُولئِكَ ) الباغون ( لَهُمْ عَذابٌ أَلِيمٌ ) مؤلم موجع في الدنيا بالحد والتعزيز ، وفي الآخرة بالنار والنكال.` },
            { text: "وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ ٱلْأُمُورِ", tafsir: `على الأذى ( وَغَفَرَ ) أي عفى عن المؤذي ـ فيما كان الغفران خيرا ـ ( إِنَّ ذلِكَ ) منه ( لَمِنْ عَزْمِ الْأُمُورِ ) أي الأمور التي تحتاج إلى عزيمة قوية في النفس ، وليس من الأمور التي تأتي عفويا ، حسب إرادة عادية ، فإن ذلك بحاجة إلى شجاعة نفسية فائقة. [45] وبعد استعراض صورة للمؤمنين في دنياهم وآخرتهم ، يأتي السياق لنقل حال الكافرين في النشأتين ( وَمَنْ يُضْلِلِ اللهُ ) بأن يتركه وشأنه ، بعد أن أراه الطريق فلم يسلكه ، وهذا هو معنى الإضلال ، كما سبق ( فَما لَهُ مِنْ وَلِيٍ ) يلي أموره ، ويأخذ بيده ( مِنْ بَعْدِهِ ) أي من بعد الله سبحانه ، إذ لا هادي إلا الله تعالى ( وَتَرَى ) يا رسول الله أو أيها الرائي ( الظَّالِمِينَ ) الذين ظلموا أنفسهم بالكفر والعصيان ، ( لَمَّا رَأَوُا الْعَذابَ ) يوم القيامة ( يَقُولُونَ هَلْ إِلى مَرَدٍّ ) أي رد إلى الدنيا ، فإن ( 1) العدالة الإسلامية للمؤلف. مِنْ سَبِيلٍ (44) وَتَراهُمْ يُعْرَضُونَ عَلَيْها خاشِعِينَ مِنَ الذُّلِّ يَنْظُرُونَ مِنْ طَرْفٍ خَفِيٍّ وَقالَ الَّذِينَ آمَنُوا إِنَّ الْخاسِرِينَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيامَةِ أَلا إِنَّ الظَّالِمِينَ فِي عَذابٍ مُقِيمٍ (45) « مرد » مصدر ميمي ( مِنْ سَبِيلٍ ) تمنيا منهم للرجوع إلى الدنيا ، حتى يعملوا صالحا ـ بظنهم ـ .` },
            { text: "وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِىٍّ مِّنۢ بَعْدِهِۦ وَتَرَى ٱلظَّٰلِمِينَ لَمَّا رَأَوُا۟ ٱلْعَذَابَ يَقُولُونَ هَلْ إِلَىٰ مَرَدٍّ مِّن سَبِيلٍ", tafsir: `` },
            { text: "وَتَرَىٰهُمْ يُعْرَضُونَ عَلَيْهَا خَٰشِعِينَ مِنَ ٱلذُّلِّ يَنظُرُونَ مِن طَرْفٍ خَفِىٍّ وَقَالَ ٱلَّذِينَ ءَامَنُوٓا۟ إِنَّ ٱلْخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ ٱلْقِيَٰمَةِ أَلَآ إِنَّ ٱلظَّٰلِمِينَ فِى عَذَابٍ مُّقِيمٍ", tafsir: `أي ترى الظالمين ( يُعْرَضُونَ عَلَيْها ) أي النار ، والمعنى تعرض النار عليها ، وإنما جيء هكذا ، لأنهم يذهب بهم من عند النار أو من باب « القلب » كقوله « كما طينت بالفدن السياعا » ( خاشِعِينَ ) أي متواضعين ( مِنَ الذُّلِ ) الذي أخذهم حيث وجدوا مرارة النكال والحكم ، عليهم بالعذاب والهوان ( يَنْظُرُونَ ) إذا أرادوا النظر إلى شيء ( مِنْ طَرْفٍ خَفِيٍ ) فإن الإنسان الذي لم يجرم ينظر إلى الإنسان والأشياء بكل عينه ، أما المجرم فإنه يختلس النظر بخفاء ، لئلا يراه أحد فيشتمه أو يؤذيه ، أو يخجل منه ، فإن الحياة غالية في العين ( وَقالَ الَّذِينَ آمَنُوا ) تعريضا بهم وجوابا لما قال الظالمون لهم ، في الحياة ، بأنهم يخسرون بسبب الإيمان سعادتهم ومستقبلهم ( إِنَّ الْخاسِرِينَ ) هم ( الَّذِينَ خَسِرُوا أَنْفُسَهُمْ ) حيث عذبوها وأوقعوها في النار ( وَأَهْلِيهِمْ ) حيث فارقوهم ، سواء كانوا من أهل الجنة ، أو من أهل النار ( يَوْمَ الْقِيامَةِ ) فإن هذا هو الخسارة الكبرى ، لا ذهاب بعض المنافع الدنيوية ، كما كان يقول الكفار للمؤمنين ، في دار الدنيا ( أَلا ) فليتنبه السامع ( إِنَّ الظَّالِمِينَ فِي عَذابٍ مُقِيمٍ ) لا يتحول عنهم أبدا ، والمراد وَما كانَ لَهُمْ مِنْ أَوْلِياءَ يَنْصُرُونَهُمْ مِنْ دُونِ اللهِ وَمَنْ يُضْلِلِ اللهُ فَما لَهُ مِنْ سَبِيلٍ (46) اسْتَجِيبُوا لِرَبِّكُمْ مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لا مَرَدَّ لَهُ مِنَ اللهِ ما لَكُمْ مِنْ مَلْجَإٍ يَوْمَئِذٍ وَما لَكُمْ مِنْ نَكِيرٍ (47) بالظالمين المعاندين من الكفار ، فإنهم هم المخلدون.` },
            { text: "وَمَا كَانَ لَهُم مِّنْ أَوْلِيَآءَ يَنصُرُونَهُم مِّن دُونِ ٱللَّهِ وَمَن يُضْلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِيلٍ", tafsir: `أي للظالمين ( مِنْ أَوْلِياءَ ) جمع ولي ، أي أصدقاء وأحباء ( يَنْصُرُونَهُمْ مِنْ دُونِ اللهِ ) أي من عذاب الله ، بأن يدفعوا عنهم عذابه ونكاله ، أو أن « من دون الله » متعلق ب « أولياء » أي لا ولي غير الله ، ينصر ( وَمَنْ يُضْلِلِ اللهُ ) بأن يتركه وشأنه ، بعد أن أراه الطريق ، فلم يهتد ( فَما لَهُ مِنْ سَبِيلٍ ) يوصله إلى المقصد ، وهو السعادة ، إذ السبيل الوحيد ، هو سبيل الله ، فإذا تركه الإنسان ، لم يكن هناك سبيل آخر يوجب النجاة والخلاص.` },
            { text: "ٱسْتَجِيبُوا۟ لِرَبِّكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِ مَا لَكُم مِّن مَّلْجَإٍ يَوْمَئِذٍ وَمَا لَكُم مِّن نَّكِيرٍ", tafsir: `أيها الناس ، ولعل الإتيان من باب « الاستفعال » لفرض بيان أن الإجابة يلزم أن تكون من القلب بطلب وإرادة ، لا مجرد إجابة لفظية ، وعمل سطحي ( لِرَبِّكُمْ ) بالإيمان به ، وإطاعة أوامره ( مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ ) هو يوم القيامة ( لا مَرَدَّ لَهُ ) أي لا رجوع لذلك اليوم ، بأن يتأخر عن موعده ، حتى يجد العصاة فرصة لاستئناف العمل ( مِنَ اللهِ ) إما بمعنى ، إن الله لا يرده ، أو أنه لا يرد على الله ، بأنه يرده أحد خلافا لإرادة الله ( ما لَكُمْ ) أيها البشر ( مِنْ مَلْجَإٍ يَوْمَئِذٍ ) تلجئون إليه ، وتقون أنفسكم بسببه عن عذاب ذلك اليوم ( وَما لَكُمْ مِنْ نَكِيرٍ ) أي منكر ينصركم ، أو إنكار : بمعنى أنكم لا تقدرون على الاستنكار فَإِنْ أَعْرَضُوا فَما أَرْسَلْناكَ عَلَيْهِمْ حَفِيظاً إِنْ عَلَيْكَ إِلاَّ الْبَلاغُ وَإِنَّا إِذا أَذَقْنَا الْإِنْسانَ مِنَّا رَحْمَةً فَرِحَ بِها وَإِنْ تُصِبْهُمْ سَيِّئَةٌ بِما قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ الْإِنْسانَ كَفُورٌ (48) لشدة الهول والفزع ، أو لما ترون من عدم الفائدة في إنكاره.` },
            { text: "فَإِنْ أَعْرَضُوا۟ فَمَآ أَرْسَلْنَٰكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا ٱلْبَلَٰغُ وَإِنَّآ إِذَآ أَذَقْنَا ٱلْإِنسَٰنَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌۢ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ ٱلْإِنسَٰنَ كَفُورٌ", tafsir: `يا رسول الله ، ولم يؤمنوا فلا يهمك أمرهم ، ولا تذهب نفسك عليهم حسرات ، إذ ما ( أَرْسَلْناكَ عَلَيْهِمْ حَفِيظاً ) أي مأمورا بحفظهم حتى يكون خروجهم خلاف مسئوليتك ، وما كلفت به ( إِنْ عَلَيْكَ ) أي ما عليك يا رسول الله ( إِلَّا الْبَلاغُ ) فأنت مأمور بالتبليغ والإرشاد ، وقد فعلت ذلك ( وَ ) هؤلاء بعداء عن الإيمان ، لما جبلوا عليه من البطر حالة الرخاء والكفر حالة البلاء وكيف هؤلاء يخالفون حتى يبتلوا بالنار ـ مع هذا الطبع الرقيق الذي لا يتحمل نقمة ولا شدة ـ ؟ ف ( إِنَّا إِذا أَذَقْنَا الْإِنْسانَ ) والمراد به هؤلاء ، لا كل إنسان ، وإنما جيء باللفظ العام ، لأن ذلك هو الطبع الغالب ( مِنَّا رَحْمَةً ) أي أوصلنا إليه من طرفنا رحمة ( فَرِحَ بِها ) أي بطر وتجاوز الحد ، كما قال له قومه ( لا تَفْرَحْ إِنَّ اللهَ لا يُحِبُّ الْفَرِحِينَ ) (1) ( وَإِنْ تُصِبْهُمْ سَيِّئَةٌ ) أي صفة تسؤهم كالفقر والمرض والخوف ، وما أشبه ( بِما قَدَّمَتْ أَيْدِيهِمْ ) أي كانت تلك السيئة جزاء لبعض أعمالهم ، والنسبة إلى « اليد » لأنها العضو الغالب في الإتيان بالأفعال ، وإلا فالمراد كل معصية ( فَإِنَّ الْإِنْسانَ كَفُورٌ ) يجزع من البلاء ، وينسى النعماء. ( 1) القصص : 77. لِلَّهِ مُلْكُ السَّماواتِ وَالْأَرْضِ يَخْلُقُ ما يَشاءُ يَهَبُ لِمَنْ يَشاءُ إِناثاً وَيَهَبُ لِمَنْ يَشاءُ الذُّكُورَ (49) أَوْ يُزَوِّجُهُمْ ذُكْراناً وَإِناثاً وَيَجْعَلُ مَنْ يَشاءُ عَقِيماً إِنَّهُ عَلِيمٌ قَدِيرٌ (50) [50] والنعم كلها من الله سبحانه ، حتى أعظم النعم التي توجب امتداد الإنسان ـ وهي الذرية ـ فلم يبتعد الإنسان عن الله ، وهو المنعم والمتفضل عليه ؟ ( لِلَّهِ مُلْكُ السَّماواتِ وَالْأَرْضِ ) فهو خالقهما ومالكهما ، والمراد الظرف والمظروف معا ( يَخْلُقُ ما يَشاءُ ) فله الملك ، وبيده الخلق ، ومنه الإعطاء ، والمنع ( يَهَبُ ) أي يعطي على وجه الهبة المجانية ( لِمَنْ يَشاءُ ) من الناس ( إِناثاً ) جمع أنثى ، أي البنات ، والمراد بالجمع الجنس ـ وقد سبق ، أن كلا من الجمع والجنس ، يخلف الآخر في المعنى ـ ( وَيَهَبُ لِمَنْ يَشاءُ الذُّكُورَ ) جمع ذكر ، أي البنين.` },
            { text: "لِّلَّهِ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ يَخْلُقُ مَا يَشَآءُ يَهَبُ لِمَن يَشَآءُ إِنَٰثًا وَيَهَبُ لِمَن يَشَآءُ ٱلذُّكُورَ", tafsir: `` },
            { text: "أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَٰثًا وَيَجْعَلُ مَن يَشَآءُ عَقِيمًا إِنَّهُۥ عَلِيمٌ قَدِيرٌ", tafsir: `أي يجمع لهم ، يقول العرب : زوجت إبلي ، أي جمعت بين كبارها وصغارها ( ذُكْراناً وَإِناثاً ) فيعطيهم من الجنسين ، إما في بطن واحد ، أو بطون متعددة ( وَيَجْعَلُ مَنْ يَشاءُ ) من الرجال أو النساء ( عَقِيماً ) لا يصير له ولد ، إما بضعف مني الرجل ، أو ضعف رحم المرأة ( إِنَّهُ ) سبحانه ( عَلِيمٌ ) بالمصالح ( قَدِيرٌ ) لما يشاء. [52] وإذ تقدم جملة من شؤون المعاد ، والألوهية ، جاء السياق لبيان بعض شؤون الرسالة ، كما هي العادة في السور المكية ، تبين من كل هذه وَما كانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللهُ إِلاَّ وَحْياً أَوْ مِنْ وَراءِ حِجابٍ أَوْ يُرْسِلَ رَسُولاً فَيُوحِيَ بِإِذْنِهِ ما يَشاءُ إِنَّهُ عَلِيٌّ حَكِيمٌ (51) وَكَذلِكَ الأصول نتفا وأطرافا ، وقد كان الكفار يطلبون من الرسول أن يروا الله يكلمهم وجها لوجه ، حتى يصدقوا كما قالوا ( لَوْ لا يُكَلِّمُنَا اللهُ ) (1) فجاء الجواب ( وَما كانَ لِبَشَرٍ ) أي لا يمكن للبشر مهما كان عظمه وقدره ( أَنْ يُكَلِّمَهُ اللهُ ) وجها لوجه ، فإنه سبحانه لا يمكن رؤيته ، إذ ليس جسما ، ولا جسمانيا ، حتى يرى ( إِلَّا وَحْياً ) بأن يلقي في قلبه إلقاء ، فإن أصل الوحي ، هو الإلقاء الخفي بحيث لا يعرفه غير المخاطب ( أَوْ مِنْ وَراءِ حِجابٍ ) بأن يتكلم الله معه ، ولا يراه تعالى ، فكان حجابا فاصل بينهما ، وهذا كناية عن عدم الرؤية ( أَوْ يُرْسِلَ ) سبحانه ( رَسُولاً ) أي ملكا ، ليكلم الإنسان عن الله سبحانه ( فَيُوحِيَ ) بواسطة ذلك الملك أو يوحي الملك ، ويلقي في قلب الرسول ( بِإِذْنِهِ ) أي بإذن الله تعالى ( ما يَشاءُ ) من المعارف والأحكام ، والإتيان بلفظ « بإذنه » لإفادة ، أن كلّا من مجيء الملك ، وتكلمه مع الرسول ، بحاجة إلى الإذن والأمر ( إِنَّهُ ) سبحانه ( عَلِيٌ ) أي رفيع عن إدراك البشر ، فلا يراه أحد ( حَكِيمٌ ) في جميع أفعاله فلا يكلم أحدا إلا الرسول ، أو ما أشبه ، أما أن يكلم كل أحد ، فليس ذلك من الحكمة لعدم قابلية مطلق البشر لكلام الله مباشرة.` },
            { text: "وَمَا كَانَ لِبَشَرٍ أَن يُكَلِّمَهُ ٱللَّهُ إِلَّا وَحْيًا أَوْ مِن وَرَآئِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِىَ بِإِذْنِهِۦ مَا يَشَآءُ إِنَّهُۥ عَلِىٌّ حَكِيمٌ", tafsir: `` },
            { text: "وَكَذَٰلِكَ أَوْحَيْنَآ إِلَيْكَ رُوحًا مِّنْ أَمْرِنَا مَا كُنتَ تَدْرِى مَا ٱلْكِتَٰبُ وَلَا ٱلْإِيمَٰنُ وَلَٰكِن جَعَلْنَٰهُ نُورًا نَّهْدِى بِهِۦ مَن نَّشَآءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِىٓ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `أي كما أوحينا إلى الأنبياء السابقين ، أو بمعنى هكذا ـ ( 1) البقرة : 119. أَوْحَيْنا إِلَيْكَ رُوحاً مِنْ أَمْرِنا ما كُنْتَ تَدْرِي مَا الْكِتابُ وَلا الْإِيمانُ وَلكِنْ جَعَلْناهُ نُوراً نَهْدِي بِهِ مَنْ نَشاءُ مِ نْ عِبادِنا وَإِنَّكَ لَتَهْدِي على تقريب تقدم بيانه ـ ( أَوْحَيْنا إِلَيْكَ ) يا رسول الله ( رُوحاً ) والمراد به الشريعة ، إذ هي روح الحياة السعيدة ، فإن الإنسان بدون الشريعة ، كالميت الذي لا يعقل ، ولا يشعر ، ولا يبصر ، ولا يسمع ، إذ هو خال عن الحقائق الكونية ، ضال عن طريق الرشد ( مِنْ أَمْرِنا ) أي ناشئا تلك الروح من أمرنا وإرادتنا ، فهو صادر عنا ، فإن الإنسان ، قد يعطي من نفسه ، وقد يعطي من غيره ، وما يعطي من النفس ، أكثر خيرا وتكرمة ، ولعل الإتيان ، ب « من أمرنا » لبيان ذلك ( ما كُنْتَ تَدْرِي ) يا رسول الله ( مَا الْكِتابُ ) قبل أن يوحى إليك ( وَلَا الْإِيمانُ ) قبل أن تتلقنه ، ومن البديهي أن الرسول صلى‌الله‌عليه‌وآله‌وسلم قبل إلقاء الله إليه الكتاب والإيمان ، لم يكن يعلمهما ، وإنما الكلام في أن الآية ساكتة عن وقت ذلك ، والظاهر أنه قبل خلق العالم ، فهو حكاية عن ابتداء خلقة الرسول في العوالم العلوية ، كما ورد « كنت نبيا ، وآدم بين الماء والطين » (1) ( وَلكِنْ ) نحن الذين أعلمناك ( جَعَلْناهُ ) أي جعلنا الكتاب والإيمان ـ باعتبار كل واحد منهما ـ ( نُوراً ) لدروب الحياة المظلمة ( نَهْدِي بِهِ مَنْ نَشاءُ ) من الذين يقبلون الدعوة ، فالمراد بالهداية : الألطاف الخاصة ، أما إرشاد الطريق ، فهو عام لكل أحد ( مِنْ عِبادِنا ) جمع عبد ( وَإِنَّكَ ) يا رسول الله ( لَتَهْدِي ) وترشد ( 1) مفتاح الفلاح : ص 41. إِلى صِراطٍ مُسْتَقِيمٍ (52) صِراطِ اللهِ الَّذِي لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ أَلا إِلَى اللهِ تَصِيرُ الْأُمُورُ (53) الناس ( إِلى صِراطٍ مُسْتَقِيمٍ ) لا التواء فيه ، ولا انحراف ، فكتابك نور ، وأنت هاد ، والدرب الذي تهدي إليه ، صراط مستقيم موصل إلى السعادة.` },
            { text: "صِرَٰطِ ٱللَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ أَلَآ إِلَى ٱللَّهِ تَصِيرُ ٱلْأُمُورُ", tafsir: `` }
        ]
    },
    43: { // سورة الزخرف
        name: "الزخرف",
        basmalaTafsir: ``,
        verses: [
            { text: "حمٓ", tafsir: `« حاء » و « ميم » وما أشبههما من سائر حروف الهجاء مادة هذا القرآن المعجز الذي لا يتمكن البشر من الإتيان بمثله ولو كان بعضهم لبعض ظهيرا ، أو رمز بين الله والرسول ، أو غيرهما من سائر الأقوال.` },
            { text: "وَٱلْكِتَٰبِ ٱلْمُبِينِ", tafsir: `أي قسما بهذا القرآن الواضح الذي يظهر الحق ويبينه.` },
            { text: "إِنَّا جَعَلْنَٰهُ قُرْءَٰنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ", tafsir: `أي بلغة العرب ، حين اختار منهم من يحمل هذه الرسالة ، واختار محلهم منبثقا لهذا الوحي الثمين ( لَعَلَّكُمْ تَعْقِلُونَ ) وهذا هو المقسم به ، أي أن الغاية من إنزال القرآن عربيا تعقلكم وتفهمكم للحقائق ، يا معشر العرب.` },
            { text: "وَإِنَّهُۥ فِىٓ أُمِّ ٱلْكِتَٰبِ لَدَيْنَا لَعَلِىٌّ حَكِيمٌ", tafsir: `هذا القرآن ( فِي أُمِّ الْكِتابِ ) وهو اللوح المحفوظ ، وإنما سمي بذلك لأنه أصل الكتب السماوية وغيرها ، حيث إن كل شيء مدروج فيه على نحو الصواب والحكمة ، فهو المرجع الوحيد الصحيح ، كالأم التي هي أصل الإنسان ، ومنها جاء وإليها يأوي ( لَدَيْنا ) أي الذي عندنا ( لَعَلِيٌ ) أي رفيع ذو قيمة ورتبة ( حَكِيمٌ ) قد وضع الأشياء موضعها اللائق بها من تشريع وأخبار وبيان وغيرها ، فإن الحكمة وضع الأشياء مواضعها اللائقة بها ، ويسمى الكتاب حكيما باعتبار اشتماله على الأشياء الحكيمة. [6] وإذا كان هذا القرآن بهذه المثابة ، فهل ترفع اليد عنه بمجرد أن جماعة أَ فَنَضْرِبُ عَنْكُمُ الذِّكْرَ صَفْحاً أَنْ كُنْتُمْ قَوْماً مُسْرِفِينَ (5) وَكَمْ أَرْسَلْنا مِنْ نَبِيٍّ فِي الْأَوَّلِينَ (6) وَما يَأْتِيهِمْ مِنْ نَبِيٍّ إِلاَّ كانُوا بِهِ يَسْتَهْزِؤُنَ (7) فَأَهْلَكْنا أَشَدَّ مِنْهُمْ كذبوا به وأسرفوا في الابتعاد عنه ؟ ( أَ فَنَضْرِبُ عَنْكُمُ ) يا معشر الناس ( الذِّكْرَ ) أي القرآن ( صَفْحاً ) أي أ نترك الوحي ؟ وأصله من ضرب الحيوان على صفحة وجهه ليميل عن طريقه إلى ما يراد به ، ثم استعمل في كل تحريف لشيء عن الطريق ( أَنْ كُنْتُمْ ) أي لأجل أنكم كنتم ( قَوْماً مُسْرِفِينَ ) تسرفون وتجاوزون في الكفر والعصيان ؟ كلا ! لا يكون هذا ، ( فَإِنْ يَكْفُرْ بِها هؤُلاءِ فَقَدْ وَكَّلْنا بِها قَوْماً لَيْسُوا بِها بِكافِرِينَ ) (1) بالإضافة إلى أنه إتمام الحجة ، وتوضيح للمحجة. [7] وليس هذا الأمر غريبا من هؤلاء فقد كانت عادة الأمم تكذيب الأنبياء ( وَكَمْ أَرْسَلْنا مِنْ نَبِيٍّ فِي الْأَوَّلِينَ ) في الأمم الماضية ، و « كم » خبرية للتكثير.` },
            { text: "أَفَنَضْرِبُ عَنكُمُ ٱلذِّكْرَ صَفْحًا أَن كُنتُمْ قَوْمًا مُّسْرِفِينَ", tafsir: `` },
            { text: "وَكَمْ أَرْسَلْنَا مِن نَّبِىٍّ فِى ٱلْأَوَّلِينَ", tafsir: `` },
            { text: "وَمَا يَأْتِيهِم مِّن نَّبِىٍّ إِلَّا كَانُوا۟ بِهِۦ يَسْتَهْزِءُونَ", tafsir: `أي الأولين ( مِنْ نَبِيٍ ) من : لتعميم النفي ( إِلَّا كانُوا بِهِ يَسْتَهْزِؤُنَ ) فإن الجهال إذا انقطعوا عن الحجة استهزءوا وتمسخروا حتى يغلبوا خصمهم بسبب انهيار أعصابه أمام الاستهزاء ، فلا يتمكن من مواصلة الاحتجاج.` },
            { text: "فَأَهْلَكْنَآ أَشَدَّ مِنْهُم بَطْشًا وَمَضَىٰ مَثَلُ ٱلْأَوَّلِينَ", tafsir: `بسبب الاستهزاء وعدم الإيمان ( أَشَدَّ مِنْهُمْ ) أي من هو ( 1) الأنعام : 90. بَطْشاً وَمَضى مَثَلُ الْأَوَّلِينَ (8) وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّماواتِ وَالْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ الْعَزِيزُ الْعَلِيمُ (9) الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْداً وَجَعَلَ لَكُمْ فِيها سُبُلاً أشد من هؤلاء القوم ( بَطْشاً ) أي قوة ومنعة ، فلا يغتر هؤلاء المشركون بالقوة والعدة ، فإنها أمام إرادة الله سبحانه لا مجال لها ( وَمَضى مَثَلُ الْأَوَّلِينَ ) أي قد سلف في القرآن أمثال أولئك الأقوام الذين أهلكناهم ، وقصصهم ، فقد سبق شباهة أولئك الكفار السابقين بهؤلاء الكفار من قومك. [10] وإذ قدم بعض الكلام حول الرسالة والقرآن يأتي الكلام حول التوحيد ( وَلَئِنْ سَأَلْتَهُمْ ) أي سألت هؤلاء الكفار يا رسول الله ( مَنْ خَلَقَ السَّماواتِ وَالْأَرْضَ ) هل هو الله أم الأصنام ؟ لم يجدوا بدّا من الاعتراف بالحقيقة ، لأنهم لا يجدون سبيلا إلا القول بكون الخلق للأصنام ف ( لَيَقُولُنَّ خَلَقَهُنَ ) والإتيان بضمير العاقل ، أما من جهة تغليب من فيها عليها ، أو لما قالوا من جواز الأمرين ـ من « هن » و « ها » في غير العاقل ـ ( الْعَزِيزُ ) الغالب في سلطانه ( الْعَلِيمُ ) بكل شيء فإن هذا الخلق المدهش لا يمكن إلا أن يكون من صنع قادر عالم ، والأصنام عاجزة جاهلة.` },
            { text: "وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ لَيَقُولُنَّ خَلَقَهُنَّ ٱلْعَزِيزُ ٱلْعَلِيمُ", tafsir: `` },
            { text: "ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ مَهْدًا وَجَعَلَ لَكُمْ فِيهَا سُبُلًا لَّعَلَّكُمْ تَهْتَدُونَ", tafsir: `أي محلا للسكنى ، فتستقرون فيها ـ وهذا من باب الالتفات المذكور في علم البلاغة ـ ( وَجَعَلَ لَكُمْ ) أيها البشر ( فِيها ) أي في الأرض ( سُبُلاً ) جمع سبيل وهو الطريق ، لَعَلَّكُمْ تَهْتَدُونَ (10) وَالَّذِي نَزَّلَ مِنَ السَّماءِ ماءً بِقَدَرٍ فَأَنْشَرْنا بِهِ بَلْدَةً مَيْتاً كَذلِكَ تُخْرَجُونَ (11) وَالَّذِي خَلَقَ الْأَزْواجَ كُلَّها وَجَعَلَ لَكُمْ مِنَ الْفُلْكِ وَالْأَنْعامِ ما تَرْكَبُونَ (12) لِتَسْتَوُوا عَلى ليتمكن الإنسان من السير والسفر ( لَعَلَّكُمْ تَهْتَدُونَ ) إلى خالقكم حيث ترون هذه الآثار الباهرة الدالة على عالم قدير حكيم.` },
            { text: "وَٱلَّذِى نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءًۢ بِقَدَرٍ فَأَنشَرْنَا بِهِۦ بَلْدَةً مَّيْتًا كَذَٰلِكَ تُخْرَجُونَ", tafsir: `أي المطر ، والمراد بالسماء جهة العلو ( بِقَدَرٍ ) فليس المطر ـ على ما يزعمه الغافل ـ يكون بكثرة لا قدر لها ، فإن الله قد حسب ذلك حسابا دقيقا ، وأنزله بقدر الحاجة لا زائدا ولا ناقصا ( فَأَنْشَرْنا بِهِ ) أي أحيينا بسبب المطر ( بَلْدَةً مَيْتاً ) أي جافة يابسة لا حركة فيها ، كالميت الذي لا حراك له ، والإحياء إنما هو بإخراج النبات والثمار ، والمراد أرض البلدة التي في أطرافها ، وإنما أضيف الإحياء إليها لأنها المنتفعة بالمطر ( كَذلِكَ ) أي رأيتم من إحياء الأرض بعد موتها ( تُخْرَجُونَ ) أنتم من القبور بعد الموت للنشر والقيامة.` },
            { text: "وَٱلَّذِى خَلَقَ ٱلْأَزْوَٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلْفُلْكِ وَٱلْأَنْعَٰمِ مَا تَرْكَبُونَ", tafsir: `أي الذكر والأنثى من الإنسان والحيوان والنبات والمعدن وغيرها ، أو المراد بالأزواج الأصناف ( وَجَعَلَ لَكُمْ ) أي لمنافعكم ( مِنَ الْفُلْكِ ) أي السفن ( وَالْأَنْعامِ ) الإبل ( ما تَرْكَبُونَ ) عليه في البحر والبر ، وإنما قال من « الفلك » لأن بعض السفن ليست صالحة للركوب كما أن بعض الأنعام كالغنم مثلا كذلك.` },
            { text: "لِتَسْتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذْكُرُوا۟ نِعْمَةَ رَبِّكُمْ إِذَا ٱسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا۟ سُبْحَٰنَ ٱلَّذِى سَخَّرَ لَنَا هَٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ", tafsir: `أي تركبوا باستواء بلا صعوبة التمايل والانحراف ( عَلى ظُهُورِهِ ثُمَّ تَذْكُرُوا نِعْمَةَ رَبِّكُمْ إِذَا اسْتَوَيْتُمْ عَلَيْهِ وَتَقُولُوا سُبْحانَ الَّذِي سَخَّرَ لَنا هذا وَما كُنَّا لَهُ مُقْرِنِينَ (13) وَإِنَّا إِلى رَبِّنا لَمُنْقَلِبُونَ (14) وَجَعَلُوا لَهُ مِنْ عِبادِهِ جُزْ ءاً إِنَّ الْإِنْسانَ لَكَفُورٌ ظُهُورِهِ ) أي ظهور ما جعل لكم من الفلك والأنعام ، ويسمى محل الركوب ظهرا ، باعتبار باطن السفينة والحيوان ، الذي هو داخل فيهما لا يمكن ولوجه أو الاستقرار فيه ( ثُمَّ تَذْكُرُوا ) أي تتذكروا ويأتي إلى ذهنكم ( نِعْمَةَ رَبِّكُمْ ) التي أنعم عليكم ( إِذَا اسْتَوَيْتُمْ عَلَيْهِ ) فتشكروه على تلك النعمة ( وَتَقُولُوا ) في ذكركم ( سُبْحانَ الَّذِي سَخَّرَ لَنا هذا ) أي أنزهه عن المثل والشريك والقبائح ، « هذا » يعني المركب سفينة كانت أم حيوانا ( وَما كُنَّا لَهُ ) أي لهذا المركب ( مُقْرِنِينَ ) أي مطيقين مقارين له ، فلو لا تسخير الله إياه لنا ، لم نتمكن من ركوبه ، فإن الإقران الإطاقة يقال أقرنت لهذا البعير أي أطقته.` },
            { text: "وَإِنَّآ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ", tafsir: `أي راجعون ، من انقلب ، بمعنى تغيّر حاله من حال إلى حال ، وهذا من باب تذكر الجنازة وسفر الآخرة ، من المركب وسفر الدنيا ـ وذلك من تتمة الدعاء الذي يقال عند ركوب المركب ـ .` },
            { text: "وَجَعَلُوا۟ لَهُۥ مِنْ عِبَادِهِۦ جُزْءًا إِنَّ ٱلْإِنسَٰنَ لَكَفُورٌ مُّبِينٌ", tafsir: `بعد هذه الآيات الكونية ( جَعَلُوا ) أي جعل الكفار ( لَهُ ) تعالى ( مِنْ عِبادِهِ ) وهم الملائكة والمسيح وعزيز ( جُزْءاً ) فقالوا إنهم أولاد الله ، فإن الولد جزء من الوالد ، لأنه خلق من دمه السائل في عروقه ( إِنَّ الْإِنْسانَ لَكَفُورٌ ) أي كثير الكفر ، فيكفر بالله تعالى في كل أمر. مُبِينٌ (15) أَمِ اتَّخَذَ مِمَّا يَخْلُقُ بَناتٍ وَأَصْفاكُمْ بِالْبَنِينَ (16) وَإِذا بُشِّرَ أَحَدُهُمْ بِما ضَرَبَ لِلرَّحْمنِ مَثَلاً ظَلَّ وَجْهُهُ مُسْوَدًّا وَهُوَ كَظِيمٌ (17) في ذاته ، في صفاته ، في توحيده في الرسالة ، في المعاد ( مُبِينٌ ) أي بيّن الكفر ظاهره. [17] ثم إن الكفار قالوا : الملائكة بنات الله فيأتي السياق لاستنكار قولهم هذا ، بالإضافة إلى استنكار أصل اتخاذه ـ سبحانه ـ ولدا ( أَمِ اتَّخَذَ ) أي هل اتخذ الله سبحانه ( مِمَّا يَخْلُقُ ) من صنوف الخلق ( بَناتٍ ) بأن جعل الملائكة بناتا له ( وَأَصْفاكُمْ ) أي أخلصكم ( بِالْبَنِينَ ) ؟ فلو كانت البنت مكروهة ـ كما في عرفكم ـ كيف تنسبون المكروه إليه ، وتقولون إنا مختصون بالذكور ؟ وهل هذا إلا تنزيل لقدر الله دون مرتبتكم.` },
            { text: "أَمِ ٱتَّخَذَ مِمَّا يَخْلُقُ بَنَاتٍ وَأَصْفَىٰكُم بِٱلْبَنِينَ", tafsir: `` },
            { text: "وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحْمَٰنِ مَثَلًا ظَلَّ وَجْهُهُۥ مُسْوَدًّا وَهُوَ كَظِيمٌ", tafsir: `أي أحد هؤلاء الكفار الذين قالوا إن الملائكة بنات الله ( بِما ضَرَبَ لِلرَّحْمنِ مَثَلاً ) أي بما جعل شبها لله ، فإن ولد كل شيء شبهه ونظيره ، والمراد إذا بشر أحدهم بأن ولدت زوجته بنتا له ( ظَلَّ وَجْهُهُ مُسْوَدًّا ) أي انقلب وجهه إلى السواد لكثرة الغم الذي يصيبه من هذه البشارة ، فإن الإنسان إذا اغتاظ ، توجه الدم إلى وجهه ، وحيث إن الدم يضرب إلى السواد يظهر من تراكمه لون السواد ، ولعل التعبير ب « ظل » لبيان دوام الاسوداد في وجهه مدة أيام ، لكثرة الحنق والغيظ ( وَهُوَ كَظِيمٌ ) أي مملوء غضبا ، كاظما نفسه ، لئلا يبدو منه ما ينافي شأنه. أَ وَمَنْ يُنَشَّؤُا فِي الْحِلْيَةِ وَهُوَ فِي الْخِصامِ غَيْرُ مُبِينٍ (18) وَجَعَلُوا الْمَلائِكَةَ الَّذِينَ هُمْ عِبادُ الرَّحْمنِ إِناثاً أَ شَهِدُوا خَلْقَهُمْ سَتُكْتَبُ شَهادَتُهُمْ وَيُسْئَلُونَ (19) [19] فكيف يجعل هؤلاء الكفار البنت التي يكرهونها بهذا النحو من الكره لله سبحانه ؟ ( أَوَ ) الهمزة للاستفهام والواو للعطف أي هل هؤلاء الكفار يجعلون لله ( مَنْ يُنَشَّؤُا فِي الْحِلْيَةِ ) أي يكبر ويتربى في الزينة ، وهي البنت فإنها تزين بالملابس والذهب والفضة من صغرها حتى تكبر ( وَهُوَ فِي الْخِصامِ ) أي في المخاصمة والاحتجاج ( غَيْرُ مُبِينٍ ) غير متمكن من إظهار حجتها ودليلها ، فإن المرأة حيث يغلب عليها جانب العاطفة لا تتمكن أن تقاوم الرجل الذي غلب عليه جانب العقل والاتزان ، وإنما جيء بالضمائر مذكرا باعتبار « من » وقد جاز في « من » و « ما » مراعاة اللفظ والمعنى ، والحاصل أنه كيف يجعل هؤلاء لله البنات الناعمة جسدا ، العاجزة حجة ، ويجعلون لأنفسهم البنين العاملين الأقوياء في الحجاج ، وهل هذا إلا انتخاب الشيء الحقير ـ بنظرهم ـ لله تعالى ، واختيار الرفيع لأنفسهم ؟ [20] ثم صرح سبحانه بذلك بقوله ( وَجَعَلُوا ) أي هؤلاء الكفار ( الْمَلائِكَةَ الَّذِينَ هُمْ عِبادُ الرَّحْمنِ ) كسائر العبيد ( إِناثاً ) بأن زعموا أنهم بنات الله ( أَ شَهِدُوا خَلْقَهُمْ ) أي هل حضر هؤلاء الكفار خلق الملائكة حتى رأوا بأنهم إناث ؟ ( سَتُكْتَبُ شَهادَتُهُمْ ) بهذا الكذب الشائن ، ولعل الإتيان ب « السين » لما ورد من تأخير كتابة العصيان مدة ، رجاء أن يتوب الإنسان ، فلا تكتب السيئة في ديوانه ( وَيُسْئَلُونَ ) عن هذه الشهادة يوم القيامة من أين قالوها ؟ وَقالُوا لَوْ شاءَ الرَّحْمنُ ما عَبَدْناهُمْ ما لَهُمْ بِذلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلاَّ يَخْرُصُونَ (20) أَمْ آتَيْناهُمْ كِتاباً مِنْ قَبْلِهِ فَهُمْ بِهِ مُسْتَمْسِكُونَ (21) بَلْ قالُوا إِنَّا وَجَدْنا آباءَنا عَلى أُمَّةٍ وَإِنَّا عَلى آثارِهِمْ مُهْتَدُونَ (22) وَكَذلِكَ ما أَرْسَلْنا مِنْ قَبْلِكَ [21] وقد كان الكفار يعبدون الملائكة ( وَقالُوا لَوْ شاءَ الرَّحْمنُ ما عَبَدْناهُمْ ) بأن يمنعنا عن عبادتهم ، وقالوا ذلك في جواب المؤمنين الذين اعترضوا عليهم وكيف تعبدون الملائكة ؟ ( ما لَهُمْ بِذلِكَ ) بأن الله شاء عبادة الملائكة ( مِنْ عِلْمٍ ) فمن أين لهم أن يثبتوا أن الله شاء عبادتهم للملائكة ؟ ( إِنْ هُمْ ) أي ما هم ( إِلَّا يَخْرُصُونَ ) أي يكذبون في نسبة المشيئة إليه سبحانه.` },
            { text: "أَوَمَن يُنَشَّؤُا۟ فِى ٱلْحِلْيَةِ وَهُوَ فِى ٱلْخِصَامِ غَيْرُ مُبِينٍ", tafsir: `` },
            { text: "وَجَعَلُوا۟ ٱلْمَلَٰٓئِكَةَ ٱلَّذِينَ هُمْ عِبَٰدُ ٱلرَّحْمَٰنِ إِنَٰثًا أَشَهِدُوا۟ خَلْقَهُمْ سَتُكْتَبُ شَهَٰدَتُهُمْ وَيُسْـَٔلُونَ", tafsir: `` },
            { text: "وَقَالُوا۟ لَوْ شَآءَ ٱلرَّحْمَٰنُ مَا عَبَدْنَٰهُم مَّا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا يَخْرُصُونَ", tafsir: `` },
            { text: "أَمْ ءَاتَيْنَٰهُمْ كِتَٰبًا مِّن قَبْلِهِۦ فَهُم بِهِۦ مُسْتَمْسِكُونَ", tafsir: `أي هل أعطينا وأرسلنا إلى هؤلاء عبّاد الملائكة ( كِتاباً ) فيه أن اعبدوهم ـ بأن لم يعلموا المشيئة عقلا وإنما علموها نقلا ـ ( مِنْ قَبْلِهِ ) أي من قبل هذا القرآن الناهي لهم عن ذلك ( فَهُمْ بِهِ ) أي بذلك الكتاب ( مُسْتَمْسِكُونَ ) متمسكون آخذون به تبريرا لعبادتهم للملائكة ؟ [23] كلا ! لا علم لهم ولا كتاب ( بَلْ قالُوا ) لتبرير موقفهم ( إِنَّا وَجَدْنا آباءَنا عَلى أُمَّةٍ ) أي على طريقة هي عبادة الملائكة ( وَإِنَّا عَلى آثارِهِمْ ) وما بقي من تقاليدهم وعاداتهم ( مُهْتَدُونَ ) فالأمر لا يخرج عن تقليد صرف. [24] وليس التقليد للآباء في الضلال والانحراف خاصا بهؤلاء الكفار بل الكفار السابقون يقولون بمثل هذا القول في مقابل الأنبياء ( وَكَذلِكَ ) أي كحال هؤلاء ( ما أَرْسَلْنا مِنْ قَبْلِكَ ) يا رسول الله فِي قَرْيَةٍ مِنْ نَذِيرٍ إِلاَّ قالَ مُتْرَفُوها إِنَّا وَجَدْنا آباءَنا عَلى أُمَّةٍ وَإِنَّا عَلى آثارِهِمْ مُقْتَدُونَ (23) قالَ أَ وَلَوْ جِئْتُكُمْ بِأَهْدى مِمَّا وَجَدْتُمْ عَلَيْهِ آباءَكُمْ قالُوا إِنَّا بِما أُرْسِلْتُمْ بِهِ كافِرُونَ (24) فَانْتَقَمْنا مِنْهُمْ فَانْظُرْ كَيْفَ كانَ عاقِبَةُ الْمُكَذِّبِينَ (25) ( فِي قَرْيَةٍ ) من القرى ، والمراد بها المدينة ( مِنْ نَذِيرٍ ) أي رسول ينذرهم من الكفر والمعاصي ( إِلَّا قالَ مُتْرَفُوها ) أي المتنعمون فيها ، من أترف بمعنى تنعم ، والمراد به الرؤساء والكبراء ، لأنهم دائما يقابلون المصلحين بالإنكار والتخاصم ( إِنَّا وَجَدْنا آباءَنا عَلى أُمَّةٍ ) أي على طريقة وملة ( وَإِنَّا عَلى آثارِهِمْ مُقْتَدُونَ ) نقتدي بهم ، فلا نخالفهم في الطريقة باتباعكم أيها الأنبياء ، وذلك لأن في اتباعهم إبقاء لكيانهم ، بالإضافة إلى أن الألفة توجب تزين الأليف في النظر دون الجديد.` },
            { text: "بَلْ قَالُوٓا۟ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّهْتَدُونَ", tafsir: `` },
            { text: "وَكَذَٰلِكَ مَآ أَرْسَلْنَا مِن قَبْلِكَ فِى قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَآ إِنَّا وَجَدْنَآ ءَابَآءَنَا عَلَىٰٓ أُمَّةٍ وَإِنَّا عَلَىٰٓ ءَاثَٰرِهِم مُّقْتَدُونَ", tafsir: `` },
            { text: "قَٰلَ أَوَلَوْ جِئْتُكُم بِأَهْدَىٰ مِمَّا وَجَدتُّمْ عَلَيْهِ ءَابَآءَكُمْ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلْتُم بِهِۦ كَٰفِرُونَ", tafsir: `يا رسول الله لهم ( أَ ) تبقون على طريقة آبائكم ( وَلَوْ جِئْتُكُمْ بِأَهْدى مِمَّا وَجَدْتُمْ عَلَيْهِ آباءَكُمْ ) ؟ يعني لو كان ما أدعوكم إليه أكثر رشدا وهداية من طريقة الآباء ؟ ( قالُوا ) في الجواب ( إِنَّا بِما أُرْسِلْتُمْ بِهِ ) من الدين والشريعة ( كافِرُونَ ) سواء كان أهدى أم غيره.` },
            { text: "فَٱنتَقَمْنَا مِنْهُمْ فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُكَذِّبِينَ", tafsir: `أي من أولئك الذين تمردوا على طاعة الأنبياء عليه‌السلام وتمسكوا بالتقاليد البالية ( فَانْظُرْ ) يا رسول الله ، أو أيها الناظر ( كَيْفَ كانَ عاقِبَةُ الْمُكَذِّبِينَ ) للأنبياء ؟ وفي هذا تهديد لكفار مكة إن لم يؤمنوا كانت عاقبتهم كعاقبة أولئك ، والمراد بالنظر : العلم والتفكير في أمرهم. وَإِذْ قالَ إِبْراهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِي بَراءٌ مِمَّا تَعْبُدُونَ (26) إِلاَّ الَّذِي فَطَرَنِي فَإِنَّهُ سَيَهْدِينِ (27) وَجَعَلَها كَلِمَةً باقِيَةً فِي عَقِبِهِ [27] ثم يأتي السياق لنقل قطعة من قصة إبراهيم عليه‌السلام لشباهتها لقصة محمد صلى‌الله‌عليه‌وآله‌وسلم في أن قومه كانوا يعبدون الأصنام فأظهر التبرؤ منهم ( وَ ) اذكر يا رسول الله ( إِذْ قالَ إِبْراهِيمُ لِأَبِيهِ ) آزر ، وكان عمه ، وإنما اسم أبيه « تارخ » وأطلق عليه لفظ « الأب » احتراما فإن الناس يسمون العم « أبا » والخالة « أما » كما في قصة يوسف عليه‌السلام « ورفع أبويه » على ما ذكره جماعة ، من أن المرأة كانت خالته لا أمه ( وَ ) كما قال لأبيه قال ل ( قَوْمِهِ ) حين كانوا يعبدون الأصنام والكواكب ( إِنَّنِي بَراءٌ ) مصدر « برء » يطلق على المفرد والتثنية والجمع مذكرا ومؤنثا بلفظ واحد ، فهو من قبيل « زيد عدل » وإلا فالأصل « ذو براء » ( مِمَّا تَعْبُدُونَ ) من الأصنام. [28] وحيث إن العام شامل حتى الله سبحانه استثنى بقوله ( إِلَّا الَّذِي فَطَرَنِي ) أي خلقني وأوجدني من العدم ( فَإِنَّهُ سَيَهْدِينِ ) أصله سيهديني حذف ضمير المتكلم تخفيفا وتنسيقا ، وحيث إن الهداية شيء يحتاج إليها الإنسان في كل خطوة من خطوات الحياة ، صح الإتيان بالفعل المستقبل ، ولا ينافي ذلك وجودها في الإنسان سابقا ، ومن ذلك ( اهْدِنَا الصِّراطَ الْمُسْتَقِيمَ ) .` },
            { text: "وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ وَقَوْمِهِۦٓ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ", tafsir: `` },
            { text: "إِلَّا ٱلَّذِى فَطَرَنِى فَإِنَّهُۥ سَيَهْدِينِ", tafsir: `` },
            { text: "وَجَعَلَهَا كَلِمَةًۢ بَاقِيَةً فِى عَقِبِهِۦ لَعَلَّهُمْ يَرْجِعُونَ", tafsir: `أي جعل إبراهيم كلمة التوحيد ـ المستفادة من قوله ( إِلَّا الَّذِي فَطَرَنِي ) ـ ( كَلِمَةً باقِيَةً فِي عَقِبِهِ ) أي في نسله وذريته بأن وصاهم بالتزامه والتمسك بها ، كما قال سبحانه ( وَوَصَّى بِها إِبْراهِيمُ بَنِيهِ لَعَلَّهُمْ يَرْجِعُونَ (28) بَلْ مَتَّعْتُ هؤُلاءِ وَآباءَهُمْ حَتَّى جاءَهُمُ الْحَقُّ وَرَسُولٌ مُبِينٌ (29) وَلَمَّا جاءَهُمُ الْحَقُّ قالُوا هذا سِحْرٌ وَإِنَّا بِهِ كافِرُونَ (30) وَيَعْقُوبُ يا بَنِيَّ إِنَّ اللهَ اصْطَفى لَكُمُ الدِّينَ فَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ) (1) ( لَعَلَّهُمْ يَرْجِعُونَ ) كلما انحرفوا عن الطريق ، بأن يتذكروا الوصية فيرجعوا إلى التوحيد فإن الإنسان ـ حسب المحيط ـ ينحرف فإذا تذكر وصية جده رجع وتاب.` },
            { text: "بَلْ مَتَّعْتُ هَٰٓؤُلَآءِ وَءَابَآءَهُمْ حَتَّىٰ جَآءَهُمُ ٱلْحَقُّ وَرَسُولٌ مُّبِينٌ", tafsir: `لندع حديث إبراهيم إلى أحوال هؤلاء الكفار المعاصرين للرسول ، الذين جاءهم الحق عيانا فقالوا إنه سحر ـ فإنّا لم نكتف بالنسبة إليهم بكلمة إبراهيم في إرشادهم ، بل أرسلنا إليهم رسولا آخر ، ومع ذلك انحرفوا ـ ( مَتَّعْتُ هؤُلاءِ ) أي أنعمت عليهم بالصحة والنعمة وطول العمر ( وَآباءَهُمْ ) إذ كل جيل يلاقي الجيل السابق ( حَتَّى جاءَهُمُ الْحَقُ ) وهو القرآن أو الشريعة ( وَرَسُولٌ مُبِينٌ ) أي ظاهر مبيّن للنهج ، وهو محمد صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "وَلَمَّا جَآءَهُمُ ٱلْحَقُّ قَالُوا۟ هَٰذَا سِحْرٌ وَإِنَّا بِهِۦ كَٰفِرُونَ", tafsir: `أي القرآن أو الشريعة أو الرسول ( قالُوا هذا سِحْرٌ ) ظاهر الآية يناسب كون المراد بالحق القرآن لأن غيره يحتاج إلى التأويل ( وَإِنَّا بِهِ كافِرُونَ ) فليس من عند الله تعالى ، وإنما الذي جاء به ساحر يريد السيطرة والاستعلاء بسحره ، وقد بين في هذه الآيات مختلف صنوف النعم والإرشاد على هؤلاء : تمتيعهم لأنفسهم ، وإبقاء آبائهم ، ووصية إبراهيم عليه‌السلام ، ومجيء الرسول ، ( 1) البقرة : 133. وَقالُوا لَوْ لا نُزِّلَ هذَا الْقُرْآنُ عَلى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ (31) ومع ذلك لم يؤمنوا.` },
            { text: "وَقَالُوا۟ لَوْلَا نُزِّلَ هَٰذَا ٱلْقُرْءَانُ عَلَىٰ رَجُلٍ مِّنَ ٱلْقَرْيَتَيْنِ عَظِيمٍ", tafsir: `أي هلا ( نُزِّلَ هذَا الْقُرْآنُ عَلى رَجُلٍ مِنَ الْقَرْيَتَيْنِ ) أي رجل من هذه القرية أو رجل من تلك ( عَظِيمٍ ) ؟ صفة رجل ، أي رجل عظيم من مكة أو الطائف. في تفسير الإمام أن رسول الله صلى‌الله‌عليه‌وآله‌وسلم كان قاعدا ذات يوم بفناء الكعبة إذ اجتمع جماعة من رؤساء قريش « إلى أن قال » : قال له عبد الله بن أبي أمية : لو أراد الله أن يبعث لنا رسولا لبعث أجلّ من في ما بيننا مالا وأحسنه حالا ؟ فهلا نزل هذا القرآن الذي تزعم أن الله أنزله عليك وأبعثك به رسولا ، على رجل من القريتين عظيم ، إما الوليد بن المغيرة بمكة وإما عروة بن مسعود الثقفي بالطائف ؟ فقال لهم رسول الله صلى‌الله‌عليه‌وآله‌وسلم : وأما قولك لو لا نزل هذا القرآن على رجل من القريتين عظيم ، فإن الله ليس يستعظم مال الدنيا كما تستعظمه أنت ولا خطر له عنده كما له عندك ، بل لو كانت الدنيا عنده تعدل جناح بعوضة ، لما سقى كافرا به مخالفا له شربة ماء ، وليس قسمة الله إليك بل الله القاسم للرحمات والفاعل لما يشاء في عبيده وإمائه ، وليس هو عزوجل ممن يخاف أحدا كما تخافه أنت لماله وحاله ، فعرفته بالنبوة لذلك ، ولا ممن يطمع في أحد في ماله أو في حاله كما تطمع فيخصه بالنبوة لذلك ، ولا ممن يحب أحدا محبة الهوى كما تحب أنت فتقدم من لا يستحق التقديم وإنما معاملته بالعدل ، فلا يؤثر لأفضل مراتب الدين وجلاله إلا الأفضل في طاعته والأجدّ في خدمته وكذلك لا يؤخر في مراتب الدين والجلالة إلا أَ هُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنا بَيْنَهُمْ مَعِيشَتَهُمْ فِي الْحَياةِ الدُّنْيا وَرَفَعْنا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجاتٍ أشدهم تبطرا عن طاعته ، وإذا كانت هذه صفته لم ينظر إلى مال ولا إلى حال بل هذا المال والحال من تفضله وليس لأحد من عباده عليه ضربة لازب ، فلا يقال له إذا تفضلت بالمال على عبد فلا بد أن تتفضل عليه بالنبوة أيضا ؟ لأنه ليس لأحد إكراهه على خلاف مراده ولا إلزامه تفضلا ، لأنه تفضل قبله بنعمه ، ألا ترى يا عبد الله كيف أغنى واحدا وقبّح صورته ؟ وكيف حسّن صورة واحد وأفقره ؟ وكيف شرّف واحدا وأفقره ؟ وكيف أغنى واحدا ووضعه ؟ ثم ليس لهذا الغني أن يقول هلّا أضيف إلى يسري جمال فلان ؟ ولا للجميل أن يقول هلّا أضيف إلى جمالي مال فلان ؟ ولا للشريف أن يقول هلا أضيف إلى شرفي مال فلان ؟ ولا للوضيع أن يقول هلا أضيف إلى صفتي شرف فلان ؟ ولكن الحكم لله يقسم كيف يشاء ويفعل كما يشاء وهو حكيم في أفعاله ، محمود في أعماله (1) . [33] وأجابهم الله تعالى بقوله ( أَ هُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ ) أي النبوة ، أي هل تقسيم النبوات بيد هؤلاء حتى ينتخبوا فلانا للنبوة دون محمد صلى‌الله‌عليه‌وآله‌وسلم ؟ كلا ! فإن الله سبحانه لم يجعل بأيديهم قسمة أرزاقهم فكيف يعطي مقاليد النبوة بأيديهم ؟ ( نَحْنُ قَسَمْنا بَيْنَهُمْ مَعِيشَتَهُمْ ) وهو ما يستعيشون به ( فِي الْحَياةِ الدُّنْيا ) أي في هذه الحياة القريبة على حسب المصلحة والحكمة ( وَرَفَعْنا بَعْضَهُمْ ) أي بعض هؤلاء ( فَوْقَ بَعْضٍ ) رزقا وجاها وقوّة وفي سائر الشؤون ( دَرَجاتٍ ) فلم نفوض ( 1) تفسير الإمام العسكري : ص 506. لِيَتَّخِذَ بَعْضُهُمْ بَعْضاً سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِمَّا يَجْمَعُونَ (32) إليهم أمور نفسهم مع عدم أهميتها فكيف نفوض إليهم أعظم الأمور وهي النبوة ؟ ( لِيَتَّخِذَ ) أي إنما جعلنا بعضهم فوق بعض لأن يستخدم ( بَعْضُهُمْ بَعْضاً سُخْرِيًّا ) وهو الذي يسخّر في الحوائج ويستخدم في المهام ، فإنه بذلك يتم نظام العالم ويستقيم ، إذ لو كان الكل سادة من كان يعمل ؟ ولو كان الكل أقوياء كثر التنازع والفناء ، ولو كان الكل فقراء من كان يجلب الطعام والحوائج ليبيعها في وقتها عند الحاجة ؟ ولو كان الكل أغنياء من كان ينكس ويطبخ ويخبز ويدير الأمور الصغيرة كالفلاحة والبناء وما أشبه ؟ وقد أراد بعض السخفاء ك « ماركس » اليهودي وأضرابه ، أن يهدموا نظام الغنى والفقر ، فلم يتمكنوا وغاية ما صنعوا أنهم أضافوا إلى الأغنياء مع غنائهم السلاح ، فجعلوا الناس فقراء ، والأغنياء بيدهم الحكم ، لكي يتمكنوا من امتصاص دماء الفقراء بالمال والقوة معا ، بعد ما كان كل من هذين العاملين للاستعلاء والترفع في فئة ، فكان الفقراء يجدون مناصا من طغيان كلّ بالالتجاء إلى الآخر ، ولقد كان نظامهم مغلوطا إلى أبعد الحدود ، ولذا نرى اليوم ـ وبعد نصف قرن من قيام دولتهم في الشرق ـ يستجدون الحنطة والرزق من بلاد الرأسماليين كل عام .. . ولقد منع الإسلام عن كل من الرأسمالية بالمعنى الغربي والشيوعية والاشتراكية ، وإنما نظّم الأمور خير تنظيم ، مما لا مجال هنا لتفصيله (1) ( وَرَحْمَتُ رَبِّكَ ) يا رسول الله ( خَيْرٌ مِمَّا يَجْمَعُونَ ) من الأموال فكيف يمكن أن ( 1) راجع الاقتصاد للشهيد السيد حسن الشيرازي. وَلَوْ لا أَنْ يَكُونَ النَّاسُ أُمَّةً واحِدَةً لَجَعَلْنا لِمَنْ يَكْفُرُ بِالرَّحْمنِ لِبُيُوتِهِمْ سُقُفاً مِنْ فِضَّةٍ وَمَعارِجَ عَلَيْها يَظْهَرُونَ (33) وَلِبُيُوتِهِمْ أَبْواباً وَسُرُراً عَلَيْها يَتَّكِؤُنَ (34) وَزُخْرُفاً يترك الله الخير ـ بيدهم ـ والحال أنه لم يترك ما يجمعون بأيديهم ؟ أو المراد أن النبوة خير من الأموال ، فما عندك خير مما عند رجل من القريتين عظيم ، الذين يرون تفضيلهما عليك. [34] إذ قيمة المال والزخرف في نظر الله سبحانه تافه جدا حتى أنه لو لم تكن مخافة انحياز الناس إلى الكفار لأسبل الله على الكفار الأموال والزخارف بكل ألوانها ، فهل هذا المال الذي هكذا شأنه يكون ميزانا لإعطاء النبوة وإرسال الرسول حتى يقول الكفار أنه ( لَوْ لا نُزِّلَ هذَا الْقُرْآنُ عَلى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ ) ؟ ( وَلَوْ لا أَنْ يَكُونَ النَّاسُ أُمَّةً واحِدَةً ) أي لو لا مخافة أن يجتمع الناس على الكفر فيكونوا جميعا كفارا ، حيث يرون ان الدنيا للكفار والمؤمنين صفر اليد منها ( لَجَعَلْنا لِمَنْ يَكْفُرُ بِالرَّحْمنِ لِبُيُوتِهِمْ سُقُفاً ) جمع سقف ( مِنْ فِضَّةٍ ) بأن أكثرنا عليهم من الفضة حتى يصنعوا السقوف منها ( وَمَعارِجَ ) من فضة ، وهو جمع معراج أي السلم ، أي كانت سلالم بيوتهم فضة ( عَلَيْها يَظْهَرُونَ ) أي على تلك المعارج يصعدون ويعلون ، فإن الصاعد يظهر بما لا يظهر الذي في البيت.` },
            { text: "أَهُمْ يَقْسِمُونَ رَحْمَتَ رَبِّكَ نَحْنُ قَسَمْنَا بَيْنَهُم مَّعِيشَتَهُمْ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَرَفَعْنَا بَعْضَهُمْ فَوْقَ بَعْضٍ دَرَجَٰتٍ لِّيَتَّخِذَ بَعْضُهُم بَعْضًا سُخْرِيًّا وَرَحْمَتُ رَبِّكَ خَيْرٌ مِّمَّا يَجْمَعُونَ", tafsir: `` },
            { text: "وَلَوْلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً لَّجَعَلْنَا لِمَن يَكْفُرُ بِٱلرَّحْمَٰنِ لِبُيُوتِهِمْ سُقُفًا مِّن فِضَّةٍ وَمَعَارِجَ عَلَيْهَا يَظْهَرُونَ", tafsir: `` },
            { text: "وَلِبُيُوتِهِمْ أَبْوَٰبًا وَسُرُرًا عَلَيْهَا يَتَّكِـُٔونَ", tafsir: `من فضة ( وَ ) لأنفسهم ( سُرُراً ) جمع سرير ، من فضة ( عَلَيْها يَتَّكِؤُنَ ) عند الجلوس.` },
            { text: "وَزُخْرُفًا وَإِن كُلُّ ذَٰلِكَ لَمَّا مَتَٰعُ ٱلْحَيَوٰةِ ٱلدُّنْيَا وَٱلْـَٔاخِرَةُ عِندَ رَبِّكَ لِلْمُتَّقِينَ", tafsir: `أي جعلنا لهم في السقف والمعارج والأبواب والسرر ، وَإِنْ كُلُّ ذلِكَ لَمَّا مَتاعُ الْحَياةِ الدُّنْيا وَالْآخِرَةُ عِنْدَ رَبِّكَ لِلْمُتَّقِينَ (35) وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمنِ نُقَيِّضْ لَهُ شَيْطاناً فَهُوَ لَهُ قَرِينٌ (36) وَإِنَّهُمْ لَيَصُدُّونَهُمْ الزخرف ، وهو الذهب ، والمعنى أغرقناهم في الذهب والفضة حتى يكون كل شيء لهم منهما ( وَإِنْ كُلُّ ذلِكَ ) من الفضة والذهب والدر وسائر أنواع التجمل والزينة ( لَمَّا مَتاعُ الْحَياةِ الدُّنْيا ) « أن » نافية و « لما » بمعنى إلا ، أي ما كل ذلك إلا متاع الحياة الدنيا ، أي الحياة القريبة ، التي يتمتع بها الإنسان في أيام قلائل ( وَالْآخِرَةُ ) التي ( عِنْدَ رَبِّكَ ) قربا شرفيا ، لا مكانيا ( لِلْمُتَّقِينَ ) الذين آمنوا وأطاعوا ، فمن الضروري أن يحصل الإنسان على الآخرة لا على الدنيا الفانية التي لا قيمة لها. [37] وإذ تبين أن لا قيمة للماديات ، فالكافر لا أهمية له بنظره سبحانه وإن كان ذا رئاسة أو مال ، بل إن مستواه المعنوي لمنحط جدا حتى أنه دائم الملازمة للشيطان الذي يغويه ، فهل مثل هذا صالح للنبوة ؟ ( وَمَنْ يَعْشُ ) أي يعرض ويتعامى ( عَنْ ذِكْرِ الرَّحْمنِ ) أصله من « العشو » وهو ضعف البصر ، فكأن الكافر ضعيف البصر ، بالنسبة إلى الشريعة والدين ( نُقَيِّضْ ) أي نرسل ( لَهُ ) لذلك الإنسان ( شَيْطاناً ) يوسوس إليه ويؤذيه ويصده عن الحق ( فَهُوَ ) أي الشيطان ( لَهُ ) لذلك الإنسان ( قَرِينٌ ) أي ملازم ، وذلك لأنه لما أعرض عن الحق خلّى سبحانه بينه وبين الشياطين يفعلون به ما يشاءون ، وهذا معنى « التقييض » .` },
            { text: "وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَٰنِ نُقَيِّضْ لَهُۥ شَيْطَٰنًا فَهُوَ لَهُۥ قَرِينٌ", tafsir: `` },
            { text: "وَإِنَّهُمْ لَيَصُدُّونَهُمْ عَنِ ٱلسَّبِيلِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ", tafsir: `أي الشياطين القرناء مع الكفار ، وإنما جيء بالجمع ، لأن المراد ب « شيطانا » الجنس ، لا الواحد ( لَيَصُدُّونَهُمْ ) أي يمنعون هؤلاء عَنِ السَّبِيلِ وَيَحْسَبُونَ أَنَّهُمْ مُهْتَدُونَ (37) حَتَّى إِذا جاءَنا قالَ يا لَيْتَ بَيْنِي وَبَيْنَكَ بُعْدَ الْمَشْرِقَيْنِ فَبِئْسَ الْقَرِينُ (38) وَلَنْ يَنْفَع َكُمُ الْيَوْمَ إِذْ ظَلَمْتُمْ الكفار ( عَنِ السَّبِيلِ ) طريق الله سبحانه بالوسوسة وإلقاء الشبهة ( وَيَحْسَبُونَ ) هؤلاء الكفار ( أَنَّهُمْ مُهْتَدُونَ ) أي أنهم في سبيل الحق ، حيث زين لهم كفرهم وعصيانهم ، حتى زعموا أنهم على هدى ، وأن المؤمنين على ضلالة ، كما قال سبحانه ( وَإِذا رَأَوْهُمْ قالُوا إِنَّ هؤُلاءِ لَضالُّونَ ) (1) . [39] ويبقى الشيطان مع هذا الكافر ( حَتَّى ) يوم القيامة ف ( إِذا جاءَنا ) أي حضر للحساب والجزاء في يوم المحشر وظهر له جزاءه السيء ( قالَ ) مخاطبا للشيطان الذي كان يغويه في دار الدنيا ، ويمنعه عن الاهتداء ( يا لَيْتَ بَيْنِي وَبَيْنَكَ ) أيها الشيطان ، بعدا مثل ( بُعْدَ الْمَشْرِقَيْنِ ) أي المشرق والمغرب ، وغلب المشرق ، لقاعدة تغليب الأشرف ، أو الأقرب إلى القصد ، ولذا يقال للشمس والقمر « شمسان » و « قمران » ( فَبِئْسَ الْقَرِينُ ) كنت لي في الدنيا حيث أوصلتني إلى هذه الحالة ، وهذا العقاب الأليم. [40] وإذا كان المقام محل توهم أن يخفف الشيطان المقارن للكافر ـ في الآخرة ـ بعض عذابه ، كما هو المعتاد في الدنيا أن يخفف أحد القرينين بعض آلام الآخر ، جاء الخطاب للكافر بقوله ( وَلَنْ يَنْفَعَكُمُ ) أيها الكفار والشياطين القرناء لهم ( الْيَوْمَ ) أي يوم القيامة ( إِذْ ظَلَمْتُمْ ) ( 1) المطففين : 33. أَنَّكُمْ فِي الْعَذابِ مُشْتَرِكُونَ (39) أَ فَأَنْتَ تُسْمِعُ الصُّمَّ أَوْ تَهْدِي الْعُمْيَ وَمَنْ كانَ فِي ضَلالٍ مُبِينٍ (40) فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُمْ مُنْتَقِمُونَ (41) أَوْ نُرِيَنَّكَ الَّذِي وَعَدْناهُمْ أنفسكم في الدنيا بالكفر والعصيان ( أَنَّكُمْ فِي الْعَذابِ مُشْتَرِكُونَ ) هذا فاعل « لن ينفعكم » أي لا يفيدكم اشتراككم في العذاب لتخفيفه عنكم بل لكل عذاب نفسه ، بدون أن يحمل قرينه بعض عذابه. [41] ثم جاء السياق ليسلي النبي صلى‌الله‌عليه‌وآله‌وسلم بالنسبة إلى هؤلاء الكفار الذين لا يسمعون وعظه وإرشاده ببيان أن التقصير ليس منك ، وإنما من الكافر نفسه حيث عاند حتى صار كالأصم الأعمى لا يسمع ولا يبصر ( أَ فَأَنْتَ ) يا رسول الله ، والاستفهام للإنكار ( تُسْمِعُ الصُّمَ ) أي تقدر على إسماع من به صمم في أذنه ، و « صم » جمع أصم ( أَوْ تَهْدِي الْعُمْيَ ) أي تقدر على إرشاد الأعمى بالكلام هو والأصم سواء من لا ينتفع بما يرى هو والأعمى سواء ( وَمَنْ كانَ فِي ضَلالٍ مُبِينٍ ) أي ضلال ظاهر بين ، وهذا في قبال أولئك فإن من ضل قلبه عن الحق وعاند يكون غير قابل للهداية ، فهؤلاء لا ينتفعون بأبصارهم وأسماعهم وقلوبهم. [42] ولا بد أن ننتقم من هؤلاء الكفار سواء انتقمنا في حياتك أو بعد موتك ( فَإِمَّا ) أصله « إن » الشرطية و « ما » الزائدة للتأكيد ( نَذْهَبَنَّ بِكَ ) يا رسول الله ، أي نميتك قبل تعذيب هؤلاء الكفار ( فَإِنَّا مِنْهُمْ مُنْتَقِمُونَ ) بعدك.` },
            { text: "حَتَّىٰٓ إِذَا جَآءَنَا قَالَ يَٰلَيْتَ بَيْنِى وَبَيْنَكَ بُعْدَ ٱلْمَشْرِقَيْنِ فَبِئْسَ ٱلْقَرِينُ", tafsir: `` },
            { text: "وَلَن يَنفَعَكُمُ ٱلْيَوْمَ إِذ ظَّلَمْتُمْ أَنَّكُمْ فِى ٱلْعَذَابِ مُشْتَرِكُونَ", tafsir: `` },
            { text: "أَفَأَنتَ تُسْمِعُ ٱلصُّمَّ أَوْ تَهْدِى ٱلْعُمْىَ وَمَن كَانَ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `` },
            { text: "فَإِمَّا نَذْهَبَنَّ بِكَ فَإِنَّا مِنْهُم مُّنتَقِمُونَ", tafsir: `` },
            { text: "أَوْ نُرِيَنَّكَ ٱلَّذِى وَعَدْنَٰهُمْ فَإِنَّا عَلَيْهِم مُّقْتَدِرُونَ", tafsir: `إن أردنا أن ( نُرِيَنَّكَ الَّذِي وَعَدْناهُمْ ) من العذاب والنكال ، بأن فَإِنَّا عَلَيْهِمْ مُقْتَدِرُونَ (42) فَاسْتَمْسِكْ بِالَّذِي أُوحِيَ إِلَيْكَ إِنَّكَ عَلى صِراطٍ مُسْتَقِيمٍ (43) وَإِنَّهُ لَذِكْرٌ لَكَ وَلِقَوْمِكَ وَسَوْفَ تُسْئَلُونَ (44) وَسْئَلْ مَنْ أَرْسَلْنا مِنْ قَبْلِكَ مِنْ رُسُلِنا نعذبهم في حياتك ( فَإِنَّا عَلَيْهِمْ مُقْتَدِرُونَ ) فإنهم لا يتمكنون من الفرار أو الانتصار علينا. [44] فما عليك يا رسول الله أمر هؤلاء ، وإنما أنت منتدب إلى البلاغ باستمرار سواء قبل الناس أم لم يقبلوا ( فَاسْتَمْسِكْ ) يا رسول الله أي تمسك بشدة ( بِالَّذِي أُوحِيَ إِلَيْكَ ) من القرآن والشريعة ( إِنَّكَ عَلى صِراطٍ مُسْتَقِيمٍ ) يوصل إلى السعادة بأقرب الخطوط.` },
            { text: "فَٱسْتَمْسِكْ بِٱلَّذِىٓ أُوحِىَ إِلَيْكَ إِنَّكَ عَلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `` },
            { text: "وَإِنَّهُۥ لَذِكْرٌ لَّكَ وَلِقَوْمِكَ وَسَوْفَ تُسْـَٔلُونَ", tafsir: `أي الذي أوحي إليك من القرآن والشريعة ( لَذِكْرٌ لَكَ ) أي مذكر لك ما أودع في فطرتك من الأصول ( وَلِقَوْمِكَ ) أي العرب ، أو من بعثت إليهم من جميع البشر ، ولذا كان صلى‌الله‌عليه‌وآله‌وسلم يقول « اللهمّ اهد قومي فإنهم لا يعلمون » (1) حين كان يؤذيه الكفار ولو كانوا غير قومه ، ويحتمل أن يكون المراد بالذكر « الشرف » أي أنه شرف باق لكم ( وَسَوْفَ تُسْئَلُونَ ) عنه يوم القيامة هل عملتم بما في هذا الذكر أم لا ؟.` },
            { text: "وَسْـَٔلْ مَنْ أَرْسَلْنَا مِن قَبْلِكَ مِن رُّسُلِنَآ أَجَعَلْنَا مِن دُونِ ٱلرَّحْمَٰنِ ءَالِهَةً يُعْبَدُونَ", tafsir: `يا رسول الله ( مَنْ أَرْسَلْنا مِنْ قَبْلِكَ مِنْ رُسُلِنا ) كنوح وإبراهيم وموسى وعيسى وغيرهم عليه‌السلام ، وهذا مجاز يراد به الفحص عن مقالاتهم ، كما يقال سل الأطباء عن هذا المرض ، أي راجع كتبهم ( 1) بحار الأنوار : ج 20 ص 117. أَ جَعَلْنا مِنْ دُونِ الرَّحْمنِ آلِهَةً يُعْبَدُونَ (45) وَلَقَدْ أَرْسَلْنا مُوسى بِآياتِنا إِلى فِرْعَوْنَ وَمَلائِهِ فَقالَ إِنِّي رَسُولُ رَبِّ الْعالَمِينَ (46) فَلَمَّا جاءَهُمْ بِآياتِنا إِذا هُمْ مِنْها يَضْحَكُونَ (47) ( أَ جَعَلْنا مِنْ دُونِ الرَّحْمنِ ) أي سواه ( آلِهَةً يُعْبَدُونَ ) ؟ أي هل قررنا عبادة آلهة أخرى ، وهذا الكلام لتقريع أهل الكتاب في المشركين الذين كانوا يزعمون أنهم متبعون للأنبياء ومع ذلك كانوا يشركون بالله زاعمين أن الله أباح لهم الشرك وقالوا : ( لَوْ شاءَ اللهُ ما عَبَدْنا مِنْ دُونِهِ مِنْ شَيْءٍ نَحْنُ وَلا آباؤُنا ) (1) وقالوا ( هؤُلاءِ شُفَعاؤُنا عِنْدَ اللهِ قُلْ أَ تُنَبِّئُونَ ) (2) وهذا لا ينافي ما روي من أن الأنبياء جمعوا للرسول صلى‌الله‌عليه‌وآله‌وسلم ليلة المعراج ، وخوطب بهذا الخطاب هناك. [47] ثم يأتي السياق ليذكر نتفا من قصة موسى عليه‌السلام ، تسلية للرسول ، حيث قابله القبط بما قابل المشركون الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلَقَدْ أَرْسَلْنا مُوسى بِآياتِنا ) أي مع آياتنا ، وهي المعجزات الباهرة ، من عصا ، ويد ، وجراد ، ودم ، وغيرها ( إِلى فِرْعَوْنَ وَمَلَائِهِ ) أي الأشراف من قومه ، وتسمى الأشراف ملأ لأنهم يملئون الصدور رهبة والعيون هيبة ، وذكر الملأ يغني عن ذكر سائر القبط ، لأنهم تابعون دائما ، فلا يحسب حسابهم ( فَقالَ ) موسى لهم ( إِنِّي رَسُولُ رَبِّ الْعالَمِينَ ) إليكم.` },
            { text: "وَلَقَدْ أَرْسَلْنَا مُوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَقَالَ إِنِّى رَسُولُ رَبِّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "فَلَمَّا جَآءَهُم بِـَٔايَٰتِنَآ إِذَا هُم مِّنْهَا يَضْحَكُونَ", tafsir: `موسى عليه‌السلام ( بِآياتِنا ) أي مع المعاجز التي أعطيناها لتثبيت نبوته ( إِذا هُمْ مِنْها يَضْحَكُونَ ) أي يستهزئون بالآيات ، وهذه ( 1) النحل : 36. ( 2) يونس : 19. وَما نُرِيهِمْ مِنْ آيَةٍ إِلاَّ هِيَ أَكْبَرُ مِنْ أُخْتِها وَأَخَذْناهُمْ بِالْعَذابِ لَعَلَّهُمْ يَرْجِعُونَ (48) وَقالُوا يا أَيُّهَا السَّاحِرُ ادْعُ لَنا رَبَّكَ بِما عَهِدَ عِنْدَكَ إِنَّنا لَمُهْتَدُونَ (49) فَلَمَّا كَشَفْنا عَنْهُمُ الْعَذابَ حيلة العاجز يتخذها وسيلة لإخماد صوت خصمه القوي حيث لا يتمكن من إبطال حجته.` },
            { text: "وَمَا نُرِيهِم مِّنْ ءَايَةٍ إِلَّا هِىَ أَكْبَرُ مِنْ أُخْتِهَا وَأَخَذْنَٰهُم بِٱلْعَذَابِ لَعَلَّهُمْ يَرْجِعُونَ", tafsir: `أي ما أريناهم ، وإنما جيء بالمستقبل لأنه حكاية حال ماضية ( مِنْ آيَةٍ ) أي خارقة من الخوارق التسع ( إِلَّا هِيَ أَكْبَرُ مِنْ أُخْتِها ) فما ترادف عليهم كان الثاني أكبر من الأول والثالث أكبر من الثاني وهكذا في الباقي أو انه عبارة عرفية لبيان كبر جميع الآيات ، ولذا يقول القائل لي أولاد واحد منهم أحسن من الآخر ـ يريد وصول كل واحد إلى منتهى درجة الحسن ـ ( وَأَخَذْناهُمْ بِالْعَذابِ ) فقد كانت بعض تلك الآيات عذابا لهم ، كالدم والقمل والضفادع ( لَعَلَّهُمْ يَرْجِعُونَ ) عن كفرهم وضلالهم.` },
            { text: "وَقَالُوا۟ يَٰٓأَيُّهَ ٱلسَّاحِرُ ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهْتَدُونَ", tafsir: `أي قال فرعون وملأه لموسى ، عند ما نزل بهم العذاب ( يا أَيُّهَا السَّاحِرُ ادْعُ لَنا ) أي لأجل رفع عذابنا ( رَبَّكَ بِما عَهِدَ عِنْدَكَ ) فقد عهد الله إلى موسى أنهم إن أرسلوا معك بني إسرائيل بأن أطلقوا سراحهم من السجون والتسخير يكشف العذاب عنهم ، كما سبق في بعض الآيات ، أو أنهم لما ضاق بهم الخناق وعدوا أن يؤمنوا إذا كشف العذاب عنهم ( إِنَّنا لَمُهْتَدُونَ ) إلى الإيمان أو إطلاقهم. [51] وعلى أيّ فقد دعا موسى ربه وكشف الله عنهم العذاب ( فَلَمَّا كَشَفْنا عَنْهُمُ الْعَذابَ ) كأن العذاب ستر عليهم ، فإذا رفع ، كشف عنهم إِذا هُمْ يَنْكُثُونَ (50) وَنادى فِرْعَوْنُ فِي قَوْمِهِ قالَ يا قَوْمِ أَ لَيْسَ لِي مُلْكُ مِصْرَ وَهذِهِ الْأَنْهارُ تَجْرِي مِنْ تَحْتِي أَ فَلا تُبْصِرُونَ (51) أَمْ أَنَا خَيْرٌ مِنْ هذَا الَّذِي هُوَ مَهِينٌ وَلا يَكادُ يُبِينُ (52) فَلَوْ لا أُلْقِيَ عَلَيْهِ أَسْوِرَةٌ ليظهروا من تحته غير معذبين ( إِذا هُمْ يَنْكُثُونَ ) أي ينقضون العهد ويبقون على كفرهم ، أو يبقون بني إسرائيل على إسارهم كالسابق.` },
            { text: "فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلْعَذَابَ إِذَا هُمْ يَنكُثُونَ", tafsir: `` },
            { text: "وَنَادَىٰ فِرْعَوْنُ فِى قَوْمِهِۦ قَالَ يَٰقَوْمِ أَلَيْسَ لِى مُلْكُ مِصْرَ وَهَٰذِهِ ٱلْأَنْهَٰرُ تَجْرِى مِن تَحْتِىٓ أَفَلَا تُبْصِرُونَ", tafsir: `حين رأى أن أمر موسى أخذ في العلو والظهور ، فأراد الحطّ من قدر موسى وإظهار نفسه قويا عظيما لدى أهل مصر ، لئلّا يميلوا إلى موسى فجمعهم وخطبهم ( قالَ يا قَوْمِ أَ لَيْسَ لِي مُلْكُ مِصْرَ ) ؟ على نحو الاستفهام التقريري ، أي أن لي هذا الملك الوسيع ( وَهذِهِ الْأَنْهارُ ) كالنيل ونحوه ( تَجْرِي مِنْ تَحْتِي ) أي من تحت أمري وسلطتي ، فلي أرض وماء ( أَ فَلا تُبْصِرُونَ ) هذا الملك العظيم ؟.` },
            { text: "أَمْ أَنَا۠ خَيْرٌ مِّنْ هَٰذَا ٱلَّذِى هُوَ مَهِينٌ وَلَا يَكَادُ يُبِينُ", tafsir: `تبصرون وتعلمون ( أَنَا خَيْرٌ مِنْ هذَا الَّذِي هُوَ مَهِينٌ ) ؟ يريد موسى عليه‌السلام ، والمراد بالمهين الذليل الحقير ، من هان بمعنى ذل وسهل أمره ( وَلا يَكادُ يُبِينُ ) أي لا يكاد يفصح بكلامه ، فقد كان موسى عليه‌السلام قبل النبوة يعقد لسانه إذا أراد الكلام ، ولذا قال في دعائه ( وَاحْلُلْ عُقْدَةً مِنْ لِسانِي ) وقد استجاب الله دعاءه فكان فصيحا ، لكن فرعون استغل جهل الناس بذلك ، وأنهم كانوا قد عهدوه قبل النبوة غير مفصح ، ولذا خدعهم بأنه بعد باق على حالته السابقة.` },
            { text: "فَلَوْلَآ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ ٱلْمَلَٰٓئِكَةُ مُقْتَرِنِينَ", tafsir: `أي على موسى ( أَسْوِرَةٌ ) جمع سوار وهو الحلية مِنْ ذَهَبٍ أَوْ جاءَ مَعَهُ الْمَلائِكَةُ مُقْتَرِنِينَ (53) فَاسْتَخَفَّ قَوْمَهُ فَأَطاعُوهُ إِنَّهُمْ كانُوا قَوْماً فاسِقِينَ (54) فَلَمَّا آسَفُونا انْتَقَمْنا مِنْهُمْ فَأَغْرَقْناهُمْ أَجْمَعِينَ (55) فَجَعَلْناهُمْ سَلَفاً وَمَثَلاً التي تلبس في اليد بين المرفق والزند ( مِنْ ذَهَبٍ ) ؟ أي إن كان صادقا فلما ذا لا يلقي عليه ربه مقدارا من الذهب يثري ويغني ( أَوْ جاءَ مَعَهُ الْمَلائِكَةُ مُقْتَرِنِينَ ) أي متتابعين يعينونه على أمره ؟ وإذ لا ذهب يبقى ولا ملائكة معه فهو كاذب ، وأي ربط بين النبوة وإلقاء الأسورة ؟ أم أي حاجة إلى نزول الملائكة بعد تلك الآيات ؟ وإنما أراد فرعون خداع الجماهير بهذه التلفيقات الباطلة.` },
            { text: "فَٱسْتَخَفَّ قَوْمَهُۥ فَأَطَاعُوهُ إِنَّهُمْ كَانُوا۟ قَوْمًا فَٰسِقِينَ", tafsir: `فرعون ( قَوْمَهُ ) بأن حسبهم خفيفي العقول يتمكن من إنهاضهم لنصره بمجرد خطاب ومغالطة ، كما هي عادة الطغاة دائما أمام الجماهير ( فَأَطاعُوهُ ) فيما دعاهم إليه من رفض الإسلام واتباع موسى ، والبقاء على الكفر والعصيان ( إِنَّهُمْ كانُوا قَوْماً فاسِقِينَ ) أي خارجين عن طاعة الله تعالى ، ولذا اتبعوا فرعون.` },
            { text: "فَلَمَّآ ءَاسَفُونَا ٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ أَجْمَعِينَ", tafsir: `أي أغضبونا ببقائهم في الكفر والعناد ، والله سبحانه لا يغضب ـ كما يغضب الإنسان ـ بل المراد وصلوا في كفرهم وعصيانهم إلى حد من شأنه أن يغضب ( انْتَقَمْنا مِنْهُمْ ) جزاء كفرهم وإثمهم ( فَأَغْرَقْناهُمْ ) في البحر ( أَجْمَعِينَ ) ولم نبق واحدا منهم سالما.` },
            { text: "فَجَعَلْنَٰهُمْ سَلَفًا وَمَثَلًا لِّلْـَٔاخِرِينَ", tafsir: `أي متقدمين إلى النار وعلى سائر الكفار ( وَمَثَلاً ) لِلْآخِرِينَ (56) وَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً أي عبرة وموعظة يمثل بهم لأجل العظة والتذكير ( لِلْآخِرِينَ ) الذين يجيئون بعدهم. [58] وبمناسبة الحديث عن قصة موسى عليه‌السلام يقدم على ذلك مقدمة و هي ما ذكره بعض المفسرين من أنه لما نزل قوله تعالى ( إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللهِ حَصَبُ جَهَنَّمَ ) (1) فرح بعض المشركين بأنهم وجدوا مأخذا على الرسول ، فجاء ابن الزبعرى وهو القائل : لعبت هاشم بالملك فلا خبر جاء ولا وحي نزل وقال للرسول ألم يعبد المسيح وعزيز والملائكة ؟ فقال الرسول بلى قد عبدوا ، فقال : فكيف يكون هؤلاء « حصب جهنم » كما ذكرت وأنت تثني عليهم ؟ وإذا جعلتهم من أهل النار فنحن نرضى بأن نكون كالمسيح ، فقال له النبي صلى‌الله‌عليه‌وآله‌وسلم : ويلك ! ما أجهلك بلسان قومك ؟ « ما » لما لا يعقل ، فأقحم ابن الزبعرى وارتد خائبا ، وفي قول آخر إن الرسول انتظر الوحي ، فنزل ( إِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِنَّا الْحُسْنى أُولئِكَ عَنْها مُبْعَدُونَ ) (2) وقد أراد الله سبحانه من ( إِنَّكُمْ وَما تَعْبُدُونَ ) (3) الأصنام ، لأن الخطاب موجه إلى المشركين ، فكان قولهم للرسول صلى‌الله‌عليه‌وآله‌وسلم مغالطة وجدلا ، ولذا أوضحت الآية ذلك ، وهناك روايات أخرى لا يهمنا التعرض لها ( وَلَمَّا ضُرِبَ ابْنُ مَرْيَمَ مَثَلاً ) أي لما ضرب ابن الزبعرى المثل بعيسى وأراد أن يجعله مثلا لقوله « وما ( 1) الأنبياء : 99. ( 2) الأنبياء : 102. ( 3) الأنبياء : 99. إِذا قَوْمُكَ مِنْهُ يَصِدُّونَ (57) وَقالُوا أَ آلِهَتُنا خَيْرٌ أَمْ هُوَ ما ضَرَبُوهُ لَكَ إِلاَّ جَدَلاً بَلْ هُمْ قَوْمٌ خَصِمُونَ (58) إِنْ هُوَ إِلاَّ عَبْدٌ أَنْعَمْنا عَلَيْهِ وَجَعَلْناهُ مَثَلاً لِبَنِي إِسْرائِيلَ (59) وَلَوْ نَشاءُ لَجَعَلْنا مِنْكُمْ تعبدون » ( إِذا قَوْمُكَ ) يا رسول الله ، والمراد بهم الكفار ( مِنْهُ ) أي من هذا المثل ( يَصِدُّونَ ) أي يضجون ضجيج المجادلة ، لظنهم أنهم غلبوك وأبطلوا أمرك.` },
            { text: "وَلَمَّا ضُرِبَ ٱبْنُ مَرْيَمَ مَثَلًا إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ", tafsir: `` },
            { text: "وَقَالُوٓا۟ ءَأَٰلِهَتُنَا خَيْرٌ أَمْ هُوَ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًۢا بَلْ هُمْ قَوْمٌ خَصِمُونَ", tafsir: `في جدالهم معك ( أَ آلِهَتُنا خَيْرٌ ) من عيسى ( أَمْ هُوَ ) خير ؟ فإذا كان عيسى في النار ـ كما تقول أنت يا محمد ـ فلتكن آلهتنا في النار أيضا ، فإنا راضون بمقام عيسى ( ما ضَرَبُوهُ ) أي لم يضرب هذا المثل ابن الزبعرى ( لَكَ ) يا رسول الله ( إِلَّا جَدَلاً ) فهم يريدون الجدل لا الحقيقة ، كسائر المعاندين ( بَلْ هُمْ قَوْمٌ خَصِمُونَ ) أي يريدون الخصومة والجدل لدفع الحق بالباطل. [60] ثم يأتي السياق لبيان حال عيسى ، بقول وسط بين إفراط النصارى وتفريط اليهود ( إِنْ هُوَ ) أي ما عيسى ( إِلَّا عَبْدٌ أَنْعَمْنا عَلَيْهِ ) بالنبوة ، فليس إلها ، ولا لغير رشده كاذبا ( وَجَعَلْناهُ مَثَلاً لِبَنِي إِسْرائِيلَ ) أي مثلا للدين والفضيلة ، فإن القدوة يكون مثلا به ، ألا ترى أنك تمثل للرسالة بمحمد صلى‌الله‌عليه‌وآله‌وسلم ، وللزهد بالمقدّس الأردبيلي ، وبالشقاوة بابن ملجم فإن الفرد الكامل في صفته يجعل مثلا ، وإنما كان مثلا لبني إسرائيل لأنه عليه‌السلام بعث فيهم.` },
            { text: "إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ", tafsir: `` },
            { text: "وَلَوْ نَشَآءُ لَجَعَلْنَا مِنكُم مَّلَٰٓئِكَةً فِى ٱلْأَرْضِ يَخْلُفُونَ", tafsir: `أيها الناس ( لَجَعَلْنا مِنْكُمْ ) أي بدلا منكم معاشر بني آدم مَلائِكَةً فِي الْأَرْضِ يَخْلُفُونَ (60) وَإِنَّهُ لَعِلْمٌ لِلسَّاعَةِ فَلا تَمْتَرُنَّ بِها وَاتَّبِعُونِ هذا صِراطٌ مُسْتَقِيمٌ (61) وَلا يَصُدَّنَّكُمُ الشَّيْطانُ ( مَلائِكَةً فِي الْأَرْضِ ) فإن إفناءكم وجعل الملائكة مكانكم ( يَخْلُفُونَ ) ويكونون خلفكم في الأرض ، أمر يسير علينا ، فلا يظن الكفار أن الله غير قادر على إفنائهم أو أنه لا يجد أفضل منهم ، ولذا يبقيهم.` },
            { text: "وَإِنَّهُۥ لَعِلْمٌ لِّلسَّاعَةِ فَلَا تَمْتَرُنَّ بِهَا وَٱتَّبِعُونِ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ", tafsir: `أي أن عيسى ابن مريم عليه‌السلام ( لَعِلْمٌ لِلسَّاعَةِ ) أي علامة لقرب القيامة ، فقد ورد في عدة أحاديث إن عيسى عليه‌السلام ينزل من السماء عند ظهور الحجة عليه‌السلام ويصلي به وكونه موجبا للعلم باقتراب الساعة ليس معناه أنه عليه‌السلام ينزل قرب الساعة حقيقة ، بل هو من قبيل كون رسولنا صلى‌الله‌عليه‌وآله‌وسلم من علائم الساعة ، ويحتمل أن يرجع ضمير « إنه » إلى نزول الملائكة ، أي أن النزول وقت قيامة القيامة كما قال سبحانه ( وَالْمَلَكُ عَلى أَرْجائِها ) (1) و ( وَيَوْمَ تَشَقَّقُ السَّماءُ بِالْغَمامِ وَنُزِّلَ الْمَلائِكَةُ تَنْزِيلاً ) (2) والآية بعد ـ عندي ـ من المتشابهات ، كما أنه لم يظهر لي الربط التام بين آية ( 60) وما قبلها والله العالم ( فَلا تَمْتَرُنَّ بِها ) لا تشكّون في الساعة ، فإنها آتية لا محالة ( وَاتَّبِعُونِ ) فيما آمر وأنهي ، وحذف « ياء » المتكلم للتخفيف ( هذا ) أي اتباعي وسلوك ديني ( صِراطٌ مُسْتَقِيمٌ ) موصل إلى السعادة الأبدية بأقصر خط وأسهل سلوك.` },
            { text: "وَلَا يَصُدَّنَّكُمُ ٱلشَّيْطَٰنُ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ", tafsir: `أي لا يصرفنكم ( الشَّيْطانُ ) بوساوسه عن طريق ( 1) الحاقة : 18. ( 2) الفرقان : 26. إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (62) وَلَمَّا جاءَ عِيسى بِالْبَيِّناتِ قالَ قَدْ جِئْتُكُمْ بِالْحِكْمَةِ وَلِأُبَيِّنَ لَكُمْ بَعْضَ الَّذِي تَخْتَلِفُونَ فِيهِ فَاتَّقُوا اللهَ وَأَطِيعُونِ (63) إِنَّ اللهَ هُوَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ الله ، وصراطه المستقيم ( إِنَّهُ ) أي الشيطان ( لَكُمْ ) أيها البشر ( عَدُوٌّ مُبِينٌ ) ظاهر العداوة.` },
            { text: "وَلَمَّا جَآءَ عِيسَىٰ بِٱلْبَيِّنَٰتِ قَالَ قَدْ جِئْتُكُم بِٱلْحِكْمَةِ وَلِأُبَيِّنَ لَكُم بَعْضَ ٱلَّذِى تَخْتَلِفُونَ فِيهِ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِيعُونِ", tafsir: `إلى اليهود ( بِالْبَيِّناتِ ) أي الأدلة الخارقة الواضحة كإحياء الموتى وإبراء الأكمه والأبرص ( قالَ ) لهم ( قَدْ جِئْتُكُمْ ) مرسلا إليكم ( بِالْحِكْمَةِ ) أي بالنبوة التي هي عرفان الشريعة وسائر الأمور المرتبطة بدين الناس ودنياهم ، فإن الرسول وحده يعلم موضع كل شيء ويتمكن من وضع كل شيء موضعه ، وقد سبق أن الحكمة عبارة عن وضع كل شيء في موضعه اللائق به ( وَلِأُبَيِّنَ لَكُمْ بَعْضَ الَّذِي تَخْتَلِفُونَ فِيهِ ) فقد اختلف اليهود في كثير من شريعة موسى عليه‌السلام فجاء عيسى مبينا لهم الحق في بعض تلك الاختلافات ، وإنما قال « بعض » لأن كل الاختلافات الجزئية لا يسهل إعلام أهلها بالحق فيها وهذا يظهر إذا قاس الإنسان ذلك بالاختلافات في ذات نفسه ، فإن الخطوط العامة للاختلافات يمكن بسهولة بيان الحق فيها أما الاختلافات بين كل فردين منتشرين هنا وهناك في بعض الأمور الدينية ، فلا يسهل استيعابها ، ولا يهم الداعي والمرشد بيان الحق فيها ( فَاتَّقُوا اللهَ ) أيها اليهود ، وخافوا عقابه في العصيان ( وَأَطِيعُونِ ) فيما آمركم وأنهاكم ، وحذف « الياء » للتخفيف والتنسيق.` },
            { text: "إِنَّ ٱللَّهَ هُوَ رَبِّى وَرَبُّكُمْ فَٱعْبُدُوهُ هَٰذَا صِرَٰطٌ مُّسْتَقِيمٌ", tafsir: `فلست إلها ( وَرَبُّكُمْ ) فلا إله غيره ، فقد كانت الوثنية تتحكم في بعض طوائف اليهود ( فَاعْبُدُوهُ ) وحده لا شريك له هذا صِراطٌ مُسْتَقِيمٌ (64) فَاخْتَلَفَ الْأَحْزابُ مِنْ بَيْنِهِمْ فَوَيْلٌ لِلَّذِينَ ظَلَمُوا مِنْ عَذابِ يَوْمٍ أَلِيمٍ (65) هَلْ يَنْظُرُونَ إِلاَّ السَّاعَةَ ( هذا ) الذي ذكرته من لزوم توحيد الله ، واتقائه وإطاعة رسله ( صِراطٌ مُسْتَقِيمٌ ) يوصلكم إلى السعادة الأبدية ، بلا انحراف أو تحوير. [66] وهل بقيت أمة عيسى على صفاء التوحيد كما أمر عيسى ، وصرح به في كلامه ؟ وهل بقوا أوفياء فيما حمّلهم من الشريعة ؟ كلا ! ( فَاخْتَلَفَ الْأَحْزابُ ) أي الفئات التي اتبعت عيسى عليه‌السلام ( مِنْ بَيْنِهِمْ ) أي من بين أولئك الذين أرشدهم عيسى وهداهم ، فهناك من بقي يهوديا ، ومن انحرف عن التوحيد فقال إن عيسى ثالث ثلاثة ، ومن أدخل في الشريعة ما ليس منها أو أنقص منها ، ومن حرّف الإنجيل كما شاء إلى غيرهم من الأحزاب المختلفة ( فَوَيْلٌ ) كلمة تقال لبيان سوء الحال ( لِلَّذِينَ ظَلَمُوا ) بالكفر والعصيان من هؤلاء ( مِنْ عَذابِ يَوْمٍ أَلِيمٍ ) أي عذب يوم القيامة ، المؤلم الموجع. [67] وإذ تقدم الكلام حول التوحيد ، وحول الرسالة ، يأتي السياق لبيان نتف حول المعاد ـ كما هي القاعدة في بيان الأحوال الثلاثة ، في القرآن الحكيم ـ ( هَلْ يَنْظُرُونَ ) أي هل ينتظر هؤلاء الكفار ( إِلَّا السَّاعَةَ ) ؟ بمعنى ماذا ينتظرون بعد قيام الحجة عليهم ، إلا أن تقوم عليهم القيامة ، فيعذبون بكفرهم ؟ وهذا تهديد لهم ، كما تقول لمن أمرته فعصى : هل تنتظر إلا العقوبة ؟ يعني أنك بعصيانك يكون حالك كحال من ينتظر العقاب ، وإلا فلما ذا تعصي ؟ ، والإتيان بلفظ أَنْ تَأْتِيَهُمْ بَغْتَةً وَهُمْ لا يَشْعُرُونَ (66) الْأَخِلاَّءُ يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلاَّ الْمُتَّقِينَ (67) يا عِبادِ لا خَوْفٌ عَلَيْكُمُ الْيَوْمَ وَلا أَنْتُمْ تَحْزَنُونَ (68) الَّذِينَ آمَنُوا بِآياتِنا وَكانُوا مُسْلِمِينَ (69) « ينظرون » لنكته هي أن المنتظر يأخذ في النظر إلى المحل المترقب ، إذا قرب وقت المجيء ، فكأن كل شيء تمّ بالنسبة إلى هؤلاء الكفار ، وقد قرب وقت العذاب ، فهم ينظرون إلى محلّه متى يأتيهم ( أَنْ تَأْتِيَهُمْ بَغْتَةً ) أي فجأة بلا سابق إنذار ( وَهُمْ لا يَشْعُرُونَ ) وقت مجيئه حتى يتوبوا ويستعدوا له.` },
            { text: "فَٱخْتَلَفَ ٱلْأَحْزَابُ مِنۢ بَيْنِهِمْ فَوَيْلٌ لِّلَّذِينَ ظَلَمُوا۟ مِنْ عَذَابِ يَوْمٍ أَلِيمٍ", tafsir: `` },
            { text: "هَلْ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ", tafsir: `` },
            { text: "ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ", tafsir: `جمع خليل ، وهو الصديق ، ( يَوْمَئِذٍ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ ) لما يرى كل واحد منهم من العذاب لأجل تلك المصادقة ( إِلَّا الْمُتَّقِينَ ) الذين آمنوا واتقوا الكفر والمعاصي ، فإنهم لا يتعادون هناك ، إذ لم يترتب على صداقتهم عذاب أو نكال ، بل بالعكس من ذلك فإن التصادق في الله يوجب الثواب والأجر. [69] ويخاطب الله المتقين في ذلك بقوله ( يا عِبادِ ) جمع عبد ، وحذف الياء للتخفيف ( لا خَوْفٌ عَلَيْكُمُ الْيَوْمَ ) من العقاب ( وَلا أَنْتُمْ تَحْزَنُونَ ) لفوات الثواب من أيديكم. [70] ثم وصف العباد ، ليعلم من هم ؟ بقوله ( الَّذِينَ آمَنُوا ) بالله ورسوله واليوم الآخر وما يلزم الإيمان به ( بِآياتِنا ) أي بحججنا وأدلتنا ( وَكانُوا مُسْلِمِينَ ) لأوامرنا ، بأن صحت عقيدتهم ، وحسن عملهم. ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَأَزْواجُكُمْ تُحْبَرُونَ (70) يُطافُ عَلَيْهِمْ بِصِحافٍ مِنْ ذَهَبٍ وَأَكْوابٍ وَفِيها ما تَشْتَهِيهِ الْأَنْفُسُ وَتَلَذُّ الْأَعْيُنُ وَأَنْتُمْ فِيها خالِدُونَ (71) وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوها بِما كُنْتُمْ تَعْمَلُونَ (72) لَكُمْ فِيها فاكِهَةٌ` },
            { text: "يَٰعِبَادِ لَا خَوْفٌ عَلَيْكُمُ ٱلْيَوْمَ وَلَآ أَنتُمْ تَحْزَنُونَ", tafsir: `` },
            { text: "ٱلَّذِينَ ءَامَنُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ مُسْلِمِينَ", tafsir: `` },
            { text: "ٱدْخُلُوا۟ ٱلْجَنَّةَ أَنتُمْ وَأَزْوَٰجُكُمْ تُحْبَرُونَ", tafsir: `المؤمنات ( تُحْبَرُونَ ) أي تسرون فيها سرورا يظهر على وجوهكم أثره ، فإن الحبور هو السرور الذي يظهر أثره في الوجه.` },
            { text: "يُطَافُ عَلَيْهِم بِصِحَافٍ مِّن ذَهَبٍ وَأَكْوَابٍ وَفِيهَا مَا تَشْتَهِيهِ ٱلْأَنفُسُ وَتَلَذُّ ٱلْأَعْيُنُ وَأَنتُمْ فِيهَا خَٰلِدُونَ", tafsir: `أي يطوف عليهم الولدان المخلدون ومعنى الطواف أن يدور فيهم لإسقائهم وإطعامهم ، كما يدور الساقي ( بِصِحافٍ ) جمع صحفة وهي الجام الذي يؤكل فيه الطعام ( مِنْ ذَهَبٍ ) فيها أنواع الأطعمة ( وَأَكْوابٍ ) جمع كوب وهو ظرف يشرب فيه الماء ( وَفِيها ) أي في الجنة ( ما تَشْتَهِيهِ الْأَنْفُسُ ) من أنواع الملذات ( وَتَلَذُّ الْأَعْيُنُ ) بالنظر إليه ( وَأَنْتُمْ فِيها خالِدُونَ ) باقون أبد الآبدين بلا زوال أو تنقل.` },
            { text: "وَتِلْكَ ٱلْجَنَّةُ ٱلَّتِىٓ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `التي وصفناها هي ( الْجَنَّةُ الَّتِي أُورِثْتُمُوها بِما كُنْتُمْ تَعْمَلُونَ ) أي انتقلت إليكم ، كالإرث الذي ينقل إلى الإنسان ، وإنما أورثوا الجنة بسبب أعمالهم الصالحة في الدنيا ، والظاهر أن هذا كلام يقال لأهل الجنة على سبيل التكريم لهم ، وإنما جاء بلفظ « تلك » للبعيد دون « هذه » تنزيلا للرفيع منزلة ، البعيد حسّا ـ كما قالوا : في ذلك الكتاب ـ .` },
            { text: "لَكُمْ فِيهَا فَٰكِهَةٌ كَثِيرَةٌ مِّنْهَا تَأْكُلُونَ", tafsir: `أيها المتقون المسلمون ( فِيها ) أي في الجنة ( فاكِهَةٌ ) أي كَثِيرَةٌ مِنْها تَأْكُلُونَ (73) إِنَّ الْمُجْرِمِينَ فِي عَذابِ جَهَنَّمَ خالِدُونَ (74) لا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ (75) وَما ظَلَمْناهُمْ وَلكِنْ كانُوا هُمُ الظَّالِمِينَ (76) وَنادَوْا يا مالِكُ لِيَقْضِ عَلَيْنا رَبُّكَ قالَ إِنَّكُمْ ماكِثُونَ (77) لَقَدْ ثمرة ( كَثِيرَةٌ ) بلا انقطاع أو قلة ( مِنْها تَأْكُلُونَ ) لأنها لكثرتها لا تؤكل كلها ، وإنما يؤكل « منها » أي بعضها. [75] وفي مقابل هؤلاء ، الكفار والعصاة الذين أجرموا في الحياة ( إِنَّ الْمُجْرِمِينَ فِي عَذابِ جَهَنَّمَ خالِدُونَ ) وهذا لمن عاند الحق ، وأما العاصي الذي تدركه الشفاعة فإنه يخرج من النار لا كالمعاند الذي ينتهي أمره.` },
            { text: "إِنَّ ٱلْمُجْرِمِينَ فِى عَذَابِ جَهَنَّمَ خَٰلِدُونَ", tafsir: `` },
            { text: "لَا يُفَتَّرُ عَنْهُمْ وَهُمْ فِيهِ مُبْلِسُونَ", tafsir: `من الفتور ، بمعنى التخفيف ، لا يخفف ( عَنْهُمْ ) العذاب ( وَهُمْ فِيهِ ) أي في العذاب ( مُبْلِسُونَ ) أي آيسون ، وهذا من أعظم المصائب ، إذ الراجي له راحة القلب ـ نوعا ما ـ بينما أن الآيس منقطع ، لا يرى إلا دوام العذاب ، مما يزيده ألما وحزنا.` },
            { text: "وَمَا ظَلَمْنَٰهُمْ وَلَٰكِن كَانُوا۟ هُمُ ٱلظَّٰلِمِينَ", tafsir: `بتعذيبهم في النار ( وَلكِنْ كانُوا هُمُ الظَّالِمِينَ ) لأنفسهم حيث عملوا في الدنيا ما استحقوا به العقاب.` },
            { text: "وَنَادَوْا۟ يَٰمَٰلِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُم مَّٰكِثُونَ", tafsir: `أي أهل النار ( يا مالِكُ ) وهو خازن جهنم ( لِيَقْضِ عَلَيْنا رَبُّكَ ) أي اسأل ربك أن يميتنا نتخلص ونستريح من هذا العذاب ( قالَ ) مالك في جوابهم ( إِنَّكُمْ ماكِثُونَ ) أي باقون في النار فلا موت بعد هذا أبدا. [79] ثم يذكّرهم سبحانه ـ في الدنيا ـ بأنه أرشدهم ولكن لم يقبلوا ( لَقَدْ جِئْناكُمْ بِالْحَقِّ وَلكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كارِهُونَ (78) أَمْ أَبْرَمُوا أَمْراً فَإِنَّا مُبْرِمُونَ (79) أَمْ يَحْسَبُونَ أَنَّا لا نَسْمَعُ سِرَّهُمْ وَنَجْواهُمْ بَلى وَرُسُلُنا لَدَيْهِمْ يَكْتُبُونَ (80) قُلْ إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ (81) جِئْناكُمْ بِالْحَقِ ) أي أرسلنا إليكم ما هو حق من أمر الرسل والكتب والشرائع ( وَلكِنَّ أَكْثَرَكُمْ ) معاشر الناس ( لِلْحَقِّ كارِهُونَ ) لما ألفتم من الباطل فصعب عليكم مفارقته إلى العمل بالحق واتباعه.` },
            { text: "لَقَدْ جِئْنَٰكُم بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَكُمْ لِلْحَقِّ كَٰرِهُونَ", tafsir: `` },
            { text: "أَمْ أَبْرَمُوٓا۟ أَمْرًا فَإِنَّا مُبْرِمُونَ", tafsir: `؟ أي بل إن هؤلاء عوض اتباعهم للحق جعلوا يحيكون المؤامرات ضد الحق ، من الإبرام ، وهو الإحكام في العمل ، والقتل ( فَإِنَّا مُبْرِمُونَ ) أي إنا محكمون أمرنا في إعلاء كلمتنا ومجازات هؤلاء.` },
            { text: "أَمْ يَحْسَبُونَ أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَىٰهُم بَلَىٰ وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ", tafsir: `أي بل يظن هؤلاء ـ حين يدبرون المكر والمؤامرة ـ ( أَنَّا لا نَسْمَعُ سِرَّهُمْ وَنَجْواهُمْ ) ما يضمرون في أنفسهم وما يتناجى بعضهم مع بعض ( بَلى ) نسمع السر والنجوى ، وإطلاق السماع على السر ـ المضمر في القلب ـ باعتبار الجوار للنجوى ، وإلا فالسر يعلم ، لا أنه يسمع ( وَرُسُلُنا ) أي الملائكة الحفظة ( لَدَيْهِمْ يَكْتُبُونَ ) ما يسرون ويتناجون. [82] ولقد كان هؤلاء الكفار بمختلف أشكالهم يزعمون أن لله ولدا ، أما المسيح أو الملائكة ، أو عزيز فجاء السياق لنفي الولد ( قُلْ ) يا رسول الله لهؤلاء ( إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) لذلك ، باعتبار أنه جزء من الإله ، فهو إله يستحق العبادة ، وإنما قال « أول العابدين » لأن سُبْحانَ رَبِّ السَّماواتِ وَالْأَرْضِ رَبِّ الْعَرْشِ عَمَّا يَصِفُونَ (82) فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ (83) وَهُوَ الَّذِي فِي السَّماءِ إِلهٌ وَفِي الْأَرْضِ إِلهٌ وَهُوَ الْحَكِيمُ الْعَلِيمُ (84) الرسول حيث إنه أعرف الناس بالله وشؤونه لا بد وأن يكون أسرع الناس إلى عبادة ولد الله ، لا يخفى ان الجملة الشرطية لا تنافي استحالة الطرفين ـ كما ذكروا ـ .` },
            { text: "قُلْ إِن كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا۠ أَوَّلُ ٱلْعَٰبِدِينَ", tafsir: `` },
            { text: "سُبْحَٰنَ رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ", tafsir: `أي أنزه الله تنزيها عن هذا القول ، فسبحان مصدر منصوب بفعل مقدر أي أسبح سبحان ( رَبِّ الْعَرْشِ ) جيء بهذا الوصف للدلالة على عظم مقامه سبحانه فكيف يمكن أن يتخذ ولدا ( عَمَّا يَصِفُونَ ) أي يصف هؤلاء المشركون الله سبحانه به فيقولون « له ولد » .` },
            { text: "فَذَرْهُمْ يَخُوضُوا۟ وَيَلْعَبُوا۟ حَتَّىٰ يُلَٰقُوا۟ يَوْمَهُمُ ٱلَّذِى يُوعَدُونَ", tafsir: `أي دعهم يا رسول الله ( يَخُوضُوا ) في باطلهم ، وأصل الخوض هو الارتماس في الماء ، ويسمى المحدّث الذي غرق في الحديث خائضا ـ تشبيها ـ ( وَيَلْعَبُوا ) في الدنيا ، فإن أعمالهم الدنيوية لعب ـ إذ هي مثله في عدم الفائدة والفناء بسرعة ـ ( حَتَّى يُلاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ ) فيه بعذاب الأبد ، وهو يوم القيامة ، وهذا تهديد لهم.` },
            { text: "وَهُوَ ٱلَّذِى فِى ٱلسَّمَآءِ إِلَٰهٌ وَفِى ٱلْأَرْضِ إِلَٰهٌ وَهُوَ ٱلْحَكِيمُ ٱلْعَلِيمُ", tafsir: `وحده إله الكون كله لا إله سواه ولدا كان أو شريكا فهو ( الَّذِي فِي السَّماءِ ) هو ( إِلهٌ ) بلا شريك ( وَفِي الْأَرْضِ ) هو ( إِلهٌ ) بلا شريك ، ( وَهُوَ الْحَكِيمُ ) في جميع أفعاله ، بمعنى أن كلّا من خلقه وتشريعه حسب الحكمة والصلاح ( الْعَلِيمُ ) بمصالح عباده ، وقد سبق وَتَبارَكَ الَّذِي لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُما وَعِنْدَهُ عِلْمُ السَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ (85) وَلا يَمْلِكُ الَّذِينَ يَدْعُونَ مِنْ دُونِهِ الشَّفاعَةَ إِلاَّ مَنْ شَهِدَ بِالْحَقِّ وَهُمْ يَعْلَمُونَ (86) أن العلم والحكمة أمران فرب عالم غير حكيم ورب حكيم غير عالم ، إذ الحكمة ملكة وضع الأشياء مواضعها وتلك تجتمع مع العلم كما يمكن أن توجد بدونه.` },
            { text: "وَتَبَارَكَ ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا وَعِندَهُۥ عِلْمُ ٱلسَّاعَةِ وَإِلَيْهِ تُرْجَعُونَ", tafsir: `أي دامت بركته ، وإنمائه للخيرات ( الَّذِي لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُما ) من ملك وإنسان وهواء وغيرها ، فلا منازع له ، ولا شريك ولا ولد ( وَعِنْدَهُ عِلْمُ السَّاعَةِ ) فهو وحده يعلم وقت قيام القيامة ( وَإِلَيْهِ تُرْجَعُونَ ) أي إلى حسابه وجزائه ترجعون أنتم أيها البشر بعد الموت. [87] فهو وحده إله مالك خالق ، لا شأن للأصنام في خلق أو ملك ، أما من يعبدها بزعم أنها تشفع له فهو في غلط ( وَ ) ذلك لأنه ( لا يَمْلِكُ ) الأصنام ( الَّذِينَ يَدْعُونَ ) هؤلاء الكفار لهم ( مِنْ دُونِهِ ) أي من دون الله ـ وإنما جاء الاستثناء لأنهم كانوا يدعون الله أيضا ـ ( الشَّفاعَةَ ) وإنما جيء بضمير العاقل للأصنام لتنسيق الكلام بين الكفار وبين جوابهم فهم يعتبرون الأصنام عقلاء ( إِلَّا مَنْ شَهِدَ بِالْحَقِ ) وهم عيسى وعزيز والملائكة ، فإن الكفار كانوا يعبدونهم ، ولهم الشفاعة في الآخرة ، أنهم يشهدون بالحق ، وأنهم ليسوا بآلهة ، وإنما أنبياء وملائكة ( وَهُمْ يَعْلَمُونَ ) أنهم ليسوا بآلهة ، وهؤلاء لا يشفعون من جحد الحق وكفر وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَهُمْ لَيَقُولُنَّ اللهُ فَأَنَّى يُؤْفَكُونَ (87) وَقِيلِهِ يا رَبِّ إِنَّ هؤُلاءِ قَوْمٌ لا يُؤْمِنُونَ (88) فَاصْفَحْ عَنْهُمْ وَقُلْ سَلامٌ فَسَوْفَ يَعْلَمُونَ (89) به ، فلا ينتظر الكفار شفاعة الآلهة التي يعبدونها ، فأصنامهم لا تشفع إطلاقا ، والأنبياء والملائكة يشفعون لغيرهم ، لا لهم. [88] ومن عجيب الأمر أنهم يعبدون غير الله ، مع أنهم معترفون بأن الله وحده خالقهم ( وَلَئِنْ سَأَلْتَهُمْ ) أي سألت هؤلاء الكفار ـ يا رسول الله ـ ( مَنْ خَلَقَهُمْ ) ؟ وأخرجهم من العدم إلى الوجود ( لَيَقُولُنَ ) في جوابك ( اللهُ ) خلقنا ( فَأَنَّى يُؤْفَكُونَ ) أي إلى أين يصرفون بعد هذا الاعتراف ؟ والمعنى فكيف ينصرفون من عبادة الله إلى عبادة الأصنام ؟. [89] ولا يجد الرسول أمام عناد هؤلاء إلا أن يشكو ربه منهم ( وَقِيلِهِ ) أي قول الرسول ( يا رَبِّ إِنَّ هؤُلاءِ قَوْمٌ لا يُؤْمِنُونَ ) بعد أن بلغتهم وأنذرتهم وقمت بواجب الإرشاد.` },
            { text: "وَلَا يَمْلِكُ ٱلَّذِينَ يَدْعُونَ مِن دُونِهِ ٱلشَّفَٰعَةَ إِلَّا مَن شَهِدَ بِٱلْحَقِّ وَهُمْ يَعْلَمُونَ", tafsir: `` },
            { text: "وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَهُمْ لَيَقُولُنَّ ٱللَّهُ فَأَنَّىٰ يُؤْفَكُونَ", tafsir: `` },
            { text: "وَقِيلِهِۦ يَٰرَبِّ إِنَّ هَٰٓؤُلَآءِ قَوْمٌ لَّا يُؤْمِنُونَ", tafsir: `` },
            { text: "فَٱصْفَحْ عَنْهُمْ وَقُلْ سَلَٰمٌ فَسَوْفَ يَعْلَمُونَ", tafsir: `` }
        ]
    },
    44: { // سورة الدخان
        name: "الدخان",
        basmalaTafsir: ``,
        verses: [
            { text: "حمٓ", tafsir: `« حاء » و « ميم » جنس هذا الكتاب المعجز الذي عجز الجن والإنس أن يأتوا بمثله ولو كان بعضهم لبعض ظهيرا ، أو رمز بين الله وبين الرسول ، وهل ذلك تكرار لما سبق من مثل هذه اللفظة ، أو لمدلولات مختلفة ، وإن تماثلت الرموز ؟ احتمالات ، إلى غير ذلك من الأقوال في فواتح السور.` },
            { text: "وَٱلْكِتَٰبِ ٱلْمُبِينِ", tafsir: `أي قسما بهذا الكتاب ـ وهو القرآن ـ الظاهر ، وقد مرّ أن الله سبحانه يحلف بمختلف صنوف خلقه ، دلالة لعظمة كل خلق ، وإن كان في النظر أمرا هينا ، نحو « والتين والزيتون » .` },
            { text: "إِنَّآ أَنزَلْنَٰهُ فِى لَيْلَةٍ مُّبَٰرَكَةٍ إِنَّا كُنَّا مُنذِرِينَ", tafsir: `أي أنزلنا الكتاب الذي هو القرآن ( فِي لَيْلَةٍ مُبارَكَةٍ ) ذات بركة ونماء ، والمراد بها ليلة القدر ، ومحتمل ليلة القدر أربع ، التاسع عشر والواحدة والعشرين والثالث والعشرين من شهر رمضان المبارك وليلة النصف من شعبان ، فقد نزل القرآن في ليلة القدر ـ جملة واحدة ـ إلى البيت المعمور في السماء ، ثم نزل منجما إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ، مبتدأ بالسابع والعشرين من رجب يوم مبعث الرسول صلى‌الله‌عليه‌وآله‌وسلم حين نزلت سورة « اقرأ » ( إِنَّا كُنَّا مُنْذِرِينَ ) للكفار والعصاة ، بأنهم إن استمروا على كفرهم وعصيانهم عوقبوا في الآخرة بالعذاب والنار ، وقوله « إنا .. . » هو المقسم به ، لقوله ( وَالْكِتابِ الْمُبِينِ ) .` },
            { text: "فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ", tafsir: `أي في الليلة المباركة ( يُفْرَقُ ) أي يبين ويميز ويفصل ( كُلُّ أَمْرٍ حَكِيمٍ ) أي كل أمر مقدر محكم مرتبط بهذا العالم ، فإن التقديرات من العام إلى العام تجري في ليلة القدر من كل سنة ، وقد ورد متواتر أَمْراً مِنْ عِنْدِنا إِنَّا كُنَّا مُرْسِلِينَ ( 5) رَحْمَةً مِنْ رَبِّكَ إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ (6) رَبِّ السَّماواتِ وَالْأَرْضِ وَما بَيْنَهُما إِنْ كُنْتُمْ مُوقِنِينَ (7) لا إِلهَ إِلاَّ هُوَ يُحْيِي الأحاديث أن الملائكة ينزلون بتقديرات العام ، إلى الإمام الموجود بعد الرسول صلى‌الله‌عليه‌وآله‌وسلم (1) ففي دورنا هذا تنزل الملائكة في ليلة القدر على الإمام المهدي عليه‌السلام بتقديرات كل إنسان وكل أمة من العام إلى العام. [6] نأمر بذلك ( أَمْراً مِنْ عِنْدِنا ) فإننا نصدر الأوامر بالتقديرات ( إِنَّا كُنَّا مُرْسِلِينَ ) للرسل إلى الأمم ، ولذا أرسلنا محمدا صلى‌الله‌عليه‌وآله‌وسلم إلى هذه الأمة ، وزودناه بالكتاب المبين الذي أنزل في ليلة مباركة. [7] وإنما نرسل الرسل ( رَحْمَةً مِنْ رَبِّكَ ) أي نرحم الناس رحمة بالإرسال ، إذ الرسل يبيّنون للناس ما يصلحهم في دنياهم وأخراهم ( إِنَّهُ ) تعالى ( هُوَ السَّمِيعُ ) لما يتكلم به الناس ولكل صوت ( الْعَلِيمُ ) بما يفعلون ، فهو يعلم سر الناس ونجواهم ، فليحذر الناس الذين أرسل إليهم أن يخالفوا الله سبحانه.` },
            { text: "أَمْرًا مِّنْ عِندِنَآ إِنَّا كُنَّا مُرْسِلِينَ", tafsir: `` },
            { text: "رَحْمَةً مِّن رَّبِّكَ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `` },
            { text: "رَبِّ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَآ إِن كُنتُم مُّوقِنِينَ", tafsir: `أي خالقها ومربيها ( وَما بَيْنَهُما ) من الإنسان والملك والجن والأشجار وغيرها ( إِنْ كُنْتُمْ ) أيها الناس ( مُوقِنِينَ ) أي ذوي يقين وعلم ، لعلمتم بصحة هذا الخبر ، وهذا في قبال من لا يبالي ولا يتبع الأمر ليتقين ، والحاصل إن أردتم العلم برب الكون لعلمتم أن ربه هو الله.` },
            { text: "لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ ٱلْأَوَّلِينَ", tafsir: `وحده لا شريك له ( يُحْيِي ) الأموات ، كما يحي ( 1) بحار الأنوار : ج 94 ص 14. وَيُمِيتُ رَبُّكُمْ وَرَبُّ آبائِكُمُ الْأَوَّلِينَ (8) بَلْ هُمْ فِي شَكٍّ يَلْعَبُونَ (9) فَارْتَقِبْ يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ (10) يَغْشَى النَّاسَ هذا عَذابٌ أَلِيمٌ (11) رَ بَّنَا اكْشِفْ عَنَّا الْعَذابَ الأرض وغيرها ( وَيُمِيتُ ) الأحياء من إنسان وحيوان ونبات ، ومن ظن أنه يميت أحدا بواسطة القتل فقد اشتبه ، فإنه إنما يهيئ السبب كما يهيئ الزرّاع والوالد سبب الزرع والولد ، أما الزرع والولد فمن الله سبحانه ، هو ( رَبُّكُمْ ) خالقكم ومربيكم ( وَرَبُّ آبائِكُمُ الْأَوَّلِينَ ) الذين سبقوكم ، فهل يتمكن أحد أن يدعي أن المسيح أو الملائكة أو عزير أو الأصنام خلقوه ؟ كلا !` },
            { text: "بَلْ هُمْ فِى شَكٍّ يَلْعَبُونَ", tafsir: `أي هؤلاء الكفار ( فِي شَكٍ ) من التوحيد ( يَلْعَبُونَ ) بالشريعة والدين ، والمراد يفعلون فعل اللاعب ، لأنهم لا يرون للدين قيمة ولا يدركون أنه مرتبط بمصيرهم في الحياة الدنيا والآخرة.` },
            { text: "فَٱرْتَقِبْ يَوْمَ تَأْتِى ٱلسَّمَآءُ بِدُخَانٍ مُّبِينٍ", tafsir: `أي انتظر يا رسول الله ( يَوْمَ تَأْتِي السَّماءُ بِدُخانٍ مُبِينٍ ) فإن من أشراط الساعة أن يشمل العالم دخان مظلم يمكث أربعين يوما ، والمعنى أنهم إن لعبوا مقابل هذا الجد ، وشكّوا مقابل هذا الأمر المتيقّن ، فدعهم حتى يأتيهم العذاب ، في يوم القيامة.` },
            { text: "يَغْشَى ٱلنَّاسَ هَٰذَا عَذَابٌ أَلِيمٌ", tafsir: `أي يحيط ذلك الدخان ب ( النَّاسَ ) وهو من أهوال القيامة ويقال لهم ( هذا ) الذين ترون وتترقبون ( عَذابٌ أَلِيمٌ ) مؤلم وموجع لمن كفر وعصى. [13] وهناك يقولون ( رَبَّنَا اكْشِفْ عَنَّا الْعَذابَ ) أي ارفع عذاب الدخان إِنَّا مُؤْمِنُونَ (12) أَنَّى لَهُمُ الذِّكْرى وَقَدْ جاءَهُمْ رَسُولٌ مُبِينٌ (13) ثُمَّ تَوَلَّوْا عَنْهُ وَقالُوا مُعَلَّمٌ مَجْنُونٌ (14) إِنَّا كاشِفُوا الْعَذابِ قَلِيلاً إِنَّكُمْ عائِدُونَ (15) وسائر ما يترقبونه من أنواع العذاب ( إِنَّا مُؤْمِنُونَ ) بما أرسلت وبمن أرسلت.` },
            { text: "رَّبَّنَا ٱكْشِفْ عَنَّا ٱلْعَذَابَ إِنَّا مُؤْمِنُونَ", tafsir: `` },
            { text: "أَنَّىٰ لَهُمُ ٱلذِّكْرَىٰ وَقَدْ جَآءَهُمْ رَسُولٌ مُّبِينٌ", tafsir: `أي كيف يمكن أن يقبل هناك ـ في القيامة ـ تذكرهم واعترافهم وإيمانهم ؟ ( وَ ) الحال أنهم وقت كانوا في الدنيا ( قَدْ جاءَهُمْ رَسُولٌ مُبِينٌ ) ظاهر الصدق ، والمراد به محمد صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "ثُمَّ تَوَلَّوْا۟ عَنْهُ وَقَالُوا۟ مُعَلَّمٌ مَّجْنُونٌ", tafsir: `وأعرضوا عن الإيمان به وبما يقول ( وَقالُوا ) في شأنه ( مُعَلَّمٌ ) يعلمه القرآن بعض الأعجميين ( مَجْنُونٌ ) فليس نبيا بل مجنون قد علّمه بعض الناس هذا القرآن ، فيردده لا شعوريا لأطماع وغايات ، والمعنى أنه لا يفيد هناك إيمانهم وقد فات أوان الإيمان حين كانوا في الدنيا. [16] ألسنا ذكرنا أحوال هؤلاء في الآخرة ؟ وألم يطلبوا كشف العذاب ؟ فإنا نمهلهم في الدنيا قليلا ، لنرى ماذا يصنعون ؟ وسمي كشفا للعذاب مع أنهم لم يعذبوا بعد ، للتشابه لفظا ، كقوله : قالوا اقترح شيئا نجد لك طبخه قلت اطبخوا لي جبّة وقميصا ( إِنَّا كاشِفُوا الْعَذابِ ) الدخان وغيره ، والمراد بالكشف : عدم تعذيبكم فيما بقي من أعماركم ( قَلِيلاً ) في الأيام القلائل المستقبلة ما دمتم في الدنيا ( إِنَّكُمْ عائِدُونَ ) إلى الكفر والعصيان ، فكيف قلتم : إنا يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرى إِنَّا مُنْتَقِمُونَ (16) وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجاءَهُمْ رَسُولٌ كَرِيمٌ (17) أَنْ أَدُّوا إِلَيَّ عِبادَ اللهِ مؤمنون ، وها نحن نراكم عائدون في الكفر ؟ وهذا من أبلغ أساليب الالتفات المذكور في علم البلاغة فكأنه صار ما أخبر سبحانه من الدخان ، ثم طلبوا فأجيبوا ، وها هم عائدون إلى الكفر ، ومن قبيله ما يحكى عن بعض الزهاد ـ عملا ـ أنه كان يذهب إلى المقابر ، فيستلقي في قبر كأنه ميت ، ثم يفكر بالمحاسبة والعذاب والأهوال ، فيقول « رب ارجعوني » ثم يجيب ـ كأنه نداء يأتيه من الأعلى ـ أرجعناك إلى الحياة ، فيقوم ويرجع أهله شاكرا أن استجيب له ، لأن يدرك ما فات منه. [17] وليتذكر هؤلاء الكفار ( يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرى ) أصل البطش الأخذ الشديد باليد للتعذيب ، والمراد نأخذ الناس لتعذيبهم ، والبطشة الكبرى ، هي الأخذ في يوم القيامة ( إِنَّا مُنْتَقِمُونَ ) ننتقم من كل كافر وفاسق ، و « يوم » منصوب بالمقدر ، أو ب « منتقمون » .` },
            { text: "إِنَّا كَاشِفُوا۟ ٱلْعَذَابِ قَلِيلًا إِنَّكُمْ عَآئِدُونَ", tafsir: `` },
            { text: "يَوْمَ نَبْطِشُ ٱلْبَطْشَةَ ٱلْكُبْرَىٰٓ إِنَّا مُنتَقِمُونَ", tafsir: `` },
            { text: "وَلَقَدْ فَتَنَّا قَبْلَهُمْ قَوْمَ فِرْعَوْنَ وَجَآءَهُمْ رَسُولٌ كَرِيمٌ", tafsir: `أي امتحنا ، فإن الفتنة بمعنى الامتحان ( قَبْلَهُمْ ) أي قبل هؤلاء الكفار ( قَوْمَ فِرْعَوْنَ ) أي فرعون وقومه ، فإنه كثيرا ما يطلق « قوم فلان » أو « آل فلان » أو ما أشبه ، ويراد به هو وقومه وآله ( وَجاءَهُمْ رَسُولٌ كَرِيمٌ ) ذو كرامة على الله سبحانه ، وهو موسى عليه‌السلام . [19] فقال لهم ( أَنْ أَدُّوا ) أي أعطوا ، من الأداء ، كما يقال « أدّ الأمانة » ( إِلَيَّ عِبادَ اللهِ ) أي أطلقوا سراح بني إسرائيل الذين هم في أسركم ، فقد كان إِنِّي لَكُمْ رَسُولٌ أَمِينٌ (18) وَأَنْ لا تَعْلُوا عَلَى اللهِ إِنِّي آتِيكُمْ بِسُلْطانٍ مُبِينٍ (19) وَإِنِّي عُذْتُ بِرَبِّي وَرَبِّكُمْ أَنْ تَرْجُمُونِ (20) وَإِنْ لَمْ تُؤْمِنُوا لِي فَاعْتَزِلُونِ (21) فَدَعا رَبَّهُ بنو إسرائيل معذبين في سجون فرعون ، وتحت اضطهاده ، فقال له موسى أطلق سراحهم ، وهذا كقوله ( فَأَرْسِلْ مَعِيَ بَنِي إِسْرائِيلَ ) (1) ( إِنِّي لَكُمْ ) يا آل فرعون ( رَسُولٌ أَمِينٌ ) مؤتمن فيما أؤديه لا أخونكم ولا أخون الوحي ، فما أقوله كله وحي بلا زيادة أو نقصان.` },
            { text: "أَنْ أَدُّوٓا۟ إِلَىَّ عِبَادَ ٱللَّهِ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ", tafsir: `` },
            { text: "وَأَن لَّا تَعْلُوا۟ عَلَى ٱللَّهِ إِنِّىٓ ءَاتِيكُم بِسُلْطَٰنٍ مُّبِينٍ", tafsir: `أي لا تتجبّروا على الله بترك طاعته ، فكأن الكافر والعاصي يرى نفسه فوق رتبة الله ، ولذا لا يستعد أن يتبعه ويطيع أمره ( إِنِّي آتِيكُمْ ) يا آل فرعون ( بِسُلْطانٍ مُبِينٍ ) أي حجة واضحة ودليل ظاهر وهي الأدلة التي أقامها على وجود الله وسائر صفاته والخوارق التي كان مزودا بها. [21] ولما دعاهم موسى عليه‌السلام توعدوه بالقتل والرجم ـ كما هي عادة الطغاة أمام المصلحين ـ فقال لهم موسى ( وَإِنِّي عُذْتُ ) أي استجرت ولذت ( بِرَبِّي وَرَبِّكُمْ ) بخالقي وخالقكم ( أَنْ تَرْجُمُونِ ) أي ترجمونني بالحجارة ، وحذف ياء المتكلم تخفيفا وتنسيقا.` },
            { text: "وَإِنِّى عُذْتُ بِرَبِّى وَرَبِّكُمْ أَن تَرْجُمُونِ", tafsir: `` },
            { text: "وَإِن لَّمْ تُؤْمِنُوا۟ لِى فَٱعْتَزِلُونِ", tafsir: `أي لم تصدقوني فيما جئتكم به ( فَاعْتَزِلُونِ ) أي اتركوني لا لي ولا علي. [23] ولما رأى موسى أن القوم مصرون على الكفر والضلال ( فَدَعا رَبَّهُ ) ( 1) الأعراف : 106. أَنَّ هؤُلاءِ قَوْمٌ مُجْرِمُونَ (22) فَأَسْرِ بِعِبادِي لَيْلاً إِنَّكُمْ مُتَّبَعُونَ (23) وَاتْرُكِ الْبَحْرَ رَهْواً إِنَّهُمْ جُنْدٌ مُغْرَقُونَ (24) كَمْ تَرَكُوا مِنْ جَنَّاتٍ وَعُيُونٍ (25) أي ناجى ربه قائلا يا رب ( أَنَّ هؤُلاءِ قَوْمٌ مُجْرِمُونَ ) مصرون على الاجرام لا ينفع فيهم البلاغ. [24] فاستجاب الله دعائه في خلاصه من فرعون وقومه فأوحى إليه أسر يا موسى ، والإسراء هو السير ليلا ( بِعِبادِي ) أي بني إسرائيل ( لَيْلاً ) وإنما أمروا بالخروج لئلا يعلم فرعون بهم فيأخذهم عاجلا قبل الهروب والفرار ( إِنَّكُمْ مُتَّبَعُونَ ) أي أن فرعون سيتبعكم ، وهذا إما تعليل قوله « ليلا » أو مقدمة لبيان غرق فرعون وبشرى لهم ، أو حث لهم على الإسراع ، حتى لا يدركهم الطلب.` },
            { text: "فَدَعَا رَبَّهُۥٓ أَنَّ هَٰٓؤُلَآءِ قَوْمٌ مُّجْرِمُونَ", tafsir: `` },
            { text: "فَأَسْرِ بِعِبَادِى لَيْلًا إِنَّكُم مُّتَّبَعُونَ", tafsir: `` },
            { text: "وَٱتْرُكِ ٱلْبَحْرَ رَهْوًا إِنَّهُمْ جُندٌ مُّغْرَقُونَ", tafsir: `يا موسى ( الْبَحْرَ ) الذي تعبرون منه ( رَهْواً ) أي ساكنا على حاله بعد أن خرجتم منه ، بأن يبقى على حاله ذي طرق وجواد ، حتى يطمع فرعون في عبوره فيغرق. وذلك لأن ضربه بالعصي بقصد إرجاعه إلى ما كان ، كان بيد موسى ، فأمره سبحانه أن لا يفعل ذلك ( إِنَّهُمْ جُنْدٌ مُغْرَقُونَ ) أي أن فرعون وقومه الذين يتبعونكم محكوم عليهم بالغرق جزاء لكفرهم وعصيانهم. [26] وسار موسى واتبعه فرعون في البحر بجنوده ـ كما فصّل سابقا ـ فيأتي السياق ـ بعد ذلك ـ ليبن كيف أن غرقهم لم يؤثر شيئا لا في الأرض ولا في السماء ( كَمْ تَرَكُوا ) أي خلف فرعون وقومه ، بعدهم ( مِنْ جَنَّاتٍ ) جمع جنة وهي البستان ، تسمى جنة لستر أرضها بالأشجار والنخيل ( وَعُيُونٍ ) جارية. وَزُرُوعٍ وَمَقامٍ كَرِيمٍ (26) وَنَعْمَةٍ كانُوا فِيها فاكِهِينَ (27) كَذلِكَ وَأَوْرَثْناها قَوْماً آخَرِينَ (28) فَما بَكَتْ عَلَيْهِمُ السَّماءُ وَالْأَرْضُ وَما كانُوا مُنْظَرِينَ (29)` },
            { text: "كَمْ تَرَكُوا۟ مِن جَنَّٰتٍ وَعُيُونٍ", tafsir: `` },
            { text: "وَزُرُوعٍ وَمَقَامٍ كَرِيمٍ", tafsir: `جمع زرع وهو ما لا ساق له كالحنطة والشعير ( وَمَقامٍ كَرِيمٍ ) أي مجالس ومنازل فاخرة ، ذات كرامة ورفعة في الأنظار.` },
            { text: "وَنَعْمَةٍ كَانُوا۟ فِيهَا فَٰكِهِينَ", tafsir: `بفتح النون ، والغالب لغير العارف ، أن يقرأها بكسر النون ( كانُوا فِيها فاكِهِينَ ) متنعمين متلذذين ، كما يتنعم آكل الفاكهة.` },
            { text: "كَذَٰلِكَ وَأَوْرَثْنَٰهَا قَوْمًا ءَاخَرِينَ", tafsir: `أخرجناهم وأهلكناهم وبقيت دورهم ونعمهم بعدهم ( وَأَوْرَثْناها ) تلك النعم ( قَوْماً آخَرِينَ ) هم بنوا إسرائيل ، حيث رجعوا إلى مصر وصاروا فيها ملوكا وسادة.` },
            { text: "فَمَا بَكَتْ عَلَيْهِمُ ٱلسَّمَآءُ وَٱلْأَرْضُ وَمَا كَانُوا۟ مُنظَرِينَ", tafsir: `أي على آل فرعون ( السَّماءُ وَالْأَرْضُ ) وهذا كناية عن أنه لم يتغير شيء في الكون بهلاكهم ، وقد ورد أن السماء والأرض تبكيان لموت النبي والإمام والعالم والمؤمن (1) ، وبطبيعة الحال أن البكاء من جنسهما المناسب بهما ، وإن كان يحتمل البكاء حقيقة ـ وما ذلك على الله بعزيز ـ ( وَما كانُوا مُنْظَرِينَ ) أي لما حكم عليهم بالعذاب ، لم يمهلوا حتى يتوبوا ، فلا يظن الكافر أنه إذا جاء العذاب يتمكن من التوبة والاستمهال ليصلح ما فات منه. ( 1) هناك روايات حول بكاء السماء والأرض على النبي والإمام والمؤمن ، عن أبي عبد الله عليه‌السلام في قوله تعالى : ( فَما بَكَتْ عَلَيْهِمُ السَّماءُ وَالْأَرْضُ ) ، قال : لم تبك السماء على أحد منذ قتل يحيى بن زكريا عليه‌السلام حتى قتل الحسين عليه‌السلام فبكت عليه « كامل الزيارات : ص 89 » ، و ورد في مجمع البيان : ج 9 ص 109 عن الرسول صلى‌الله‌عليه‌وآله‌وسلم بكاءهما على المؤمن. وَلَقَدْ نَجَّيْنا بَنِي إِسْرائِيلَ مِنَ الْعَذابِ الْمُهِينِ (30) مِنْ فِرْعَوْنَ إِنَّهُ كانَ عالِياً مِنَ الْمُسْرِفِينَ (31) وَلَقَدِ اخْتَرْناهُمْ عَلى عِلْمٍ عَلَى الْعالَمِينَ (32) وَآتَيْناهُمْ مِنَ الْآياتِ ما فِيهِ بَلؤُا مُبِينٌ (33)` },
            { text: "وَلَقَدْ نَجَّيْنَا بَنِىٓ إِسْرَٰٓءِيلَ مِنَ ٱلْعَذَابِ ٱلْمُهِينِ", tafsir: `المؤمنين بموسى ( مِنَ الْعَذابِ الْمُهِينِ ) عذاب فرعون الذي كان يهينهم ويذلهم ، من قتل الأبناء واستحياء النساء.` },
            { text: "مِن فِرْعَوْنَ إِنَّهُۥ كَانَ عَالِيًا مِّنَ ٱلْمُسْرِفِينَ", tafsir: `الذي كان يأمر بتعذيبهم ( إِنَّهُ كانَ عالِياً ) أي متجبرا متكبرا ( مِنَ الْمُسْرِفِينَ ) يسرف ويتجاوز الحد في الظلم والتعذيب.` },
            { text: "وَلَقَدِ ٱخْتَرْنَٰهُمْ عَلَىٰ عِلْمٍ عَلَى ٱلْعَٰلَمِينَ", tafsir: `أي اخترنا بني إسرائيل ( عَلى عِلْمٍ ) أي على بصيرة منا باستحقاقهم ، لا اختيارا اعتباطيا ( عَلَى الْعالَمِينَ ) أي عوالم زمانهم ، فإنهم كانوا مختارين على سائر الكفار في زمانهم ، لأنهم كانوا مؤمنين ، وغيرهم كانوا كفارا ، وهذا كما يقول : الشريف الفلاني أكبر أشراف العالم ، يريد أشراف زمانه لا كلّ شريف كان أو سيكون.` },
            { text: "وَءَاتَيْنَٰهُم مِّنَ ٱلْـَٔايَٰتِ مَا فِيهِ بَلَٰٓؤٌا۟ مُّبِينٌ", tafsir: `أي أعطيناهم ، والنسبة إليهم باعتبار إعطاء موسى عليه‌السلام ، كما يقول الملك : أعطيت القبيلة الفلانية كذا وكذا ، فيما إذا أعطى رئيسها ( مِنَ الْآياتِ ) الخارقة ( ما فِيهِ بَلؤُا مُبِينٌ ) أي امتحان ظاهر ، حتى يكون المؤمن على بصيرة ، والكافر عن عناد يستحق العقاب الأليم ، وهي مثل العصا واليد وفلق البحر ، وتضليل الغمام ، والمن والسلوى وغيرها. [35] وبعد التكلم عن التوحيد والرسالة ـ في بعض جوانبها ـ يأتي السياق إِنَّ هؤُلاءِ لَيَقُولُونَ (34) إِنْ هِيَ إِلاَّ مَوْتَتُنَا الْأُولى وَما نَحْنُ بِمُنْشَرِينَ (35) فَأْتُوا بِآبائِنا إِنْ كُنْتُمْ صادِقِينَ (36) أَ هُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَالَّذِينَ مِنْ قَبْلِهِمْ أَهْلَكْناهُمْ إِنَّهُمْ كانُوا مُجْرِمِينَ (37) لذكر المعاد ( إِنَّ هؤُلاءِ ) الكفار المعاصرون لك يا رسول الله ( لَيَقُولُونَ ) منكرين للمعاد.` },
            { text: "إِنَّ هَٰٓؤُلَآءِ لَيَقُولُونَ", tafsir: `` },
            { text: "إِنْ هِىَ إِلَّا مَوْتَتُنَا ٱلْأُولَىٰ وَمَا نَحْنُ بِمُنشَرِينَ", tafsir: `أي ما العاقبة ونهاية الأمر ( إِلَّا مَوْتَتُنَا الْأُولى ) التي تزيل حياتنا ( وَما نَحْنُ بِمُنْشَرِينَ ) أي بمبعوثين ، فليس للإنسان موتتان وحياتان ، كما تقولون أنتم أيها المؤمنون ، وإنما قالوا « الأولى » مع أنهم لا يعتقدون بموتة أخرى ، لتوحيد السياق مع كلام المؤمنين الذين كانوا يحاجوهم.` },
            { text: "فَأْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `أيها المؤمنون المدّعون للبعث ( بِآبائِنا ) الذين ماتوا من قبلنا ( إِنْ كُنْتُمْ صادِقِينَ ) في مقالكم أن الإنسان يبعث بعد الموت ، ولكن كلامهم تافه إلى أبعد الحدود ، إن المؤمنين لم يدعوا أنهم يعيدون الأموات وإنما ادعوا إعادة الله لهم عند القيامة ، فأي ربط بين الكلامين ؟ ولذا لم يأت السياق لجوابه ، فإن جواب المعاند السكوت.` },
            { text: "أَهُمْ خَيْرٌ أَمْ قَوْمُ تُبَّعٍ وَٱلَّذِينَ مِن قَبْلِهِمْ أَهْلَكْنَٰهُمْ إِنَّهُمْ كَانُوا۟ مُجْرِمِينَ", tafsir: `أي هل هؤلاء الكفار خير من حيث كثرة الأموال والجيوش والقوة ( أَمْ قَوْمُ تُبَّعٍ ) وقد كان تبع ملكا مؤمنا ، وقومه كافرين ، وكانوا كثيري الأموال والقوى ( وَالَّذِينَ مِنْ قَبْلِهِمْ ) كعاد وثمود وقوم لوط وغيرهم ؟ و الجواب مقدّر ، أي أن أولئك كانوا خيرا من هؤلاء ، ومع ذلك ( أَهْلَكْناهُمْ ) لما كفروا بالله وعصوا رسله ل ( إِنَّهُمْ كانُوا مُجْرِمِينَ ) وهذا تهديد لهؤلاء بأن مصيرهم مصير أولئك وَما خَلَقْنَا السَّماواتِ وَالْأَرْضَ وَما بَيْنَهُما لاعِبِينَ (38) ما خَلَقْناهُما إِلاَّ بِالْحَقِّ وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ (39) إِنَّ يَوْمَ الْفَصْلِ مِيقاتُهُمْ أَجْمَعِينَ (40) يَوْمَ لا يُغْنِي مَوْلًى عَنْ إن تمادوا في الكفر والطغيان.` },
            { text: "وَمَا خَلَقْنَا ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَمَا بَيْنَهُمَا لَٰعِبِينَ", tafsir: `من صنوف الخلق ( لاعِبِينَ ) أي بلا غرض وغاية كما يفعل اللاعب ، حتى نترك هؤلاء يلعبون ، كما سبق ( بَلْ هُمْ فِي شَكٍّ يَلْعَبُونَ ) (1) .` },
            { text: "مَا خَلَقْنَٰهُمَآ إِلَّا بِٱلْحَقِّ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", tafsir: `لأجل غاية هي إطاعة البشر ، كما قال تعالى في الحديث « خلقت الخلق لأجلك وخلقتك لأجلي » وفي القرآن الحكيم ( وَما خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ ) (2) ( وَلكِنَّ أَكْثَرَهُمْ ) أي أكثر الناس وهم الكفار ( لا يَعْلَمُونَ ) أن الخلق بالحق ، بل يظنون أنه صدفة فلا غاية ولا غرض ، ولكل امرئ ما يشاء أن يعمل. [41] وإذا كان الخلق بالحق ، قرر هناك يوم للحساب والجزاء ـ كما أن لأجل ذلك أيضا نزلت الكتب وشرعت الشرائع ـ ( إِنَّ يَوْمَ الْفَصْلِ ) وهو يوم القيامة الذي يفصل فيه بين المحق والمبطل ، وبين أهل الجنة وأهل النار ( مِيقاتُهُمْ ) أي وقت حساب الناس ( أَجْمَعِينَ ) بلا تخلف أحد منهم عن ذلك الموعد. [42] ثم وصف ذلك اليوم بأنه يوم عجيب لا يفيد فيه إلا رحم الله سبحانه التابع للإيمان والعمل الصالح ( يَوْمَ لا يُغْنِي مَوْلًى عَنْ ( 1) الدخان : 10. ( 2) الذاريات : 57. مَوْلًى شَيْئاً وَلا هُمْ يُنْصَرُونَ (41) إِلاَّ مَنْ رَحِمَ اللهُ إِنَّهُ هُوَ الْعَزِيزُ الرَّحِيمُ (42) إِنَّ شَجَرَةَ الزَّقُّومِ (43) طَعامُ الْأَثِيمِ (44) كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ (45) كَغَلْيِ الْحَمِيمِ (46) خُذُوهُ مَوْلًى شَيْئاً ) المراد بالمولى هنا الصاحب ، سمي به لأنه يتولى شؤون صاحبه أي لا ينفع صاحب لصاحبه ، أصلا ( وَلا هُمْ ) أي الناس ( يُنْصَرُونَ ) بأن ينصرهم أحد لإنقاذهم من عذاب الله ، فيما استحقوا العذاب.` },
            { text: "إِنَّ يَوْمَ ٱلْفَصْلِ مِيقَٰتُهُمْ أَجْمَعِينَ", tafsir: `` },
            { text: "يَوْمَ لَا يُغْنِى مَوْلًى عَن مَّوْلًى شَيْـًٔا وَلَا هُمْ يُنصَرُونَ", tafsir: `` },
            { text: "إِلَّا مَن رَّحِمَ ٱللَّهُ إِنَّهُۥ هُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ", tafsir: `أي تفضل عليه سبحانه بغفران ذنبه ، وإدراكه الشفاعة ، بعد أن كان قابلا لذلك ، بالإيمان الصحيح ( إِنَّهُ ) سبحانه ( هُوَ الْعَزِيزُ ) الغالب على أمره فلا يرد بأسه عن أحد استحقه ( الرَّحِيمُ ) بالمؤمنين. [44] ثم بين سبحانه مقام كل من الفريقين هناك ، فقال ( إِنَّ شَجَرَةَ الزَّقُّومِ ) وهي شجرة تعطي ثمارا بشعة مرة.` },
            { text: "إِنَّ شَجَرَتَ ٱلزَّقُّومِ", tafsir: `` },
            { text: "طَعَامُ ٱلْأَثِيمِ", tafsir: `أي من كثرت آثامه ومعاصيه ، فإن « أثيم » فعيل من « الإثم » .` },
            { text: "كَٱلْمُهْلِ يَغْلِى فِى ٱلْبُطُونِ", tafsir: `وهو النحاس المذاب ـ أو ما أشبه ( يَغْلِي فِي الْبُطُونِ ) أي إذا أكله الأثيم غلى وفار في بطنه من شدة الحرارة.` },
            { text: "كَغَلْىِ ٱلْحَمِيمِ", tafsir: `أي مثل غلي الماء الحار الشديد الحرارة. [48] ثم يقال للزبانية الموكلين بالنار ( خُذُوهُ ) أي خذوا هذا الأثيم فَاعْتِلُوهُ إِلى سَواءِ الْجَحِيمِ (47) ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذابِ الْحَمِيمِ (48) ذُقْ إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ (49) إِنَّ هذا ما كُنْتُمْ بِهِ تَمْتَرُونَ (50) إِنَّ الْمُتَّقِينَ فِي مَقامٍ أَمِينٍ (51) ( فَاعْتِلُوهُ ) يقال « عتله » إذا دفعه بشدة وعنف ، أي فادفعوه من أطراف النار ( إِلى سَواءِ الْجَحِيمِ ) أي في وسط النار ، حيث العذاب والألم أكثر ، وسمي وسط الشيء سواء ، لاستواء المسافة بينه وبين أطرافه المحيطة به.` },
            { text: "خُذُوهُ فَٱعْتِلُوهُ إِلَىٰ سَوَآءِ ٱلْجَحِيمِ", tafsir: `` },
            { text: "ثُمَّ صُبُّوا۟ فَوْقَ رَأْسِهِۦ مِنْ عَذَابِ ٱلْحَمِيمِ", tafsir: `للتعذيب والإهانة ( مِنْ عَذابِ الْحَمِيمِ ) أي الماء الحار الشديد الحرارة ، فهو في وسط النار ، وفي بطنه زقوم يغلي ، وعلى رأسه يصب الماء الحار. [50] ويقال له لإذلاله في مقابل كبريائه في الدنيا ( ذُقْ ) هذا العذاب ( إِنَّكَ أَنْتَ الْعَزِيزُ الْكَرِيمُ ) فإن الكفار يقولون في الدنيا ، بلسان حالهم ، أو لفظا ، إننا أعزاء كرماء فكيف نتبع الدين ؟ فيقال لهم هذا القول هناك على وجه السخرية والاستهزاء ، و قد ورد أن أبا جهل قال للرسول صلى‌الله‌عليه‌وآله‌وسلم : ما بين جبليها أعز ولا أكرم مني ، فنزلت هذه الآية. [51] ثم يقال لهم ( إِنَّ هذا ) العذاب والجزاء ( ما كُنْتُمْ ) أيها الكفار ( بِهِ تَمْتَرُونَ ) أي تشكون في دار الدنيا ، فذوقوه الآن جزاء لشككم وإصراركم على الكفر والعناد. [52] ولننظر إلى مقام المؤمنين الورعين هناك ( إِنَّ الْمُتَّقِينَ ) الذين اتقوا الكفر والمعاصي في دار الدنيا ( فِي مَقامٍ أَمِينٍ ) أي في محل مأمون فِي جَنَّاتٍ وَعُيُونٍ (52) يَلْبَسُونَ مِنْ سُندُسٍ وَإِسْتَبْرَقٍ مُتَقابِلِينَ (53) كَذلِكَ وَزَوَّجْناهُمْ بِحُورٍ عِينٍ (54) يَدْعُونَ فِيها بِكُلِّ فاكِهَةٍ آمِنِينَ (55) لا يَذُوقُونَ فِيهَا الْمَو ْتَ إِلاَّ الْمَوْتَةَ الْأُولى من العذاب والآلام.` },
            { text: "ذُقْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْكَرِيمُ", tafsir: `` },
            { text: "إِنَّ هَٰذَا مَا كُنتُم بِهِۦ تَمْتَرُونَ", tafsir: `` },
            { text: "إِنَّ ٱلْمُتَّقِينَ فِى مَقَامٍ أَمِينٍ", tafsir: `` },
            { text: "فِى جَنَّٰتٍ وَعُيُونٍ", tafsir: `أي بساتين ( وَعُيُونٍ ) أي أنهر جارية ، أو عيون صافية ، ومعنى « في » إنهم في محل فيه « عيون » و « أشجار » .` },
            { text: "يَلْبَسُونَ مِن سُندُسٍ وَإِسْتَبْرَقٍ مُّتَقَٰبِلِينَ", tafsir: `وهو الحرير الرقيق ( وَإِسْتَبْرَقٍ ) هو الحرير الخشن ، ولكل فضل ، فالأول ألين مسا ، والثاني أكثر جمالا في العين ، في حال كونهم ( مُتَقابِلِينَ ) يقابل بعضهم بعضا في مجالسهم ، يتحدثون هناك ، ولا تأخذهم وحشة الانفراد.` },
            { text: "كَذَٰلِكَ وَزَوَّجْنَٰهُم بِحُورٍ عِينٍ", tafsir: `حال أهل الجنة ( وَزَوَّجْناهُمْ بِحُورٍ ) جمع « حوراء » وهي المرأة البيضاء الملائكية الجميلة ( عِينٍ ) جمع عيناء ، وهي من وسعت حدقتها ، وذلك مما يزيد من جمال المرأة.` },
            { text: "يَدْعُونَ فِيهَا بِكُلِّ فَٰكِهَةٍ ءَامِنِينَ", tafsir: `أي يطلبون في الجنات ( بِكُلِ ) قسم من ال ( فاكِهَةٍ ) أي الثمرة ( آمِنِينَ ) أي في حال كونهم لا يخافون نفادها أو ضررها ، أو المراد مطلق الأمان من كل مكروه ، وكرر ذلك لأهميته.` },
            { text: "لَا يَذُوقُونَ فِيهَا ٱلْمَوْتَ إِلَّا ٱلْمَوْتَةَ ٱلْأُولَىٰ وَوَقَىٰهُمْ عَذَابَ ٱلْجَحِيمِ", tafsir: `فهم خالدون في ذلك النعيم أبد الآبدين ، وقد شبه الموت بالمعلومات ، ولذا نسب إليه الذوق ( إِلَّا الْمَوْتَةَ الْأُولى ) استثناء منقطع ، إذ الموتة الأولى إنما هي في دار الدنيا ، وَوَقاهُمْ عَذابَ الْجَحِيمِ (56) فَضْلاً مِنْ رَبِّكَ ذلِكَ هُوَ الْفَوْزُ الْعَظِيمُ (57) فَإِنَّما يَسَّرْناهُ بِلِسانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ (58) فَارْتَقِبْ إِنَّهُمْ مُرْتَقِبُونَ (59) والمعنى أن هؤلاء لا يلاقون الموت إلا في الدنيا ، أما في الآخرة فلا موت لهم ، وقد سبق وجه الاستثناءات المنقطعة عموما ، وأن الكلام المتقدم يفرض خاليا عن القيد ، وذلك لتكثير الفائدة ، فتنحل الجملتان إلى ثلاث جمل ( وَوَقاهُمْ ) أي حفظهم الله سبحانه ( عَذابَ الْجَحِيمِ ) فليس عدم موتهم من قبيل عدم موت أهل النار ، الذي ( يَأْتِيهِ الْمَوْتُ مِنْ كُلِّ مَكانٍ وَما هُوَ بِمَيِّتٍ ) (1) .` },
            { text: "فَضْلًا مِّن رَّبِّكَ ذَٰلِكَ هُوَ ٱلْفَوْزُ ٱلْعَظِيمُ", tafsir: `أي يتفضّل سبحانه بهذه النعم على أهل الجنة فضلا ، إذ لا يستحق أحد على الله شيئا ( ذلِكَ ) الفضل ( هُوَ الْفَوْزُ الْعَظِيمُ ) أي الفلاح والظفر بالمطلوب الذي ليس شيء أعظم منه.` },
            { text: "فَإِنَّمَا يَسَّرْنَٰهُ بِلِسَانِكَ لَعَلَّهُمْ يَتَذَكَّرُونَ", tafsir: `أي سهلنا القرآن ( بِلِسانِكَ ) العربي ، يا رسول الله ( لَعَلَّهُمْ يَتَذَكَّرُونَ ) ما أودع في فطرتهم من المبدأ والمعاد ليفوزوا بذلك الثواب وينجوا من تلك النار والعقاب.` },
            { text: "فَٱرْتَقِبْ إِنَّهُم مُّرْتَقِبُونَ", tafsir: `` }
        ]
    }
});
